window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0155", [{"word":"anxious","ipa_uk":"/ˈæŋkʃəs/","ipa_us":"/ˈæŋkʃəs/","definition_zh":"焦虑的；担忧的；令人不安的；渴望的；挂念的","definition_en":"feeling worried and tense about something uncertain, or showing or causing such worry","core_image":"深夜的候车室里，一个人反复看手机上的时间，掌心出汗，脑中不停排练还没发生的坏消息","scene":"雨夜的车站候车室里，一名考生把通知书折了又展开，晚点提示每刷新一次，他的手指就收紧一分。The anxious candidate checked the departure board every few minutes and rehearsed what could go wrong at the interview.","sceneCN":"这里 anxious 指「对可能发生的坏事持续不安」（第 1 个义项：尚未发生的不确定引发担心）；句意为这名焦虑的考生每隔几分钟就看一次发车信息，并在脑中反复演练面试可能出的岔子。","pos":[{"tag":"adj.","zh":"焦虑的；担忧的；渴望的；令人焦虑的"}],"collocations":[{"phrase":"anxious about","zh":"为……而担忧"},{"phrase":"anxious for news","zh":"急切等待消息"},{"phrase":"anxious to do","zh":"急于做某事"},{"phrase":"anxious moments","zh":"令人不安的时刻"},{"phrase":"anxious parents","zh":"过度担忧的家长"},{"phrase":"an anxious glance","zh":"不安的一瞥"}],"forms":[{"label":"比较级","form":"more anxious"},{"label":"最高级","form":"most anxious"},{"label":"副词","form":"anxiously"},{"label":"名词（焦虑）","form":"anxiety"},{"label":"名词（不安的状态）","form":"anxiousness"},{"label":"前缀派生","form":"overanxious"}],"derivatives":[{"word":"anxiety","pos":"n.","zh":"焦虑；担忧；焦虑症（拉丁名词「不安状态」直接进入英语）"},{"word":"anxiously","pos":"adv.","zh":"不安地；急切地（形容词加副词后缀，动作带上了紧张）"},{"word":"anxiousness","pos":"n.","zh":"不安；紧张（形容词加名词后缀，指状态本身）"},{"word":"overanxious","pos":"adj.","zh":"过分担忧的（前缀「过度」加本词，指担心越过了合理限度）"}],"senses":[{"no":"01","title":"Uneasy about something that may happen","titleCN":"对可能发生的事感到不安","definition":"feeling worried and tense because something uncertain may turn out badly","definitionCN":"因不确定的事可能变糟而感到担心与紧张","example":"She grew anxious as the deadline approached and no reply came.","exampleCN":"期限临近却仍无回音，她越来越不安。","why":"The Latin root means 'squeezed tight', so the body is held by a worry that has not yet arrived.","whyCN":"词根原义是「被紧紧勒住」，身体被一件尚未到来的担忧攥住了。"},{"no":"02","title":"Causing worry in others","titleCN":"使别人不安的","definition":"causing other people to feel worried or tense","definitionCN":"使他人感到担心或紧张","example":"The anxious silence in the room told us the results were bad.","exampleCN":"屋里那片令人不安的沉默告诉我们结果不好。","why":"A feeling can be transferred to a scene or a pause, so the same adjective describes what produces the worry.","whyCN":"情绪会转移到场景与停顿上，于是同一个形容词也用来形容引起担忧的事物。"},{"no":"03","title":"Eager to have something","titleCN":"急切想得到","definition":"wanting something very much and impatient to get it","definitionCN":"非常想要某物并急于得到","example":"The whole town was anxious for news of the missing climbers.","exampleCN":"全镇人都急切盼着失踪登山者的消息。","why":"The same tightened chest serves fear and desire alike: both are states of not yet having.","whyCN":"同一份勒紧的胸腔既服务于恐惧也服务于欲望：两者都是「尚未得到」的状态。"},{"no":"04","title":"Concerned for another person","titleCN":"牵挂、操心他人","definition":"showing care and concern for another person's safety or comfort","definitionCN":"对别人的安危或处境表示关心与牵挂","example":"An anxious mother waited by the phone all night.","exampleCN":"一位牵挂孩子的母亲在电话旁守了一整夜。","why":"When the worry is aimed at someone else, the word shifts from self-concern to solicitude.","whyCN":"当担忧指向别人时，这个词就从自我不安转为对他人的挂念。"},{"no":"05","title":"Restless in body","titleCN":"坐立不安的","definition":"showing physical restlessness that comes from worry","definitionCN":"表现出由担忧引起的身体上的不安","example":"He gave an anxious glance at the door and shifted in his seat.","exampleCN":"他不安地朝门口看了一眼，在座位上挪了挪身子。","why":"Because the root is a bodily squeeze, the word easily names the small movements that a squeezed body makes.","whyCN":"由于词根是身体被勒紧，这个词自然也能指被勒紧的身体做出的那些小动作。"},{"no":"06","title":"Relating to anxiety as a disorder","titleCN":"焦虑（症）的","definition":"in medicine and psychology, describing persistent excessive worry treated as a condition","definitionCN":"在医学与心理学中，形容被当作病症处理的持续过度担忧","example":"The clinic treats anxious patients with breathing training and counselling.","exampleCN":"诊所用手呼吸训练与心理咨询来治疗焦虑患者。","why":"Clinical use narrows everyday worry into a pattern that lasts and interferes with daily life.","whyCN":"临床用法把日常担忧收窄为一种持续并干扰生活的固定模式。"},{"no":"07","title":"Overprotective through worry","titleCN":"因过度担忧而管得太紧的","definition":"so worried about a possible risk that one restricts what others may do","definitionCN":"对可能的风险过分担心，因而限制他人的行动","example":"Anxious parents rarely let the children walk home alone.","exampleCN":"过度担忧的家长很少让孩子独自走回家。","why":"When worry is acted on, it becomes a form of control over other people's movements.","whyCN":"当担忧化为行动，它就变成对他人行动的一种控制。"},{"no":"08","title":"Afraid of making a small mistake","titleCN":"怕出错、拘谨的","definition":"self-conscious and nervous about doing something incorrectly","definitionCN":"对做错事过分在意而显得紧张拘谨","example":"The new intern was anxious about every word she wrote in the report.","exampleCN":"新来的实习生在报告里每写一个词都怕出错。","why":"The same tension can attach to a small social risk, where nothing terrible is at stake but the self feels exposed.","whyCN":"同一种紧张也可以附着在微小的社交风险上：并无大祸，但自我感到暴露。"}],"etymology":{"intro":{"en":"Anxious came into English from Latin anxius, an adjective built on the verb angere 'to squeeze, choke'. The word began as a description of a body held tight by worry and only later acquired its eager sense.","cn":"anxious 来自拉丁形容词 anxius，它由动词 angere「挤压、勒住」构成。这个词最初描写的是一具被担忧勒紧的身体，后来才获得「渴望」的意思。"},"items":[{"era":"LATIN ANGERE","en":"Angere meant 'to squeeze, choke, strangle'. It supplies the physical picture behind the word: a chest that cannot expand. Its descendants include the words for anguish, for a choking pain in the chest, and for a tight throat.","cn":"angere 意为「挤压、勒住、使窒息」。它提供了这个词背后的身体画面：一只无法舒展的胸腔。它的后裔包括表示「剧痛」的词、表示胸口紧缩疼痛的词，以及表示咽喉紧缩的词。"},{"era":"LATIN ANXIUS","en":"Anxius described a person troubled in mind, restless and unable to settle; it also described something that causes such a state.","cn":"anxius 描写心思受扰、坐立不安、无法安定的人；也用来形容引起这种状态的事物。"},{"era":"LATIN ANXIETAS","en":"The abstract noun anxietas named the condition itself and is the direct source of the English noun anxiety.","cn":"抽象名词 anxietas 指这种状态本身，是英语名词 anxiety 的直接来源。"},{"era":"EARLY MODERN ENGLISH","en":"Anxious entered English in the sixteenth century through learned Latin rather than through everyday French, and for a long period it meant only 'greatly troubled'.","cn":"anxious 在 16 世纪经书面的拉丁语进入英语，而不是经日常法语；在很长一段时间里它只表示「深受困扰」。"},{"era":"EAGER SENSE","en":"By the seventeenth century the word was also used with for and to in the sense of wanting something urgently, a use that strict writers still object to.","cn":"到 17 世纪，这个词也与表示对象的介词连用，表示急切想要某物；这一用法至今仍受到严格写作者的反对。"},{"era":"CLINICAL AND UNCERTAIN","en":"The clinical sense belongs to twentieth-century psychology. Source uncertain: the deeper Indo-European root proposed for angere is a reconstructed form, and no single origin can be demonstrated.","cn":"临床义属于 20 世纪的心理学。来源不确定：为 angere 提出的更深印欧词根是重构形式，无法证明唯一来源。"}]},"similar":{"note":{"en":"The first group holds words that look or sound close and are constantly mixed up with anxious; the second holds near neighbours with a different shade of worry.","cn":"第一组是与 anxious 形近或音近、极容易混淆的词；第二组是语义相近但担忧的侧重点不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"eager","ipa":"/ˈiːɡə/","tag":"not a relative","definition":"From Latin acer 'sharp, keen', a completely different root: it names strong desire without any trace of fear.","definitionCN":"来自拉丁 acer「锐利、热切」，词根完全不同：只表示强烈的愿望，没有一点恐惧。"},{"word":"nervous","ipa":"/ˈnɜːvəs/","tag":"different root","definition":"Built on Latin nervus 'sinew', so it starts from the nerves of the body rather than from a tight chest.","definitionCN":"由拉丁 nervus「筋、神经」构成，出发点是人体的神经，而不是被勒紧的胸腔。"},{"word":"angst","ipa":"/æŋst/","tag":"German cousin","definition":"A twentieth-century borrowing from German, where the same tightness image survives; it names a deeper, less object-directed dread.","definitionCN":"20 世纪从德语借入，德语里保留着同一个「勒紧」的形象；它指更深、较少指向具体对象的恐惧。"},{"word":"uneasy","ipa":"/ʌnˈiːzi/","tag":"native compound","definition":"An English compound of 'not' plus 'ease', with no Latin root at all: mild discomfort rather than active worry.","definitionCN":"由「不」加「安适」构成的英语复合词，没有拉丁词根：指轻微的不适而非主动的担忧。"}]},{"heading":"NEAR MEANING","entries":[{"word":"worried","ipa":"/ˈwʌrid/","tag":"thoughts circling","definition":"The everyday word for a mind going round the same bad possibility; it stresses thinking rather than the bodily squeeze.","definitionCN":"日常用词，指心思绕着同一个坏可能打转；强调思虑，而非身体的紧绷。"},{"word":"concerned","ipa":"/kənˈsɜːnd/","tag":"mild and caring","definition":"A cooler, more social word: it reports that something matters to you, often on another person's behalf.","definitionCN":"更冷静、更社会的词：说明某事对你重要，常是为他人而挂心。"},{"word":"apprehensive","ipa":"/ˌæprɪˈhensɪv/","tag":"aimed at the future","definition":"From Latin 'to seize upon', it points forward to a specific coming event, which anxious does not always do.","definitionCN":"来自拉丁语「抓住」，指向一个具体将要发生的事，而 anxious 未必如此。"},{"word":"solicitous","ipa":"/səˈlɪsɪtəs/","tag":"care on display","definition":"Formal and slightly old-fashioned: worry expressed as attentive care for someone's comfort.","definitionCN":"正式且略旧：把担忧表现为对他人起居的周到照料。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The old verb meant 'to squeeze the throat'; a squeezed chest is the whole image behind the word.","cn":"古动词意为「勒住喉咙」；被勒紧的胸腔就是这个词背后的全部画面。"},{"en":"The family runs anxious, anxiety, anxiously, anxiousness, overanxious.","cn":"同族词包括 anxious、anxiety、anxiously、anxiousness、overanxious。"},{"en":"Fixed phrases mark the target of the worry: anxious about a result, anxious for news, anxious to leave.","cn":"固定搭配标出担忧的对象：为结果担忧、急切等消息、急于离开。"},{"en":"A related word survives in medicine for a tight, choking pain in the chest.","cn":"同一个「勒紧」的意象还留在医学里，指胸口紧缩的疼痛。"},{"en":"Psychology separates the everyday feeling from the disorder by adding 'disorder' to the noun.","cn":"心理学在名词后加上「障碍」一词，把日常情绪与病症区分开。"}],"abstract":[{"en":"Picture a coat buttoned one size too small, so every breath becomes visible.","cn":"想象一件扣小了一号的外套，每次呼吸都看得见。"},{"en":"Picture a letter still sealed on the table, and the hand that keeps turning it over.","cn":"想象桌上那封还没拆的信，和那只不停翻动它的手。"},{"en":"Picture a clock whose hands move slower the more you watch them.","cn":"想象一只越盯着看就走得越慢的钟。"}]},"examples":[{"en":"Parents are anxious about how much time children spend on screens.","cn":"家长对孩子花在屏幕上的时间感到担忧。"},{"en":"She was anxious to know whether her application had been accepted.","cn":"她急切地想知道自己的申请是否被接受。"},{"en":"The long silence before the announcement made the whole hall anxious.","cn":"宣布前那段漫长的沉默让整个大厅的人都不安起来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「an（一）+ xious（休斯）」——心里一直悬着，一刻也歇不下 → 焦虑的、担忧的；也可记「急着想要」。","word":"anxious"},"root":"拉丁 anxius「心绪不安的」，来自 angere「挤压、勒住」；angere 更深来源不确定，常被提到的印欧词根属重构形式。同族有 anxiety、angina（心绞痛）、anguish（剧痛）。","sensesIntro":{"en":"Eight senses follow one bodily image: a chest squeezed by something not yet settled. The squeeze can be aimed at a coming event, radiate into a room, turn into desire, attach to another person, show in small movements, harden into a disorder, become control, or shrink to the fear of a tiny mistake.","cn":"八个义项沿同一个身体意象展开：胸腔被一件尚未落定的事攥住。这股挤压可以指向将发生的事、弥漫到整个房间、转为欲望、附着在别人身上、显为小动作、固化成病症、变成控制，也可以缩小为对微小错误的恐惧。"},"semanticMap":{"core":{"en":"CORE IMAGE: a chest held tight by something that has not happened yet.","cn":"核心意象：一只被尚未发生之事勒紧的胸腔。"},"chain":["PRESSED TIGHT","UNEASY ANTICIPATION","WORRY LEAVING THE BODY","WANTING IT NOW","CARE FOR ANOTHER","FEAR OF SMALL ERROR"],"branches":[{"senses":"01 · 05","en":"ONE SQUEEZE, TWO FACES: the inward feeling and the small movements it forces on the body are a single state.","cn":"一次挤压、两副面孔：内在的感受与它逼出的身体小动作是同一个状态。"},{"senses":"02 · 07","en":"WORRY LEAVING THE BODY: it fills a room with silence, or it becomes a parent's hand on the door.","cn":"担忧离开身体：它让一个房间充满沉默，或变成家长挡在门上的那只手。"},{"senses":"03","en":"DESIRE WITHOUT ARRIVAL: wanting and dreading share the shape of not yet having.","cn":"尚未抵达的欲望：想要与害怕共享「尚未得到」的形状。"},{"senses":"04","en":"AIMED AT SOMEONE ELSE: the same tension, now spent on another person's safety.","cn":"指向他人：同一种紧张，如今花在别人的安危上。"},{"senses":"06 · 08","en":"FROM FEELING TO LABEL: first a lasting condition with a name, then the small social fear of being wrong.","cn":"从感受到标签：先是一个有名字的持续状态，再是对出错的细小社交恐惧。"}]},"affixes":{"intro":{"en":"Anxious is an adjective made from a Latin root plus a very common adjective ending, and the whole family can be read morpheme by morpheme.","cn":"anxious 由拉丁词根加一个极常见的形容词词尾构成，整个词族可以按语素逐个读出。"},"latinIntro":{"en":"The squeezing root also builds the Latin noun for the condition and the Latin word for a choking pain, while the adjective ending marks 'full of, having the quality of'.","cn":"这个「挤压」词根还构成拉丁语中指该状态的名词与指窒息性疼痛的词，而形容词词尾表示「充满、具有……性质」。"},"items":[{"word":"ang-","structure":"angere (Latin verb, 'to squeeze, choke')","meaning":"to squeeze; to choke","meaningCN":"挤压；使窒息","example":"The root carries a physical grip on the chest.","exampleCN":"这个词根带着一只手攥住胸腔的感觉。"},{"word":"-ous","structure":"-ous (Latin adjective suffix, 'full of, having the quality of')","meaning":"full of; having the quality of","meaningCN":"充满……的；具有……性质的","example":"The ending turns a root into a description of a person.","exampleCN":"这个词尾把词根变成对人的描写。"},{"word":"anxious","structure":"ang- + -ous","meaning":"held tight by worry","meaningCN":"被担忧勒紧的","example":"The candidate was anxious before the interview.","exampleCN":"面试前这名考生很不安。"},{"word":"anxiety","structure":"anxious stem + -ety (noun of state)","meaning":"the state of being uneasy","meaningCN":"不安的状态","example":"Her anxiety eased once the letter arrived.","exampleCN":"信一到，她的焦虑就缓解了。"},{"word":"anxiously","structure":"anxious + -ly (adverb)","meaning":"in an uneasy way","meaningCN":"不安地","example":"He waited anxiously by the telephone.","exampleCN":"他在电话旁不安地等着。"},{"word":"anxiousness","structure":"anxious + -ness (noun of quality)","meaning":"the quality of being uneasy","meaningCN":"不安的性质","example":"The anxiousness in her voice was hard to miss.","exampleCN":"她声音里的不安很难忽略。"},{"word":"overanxious","structure":"over- + anxious","meaning":"worried beyond what is reasonable","meaningCN":"担忧过度的","example":"Overanxious coaches restrict every move.","exampleCN":"过度担忧的教练限制每一个动作。"},{"word":"anguish","structure":"anguish (noun, from a Latin word for tightness)","meaning":"severe mental or bodily pain","meaningCN":"剧烈的身心痛苦","example":"The family waited in anguish for any word.","exampleCN":"家人在痛苦中等着任何一点消息。"},{"word":"angina","structure":"angina (medical noun, from a word for strangling)","meaning":"a choking pain in the chest","meaningCN":"心绞痛；胸口紧缩的疼痛","example":"The patient described a tight pain across the chest.","exampleCN":"病人描述胸口有一阵紧缩的疼痛。"}],"latinEntries":[{"word":"angere","structure":"angere, anxi, anctum (verb, third conjugation)","meaning":"to squeeze, choke, torment","meaningCN":"挤压；勒住；折磨"},{"word":"anxius","structure":"anxius, anxia, anxium (adj.)","meaning":"uneasy, troubled, anxious","meaningCN":"不安的；受困扰的"},{"word":"anxietas","structure":"anxietas, anxietatis (f., third declension)","meaning":"uneasiness, anxiety","meaningCN":"不安；焦虑"},{"word":"angor","structure":"angor, angoris (m., third declension)","meaning":"a choking, a tightness","meaningCN":"窒息感；紧缩感"}],"derivatives":[{"word":"anxiety","pos":"n.","zh":"焦虑；担忧；焦虑症（拉丁名词「不安状态」直接进入英语）"},{"word":"anxiously","pos":"adv.","zh":"不安地；急切地（形容词加副词后缀，动作带上了紧张）"},{"word":"anxiousness","pos":"n.","zh":"不安；紧张（形容词加名词后缀，指状态本身）"},{"word":"overanxious","pos":"adj.","zh":"过分担忧的（前缀「过度」加本词，指担心越过了合理限度）"}]}},{"word":"stressful","ipa_uk":"/ˈstresfl/","ipa_us":"/ˈstresfl/","definition_zh":"压力大的；令人紧张的；消耗人的；要求过高的","definition_en":"full of pressure or tension, and therefore tiring to deal with","core_image":"桌面上三份截止日期相同的文件，电话在响，咖啡已经凉透，椅背上还搭着没来得及穿的外套","scene":"凌晨的急诊值班室里，监护仪的滴答声没有停过，一名护士刚收拾完一张床位又被叫去下一张。The stressful night shift left the nurses too tired to eat.","sceneCN":"这里 stressful 指「被压力占满、令人持续紧绷」（第 1 个义项：整体状态充满压力）；句意为这个压力极大的夜班让护士们累到吃不下东西。","pos":[{"tag":"adj.","zh":"压力大的；令人紧张的；造成紧张的"}],"collocations":[{"phrase":"stressful job","zh":"压力大的工作"},{"phrase":"stressful situation","zh":"令人紧张的处境"},{"phrase":"stressful period","zh":"压力集中的一段时期"},{"phrase":"highly stressful","zh":"压力极大的"},{"phrase":"stressful experience","zh":"令人紧张的经历"},{"phrase":"stressful for someone","zh":"对某人来说压力很大"}],"forms":[{"label":"比较级","form":"more stressful"},{"label":"最高级","form":"most stressful"},{"label":"副词","form":"stressfully"},{"label":"名词（压力）","form":"stress"},{"label":"名词（紧张程度）","form":"stressfulness"},{"label":"名词（压力源）","form":"stressor"},{"label":"动词","form":"stress"}],"derivatives":[{"word":"stress","pos":"n./v.","zh":"压力；紧张 / 强调；使紧张（拉丁词根「拉紧」，由拉紧转为压迫）"},{"word":"stressfully","pos":"adv.","zh":"在充满压力的状态下（形容词加副词后缀）"},{"word":"stressfulness","pos":"n.","zh":"压力程度（形容词加名词后缀，指性质本身）"},{"word":"stressor","pos":"n.","zh":"压力源（动词加表施动者的后缀，指引起紧张的外在因素）"}],"senses":[{"no":"01","title":"Full of pressure","titleCN":"充满压力的","definition":"marked by heavy demands on time, attention or emotion, so that a person feels pressed","definitionCN":"在时间、注意力或情绪上要求过重，使人感到被逼迫","example":"The stressful first year of teaching made him lose ten pounds.","exampleCN":"教书第一年压力极大，他瘦了十磅。","why":"The Latin root means 'drawn tight', so a life with too many demands is a rope pulled past its slack.","whyCN":"拉丁词根意为「拉紧」，因此要求过多的生活就是一根被拉过余量的绳。"},{"no":"02","title":"Causing tension in a place","titleCN":"使场合紧张起来的","definition":"making a room, meeting or event tense for everyone present","definitionCN":"使在场的每个人对某个场合感到紧张","example":"The stressful meeting ended with two colleagues refusing to speak.","exampleCN":"那场令人紧张的会议以两名同事拒绝说话收场。","why":"Tension is not only inside one person; a setting can impose it on everyone who enters.","whyCN":"紧张不只在一个人心里；一个场合也能把它压到每个进入其中的人身上。"},{"no":"03","title":"Physically taxing","titleCN":"极耗体力的","definition":"demanding sustained physical effort, as of work or travel","definitionCN":"需要持续体力付出的，如工作或旅途","example":"The stressful climb left the porters short of breath.","exampleCN":"那段极耗体力的攀爬让脚夫们喘不上气。","why":"When the load is bodily rather than mental, the same pulling image describes muscles held at their limit.","whyCN":"当负荷落在身体而非心上时，同一种拉扯的画面就用来形容被逼到极限的肌肉。"},{"no":"04","title":"Emotionally draining","titleCN":"让人心力交瘁的","definition":"using up emotional energy, so that a person is left flat and unable to respond","definitionCN":"耗尽情绪能量，使人变得平淡、难以回应","example":"Caring for a sick relative for a year was far more stressful than she expected.","exampleCN":"照护生病的亲人一年，远比她预想的更让人心力交瘁。","why":"Emotional labour also pulls: the effort is invisible, but the reserve is spent the same way.","whyCN":"情绪劳动同样在拉扯：付出看不见，储备却以同样的方式被花掉。"},{"no":"05","title":"Demanding precision","titleCN":"要求高度精确的","definition":"requiring exact timing or accuracy, where a small slip matters","definitionCN":"要求精确的时间或准确度，稍有偏差就有影响","example":"Landing the aircraft in crosswinds is a stressful task for any pilot.","exampleCN":"侧风中降落对任何飞行员都是要求极高的任务。","why":"Precision adds a second rope: besides doing the work, one must not make a single error.","whyCN":"精确再加一根绳：除了完成工作，还必须不出一个错。"},{"no":"06","title":"High-stakes","titleCN":"利害关系重大的","definition":"carrying consequences large enough that failure is costly","definitionCN":"后果重大到一旦失败代价高昂","example":"The stressful entrance exam decides who gets the scholarship.","exampleCN":"这场关系重大的入学考试决定谁拿到奖学金。","why":"The word turns into an assessment of stakes, not of effort: what matters is what a mistake would cost.","whyCN":"这个词转为对利害的评估，而非对努力的评估：要紧的是犯错要付什么代价。"},{"no":"07","title":"Marked by conflict","titleCN":"冲突不断的","definition":"full of disagreement or friction between people, so that contact itself is wearing","definitionCN":"人与人之间充满分歧与摩擦，以致接触本身就消耗人","example":"A stressful negotiation broke down twice before dawn.","exampleCN":"一场冲突不断的谈判在黎明前破裂了两次。","why":"Conflict is tension made social: two ropes pulled in opposite directions.","whyCN":"冲突是被社会化了的紧张：两根绳朝相反方向拉。"},{"no":"08","title":"Triggering a stress response","titleCN":"引发应激反应的","definition":"in research and medicine, describing a stimulus that raises the body's alarm response","definitionCN":"在科研与医学中，形容引起身体警报反应的外在刺激","example":"Researchers measured cortisol after a stressful stimulus.","exampleCN":"研究者在一段引发应激的刺激之后测量了皮质醇。","why":"The everyday word became a laboratory label once stress was studied as a bodily system.","whyCN":"当压力被当作身体系统来研究，日常词就变成了实验室标签。"}],"etymology":{"intro":{"en":"Stressful is an English adjective built on stress plus the native ending -ful. Stress itself came through Old French from Latin, where the underlying verb meant 'to draw tight'.","cn":"stressful 是英语形容词，由 stress 加一个表示「充满」的本族形容词词尾构成。stress 本身经古法语来自拉丁语，其底层动词意为「拉紧」。"},"items":[{"era":"LATIN STRINGERE","en":"Stringere meant 'to draw tight, to graze, to touch lightly'. The tight-drawing sense is the one that survives in this family.","cn":"stringere 意为「拉紧、擦过、轻触」。在这个词族里留下来的是「拉紧」这一义。"},{"era":"LATIN DISTRICTUS","en":"The past participle of the compound verb meant 'drawn apart, stretched, detained'. From it came the Old French noun for hardship and narrow straits.","cn":"那个复合动词的过去分词意为「被拉开、被拉伸、被扣住」。古法语中指困苦与窘迫的名词由它而来。"},{"era":"MIDDLE ENGLISH","en":"English took the Old French noun as a word for hardship, distress and, later, for emphasis laid on a syllable or an idea.","cn":"英语接受了这个古法语名词，用来指困苦、危难，后来又指落在音节或某个想法上的强调。"},{"era":"NINETEENTH AND TWENTIETH CENTURIES","en":"Engineers used the word for force per unit area, and physiologists borrowed it for the body's response to demand; the modern psychological sense dates from the twentieth century.","cn":"工程师用它指单位面积上的力，生理学家借它指身体对要求的反应；现代心理学义则始于 20 世纪。"},{"era":"NATIVE SUFFIX","en":"The ending -ful is native English and means 'full of', so stressful simply says 'full of stress'.","cn":"那个形容词词尾是英语本族成分，意为「充满」，因此 stressful 直说就是「充满压力的」。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of stringere is not settled, and the reconstructed Indo-European root offered for it is a hypothesis rather than a demonstrated fact.","cn":"来源不确定：stringere 的更早来源没有定论，为它提出的印欧词根属重构，只是假说而非已证事实。"}]},"similar":{"note":{"en":"The first group holds words from the same tight-drawing family that are often confused with stressful; the second holds near neighbours that name difficulty in other terms.","cn":"第一组是同出「拉紧」词族、常与 stressful 混淆的词；第二组是用其他方式指称艰难的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"distress","ipa":"/dɪˈstres/","tag":"doublet","definition":"A doublet of stress, taken from the same Old French source: it means acute suffering or a situation of danger, not ongoing pressure.","definitionCN":"与 stress 是同源双式词，来自同一个古法语来源：指剧烈痛苦或危险处境，而非持续压力。"},{"word":"strain","ipa":"/streɪn/","tag":"same root","definition":"From the same Latin verb through a different French route: a strain is the pull itself, or the injury it causes.","definitionCN":"经另一条法语路径来自同一个拉丁动词：strain 指拉力本身，或它造成的损伤。"},{"word":"strict","ipa":"/strɪkt/","tag":"same root, other sense","definition":"Also from the drawing-tight verb, but it kept the sense of binding closely, hence rules enforced without slack.","definitionCN":"同样来自「拉紧」动词，但保留了「紧紧束缚」的意思，因此指不留余地的规则。"},{"word":"stressor","ipa":"/ˈstresə/","tag":"derived, not a synonym","definition":"A derived word naming the cause rather than the experience: a stressor is what produces stress.","definitionCN":"派生词，指成因而非体验：压力源是产生压力的东西。"}]},{"heading":"NEAR MEANING","entries":[{"word":"demanding","ipa":"/dɪˈmɑːndɪŋ/","tag":"asks a lot","definition":"It stresses the size of the demand; a demanding job may be satisfying rather than tense.","definitionCN":"强调要求的份量；要求高的工作也可能令人满足，而不一定紧张。"},{"word":"taxing","ipa":"/ˈtæksɪŋ/","tag":"uses you up","definition":"It stresses depletion of energy, often physical, without the emotional charge of stressful.","definitionCN":"强调精力的消耗，常指体力，不带 stressful 那样的情绪色彩。"},{"word":"tense","ipa":"/tens/","tag":"the atmosphere","definition":"It describes the mood of a room or a moment, and is also from the same drawing-tight root.","definitionCN":"形容房间或时刻的气氛，也来自同一个「拉紧」词根。"},{"word":"pressure-filled","ipa":"/ˈpreʃə fɪld/","tag":"plain paraphrase","definition":"A transparent compound rather than an established single word: it simply states that pressure is present.","definitionCN":"透明的复合说法而非固定单词：只说明压力存在。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin base means 'drawn tight', and -ful means 'full of': a life pulled tight all round.","cn":"拉丁词基意为「拉紧」，后面那个本族词尾意为「充满」：整个生活被拉得紧紧的。"},{"en":"The family runs stress, stressful, stressfully, stressfulness, stressor.","cn":"同族词包括 stress、stressful、stressfully、stressfulness、stressor。"},{"en":"Fixed phrases mark the setting: stressful job, stressful situation, stressful period.","cn":"固定搭配标出场景：压力大的工作、紧张的处境、压力集中的时期。"},{"en":"The same tight-drawing root gives strain, strict and distress.","cn":"同一个「拉紧」词根衍生出 strain、strict 与 distress。"},{"en":"Engineering uses the noun for force on an area; physiology uses it for the body's alarm.","cn":"工程学用这个名词指单位面积上的力；生理学用它指身体的警报。"}],"abstract":[{"en":"Picture a rubber band around a stack of cards, one card too many.","cn":"想象一圈橡皮筋箍着一叠卡片，而卡片多了一张。"},{"en":"Picture a phone that rings every time you finally sit down.","cn":"想象一部电话，每次你终于坐下它就响。"},{"en":"Picture a bridge designed for ten trucks and carrying twelve.","cn":"想象一座按十辆卡车设计的桥，正载着十二辆。"}]},"examples":[{"en":"Many teachers describe the first term as the most stressful of their career.","cn":"许多教师把第一个学期形容为职业生涯中压力最大的一段。"},{"en":"Moving house is stressful even when everything goes well.","cn":"即使一切顺利，搬家也是件让人紧张的事。"},{"en":"The hospital reduced stressful noise at night to help patients sleep.","cn":"医院减少了夜间令人紧张的噪音，以帮助病人入睡。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"stress（压力）+ ful（充满）＝ 从头到脚都是压力 → 压力大的、令人紧张的。","word":"stressful"},"root":"stress 经古法语来自拉丁 districtus「被拉开、被扣住」，底层是 stringere「拉紧」；后面那个本族词尾意为「充满」。同族有 strain、strict、distress、district。","sensesIntro":{"en":"Eight senses follow one rope: something is drawn tight. It can be a whole life, a room, a body on a climb, a spent heart, a task that allows no slip, a decision with high stakes, a fight, or a laboratory stimulus.","cn":"八个义项沿一根绳展开：某物被拉紧。被拉紧的可以是一整段生活、一个房间、攀爬中的身体、被耗尽的心、不容失误的任务、代价重大的决定、一场争执，或实验室里的刺激。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rope drawn past its slack until the fibres show.","cn":"核心意象：一根被拉过余量、纤维都露出来的绳。"},"chain":["PULLED TIGHT","WEIGHT OF DEMANDS","TENSION IN THE ROOM","RESERVES RUNNING DOWN","NO SLIP ALLOWED","ALARM IN THE BODY"],"branches":[{"senses":"01 · 02","en":"THE ROPE AND THE ROOM: a pressed life and the atmosphere it creates are the same pull seen from inside and outside.","cn":"绳与房间：被逼迫的生活与它造出的气氛，是同一股拉力从内外两面看。"},{"senses":"03 · 04","en":"TWO KINDS OF COST: muscles at their limit and feelings spent to the bottom.","cn":"两种代价：被逼到极限的肌肉，与被掏到底的情绪。"},{"senses":"05","en":"A SECOND ROPE: precision adds the fear of one small slip on top of the work itself.","cn":"第二根绳：精确在工作本身之上又加了一层对微小失误的恐惧。"},{"senses":"06","en":"WHAT A MISTAKE COSTS: the word stops measuring effort and starts measuring stakes.","cn":"错误的代价：这个词不再衡量付出，而开始衡量利害。"},{"senses":"07 · 08","en":"PULLED FROM BOTH ENDS: conflict between people, and the body's own alarm when demand exceeds capacity.","cn":"两端都在拉：人与人之间的冲突，以及要求超过承受时身体自身的警报。"}]},"affixes":{"intro":{"en":"Stressful joins a Latin-derived noun to a native English ending, so it can be read as one borrowed part and one inherited part.","cn":"stressful 把一个源自拉丁语的名词接到一个英语本族词尾上，因此可以读成一半借来、一半继承。"},"latinIntro":{"en":"The Latin verb for drawing tight also builds the words for strain, strictness and distress, while the English ending marks 'full of'.","cn":"拉丁语中表示「拉紧」的动词还构成指拉伤、严格与痛苦的一组词，而英语词尾表示「充满」。"},"items":[{"word":"stringere","structure":"stringere, strinxi, strictum (Latin verb, third conjugation)","meaning":"to draw tight, bind","meaningCN":"拉紧；束缚","example":"The root pictures a cord pulled until it hums.","exampleCN":"这个词根画出一根被拉到发响的绳。"},{"word":"stress","structure":"stress (noun, from an Old French form of the Latin participle)","meaning":"pressure; emphasis","meaningCN":"压力；强调","example":"The job put him under constant stress.","exampleCN":"这份工作让他长期处在压力之下。"},{"word":"-ful","structure":"-ful (native English suffix, 'full of')","meaning":"full of","meaningCN":"充满……的","example":"The ending turns a noun into a description.","exampleCN":"这个词尾把名词变成描写。"},{"word":"stressful","structure":"stress + -ful","meaning":"full of pressure","meaningCN":"充满压力的","example":"The night shift was stressful.","exampleCN":"那个夜班压力很大。"},{"word":"stressfully","structure":"stressful + -ly (adverb)","meaning":"in a pressured way","meaningCN":"在压力下地","example":"The weeks passed stressfully for the whole team.","exampleCN":"那几周整个团队都在压力中度过。"},{"word":"stressfulness","structure":"stressful + -ness (noun of quality)","meaning":"the degree of pressure","meaningCN":"压力程度","example":"Researchers rated the stressfulness of each task.","exampleCN":"研究者评估了每项任务的压力程度。"},{"word":"stressor","structure":"stress + -or (one that acts)","meaning":"a cause of stress","meaningCN":"压力源","example":"Noise is a common stressor in open offices.","exampleCN":"噪音是开放式办公室里常见的压力源。"},{"word":"distress","structure":"distress (noun, a doublet of stress)","meaning":"acute suffering","meaningCN":"剧烈痛苦；危难","example":"The ship sent a distress signal.","exampleCN":"那艘船发出了求救信号。"},{"word":"strain","structure":"strain (noun and verb, same Latin root by another route)","meaning":"a pull; an injury from pulling","meaningCN":"拉力；拉伤","example":"The rope snapped under the strain.","exampleCN":"绳子在拉力下断了。"}],"latinEntries":[{"word":"stringere","structure":"stringere, strinxi, strictum (verb, third conjugation)","meaning":"to draw tight, bind, graze","meaningCN":"拉紧；束缚；擦过"},{"word":"districtus","structure":"districtus, districtus (m., fourth declension)","meaning":"a distraining, a seizure; stretched apart","meaningCN":"扣押；被拉开"},{"word":"strictus","structure":"strictus, stricta, strictum (adj.)","meaning":"drawn tight, close, strict","meaningCN":"拉紧的；紧密的；严格的"}],"derivatives":[{"word":"stress","pos":"n./v.","zh":"压力；紧张 / 强调；使紧张（拉丁词根「拉紧」，由拉紧转为压迫）"},{"word":"stressfully","pos":"adv.","zh":"在充满压力的状态下（形容词加副词后缀）"},{"word":"stressfulness","pos":"n.","zh":"压力程度（形容词加名词后缀，指性质本身）"},{"word":"stressor","pos":"n.","zh":"压力源（动词加表施动者的后缀，指引起紧张的外在因素）"}]}},{"word":"frustration","ipa_uk":"/frʌˈstreɪʃn/","ipa_us":"/frʌˈstreɪʃən/","definition_zh":"挫败感；挫折；受阻；使（计划）落空","definition_en":"the feeling or state of being blocked, or the act of making an effort or plan come to nothing","core_image":"一个人反复拧一颗已经滑丝的螺丝，手指越用力，螺纹越是空转","scene":"实验台前的学生第七次把同一段线路接上又拆下，示波器上的波形始终是乱的，他把工具往桌上一放。Frustration showed in the way the student pushed the breadboard away after another failed attempt.","sceneCN":"这里「挫折感」指「努力被反复挡住后生出的无力与烦躁」（第 1 个义项：受阻而生的情绪）；句意为又一次尝试失败后，这名学生把电路板推开，挫败感显露出来。","pos":[{"tag":"n.","zh":"挫败感；挫折；受阻（不可数指情绪，可数指造成挫败的事）"}],"collocations":[{"phrase":"in frustration","zh":"沮丧地；气恼地"},{"phrase":"sense of frustration","zh":"挫败感"},{"phrase":"growing frustration","zh":"日益加深的挫败感"},{"phrase":"frustration with","zh":"对……感到沮丧"},{"phrase":"frustration of a plan","zh":"计划受阻"},{"phrase":"frustration at the slow pace","zh":"对缓慢进度的不耐"}],"forms":[{"label":"复数","form":"frustrations"},{"label":"动词","form":"frustrate"},{"label":"形容词（感到受挫的）","form":"frustrated"},{"label":"形容词（令人受挫的）","form":"frustrating"},{"label":"副词","form":"frustratingly"},{"label":"名词（受阻状态）","form":"frustratedness"}],"derivatives":[{"word":"frustrate","pos":"v.","zh":"使受挫；使落空（拉丁动词「使成为徒劳」直接进入英语）"},{"word":"frustrated","pos":"adj.","zh":"受挫的；沮丧的（动词过去分词转为形容词）"},{"word":"frustrating","pos":"adj.","zh":"令人挫败的（动词现在分词转为形容词，指引起这种感受）"},{"word":"frustratingly","pos":"adv.","zh":"令人气恼地（分词形容词加副词后缀）"}],"senses":[{"no":"01","title":"The feeling of being blocked","titleCN":"受阻而生的挫败情绪","definition":"the unpleasant feeling that comes when effort meets a barrier and cannot get through","definitionCN":"努力遇到阻碍、无法通过时产生的不快感受","example":"Frustration rose in her voice as the form was rejected for the third time.","exampleCN":"表格第三次被退回时，她声音里的挫败感升了上来。","why":"The Latin verb meant 'to make vain', so the feeling is what a vain effort leaves behind.","whyCN":"拉丁动词意为「使成徒劳」，因此这种感受就是徒劳的努力留下的东西。"},{"no":"02","title":"An obstacle that blocks","titleCN":"造成挫败的阻碍","definition":"something that keeps a person from reaching a goal, viewed as a cause rather than a mood","definitionCN":"阻止人达到目标的障碍物，被视为成因而非情绪","example":"Traffic was the first frustration of an already difficult morning.","exampleCN":"对本来就不顺的早晨来说，交通是第一个挫折。","why":"The same word names the barrier and the reaction to it, because one produces the other.","whyCN":"同一个词既指障碍又指对它的反应，因为前者产生后者。"},{"no":"03","title":"Making a plan come to nothing","titleCN":"使计划落空","definition":"the act of defeating an aim or a scheme, often deliberately","definitionCN":"使某个目标或计策失败，常带刻意成分","example":"The frustration of the proposal by two committee members cost a year of work.","exampleCN":"两名委员让提案落空，代价是一年的工作。","why":"This is the oldest sense of the Latin noun: rendering something useless, whether by accident or by design.","whyCN":"这是拉丁名词最古老的意思：使某物变得无用，无论出于偶然还是有意。"},{"no":"04","title":"A run of repeated failure","titleCN":"屡屡受挫的经历","definition":"an extended period in which attempts keep failing, treated as an experience rather than a moment","definitionCN":"一段不断失败的经历，被当作经历而非瞬间","example":"Years of frustration in the laboratory finally produced a working method.","exampleCN":"实验室里多年屡屡受挫，最终产生了一套可行的办法。","why":"Repetition turns a single blocked moment into a stretch of time with its own weight.","whyCN":"重复把一次受阻的时刻拉成一段自有重量的时间。"},{"no":"05","title":"Pent-up irritation","titleCN":"积压的烦躁","definition":"irritation that has accumulated because it cannot be expressed at the moment it arises","definitionCN":"因为当时无法表达而积累起来的恼怒","example":"He threw the pen across the desk in pure frustration.","exampleCN":"他纯粹出于积压的烦躁把笔摔到了桌子那头。","why":"Blocked energy has to go somewhere; when it cannot reach the goal, it turns into temper.","whyCN":"被挡住的力量总要有去处；到不了目标，就变成脾气。"},{"no":"06","title":"The frustration-aggression link","titleCN":"挫折与攻击的心理学术语","definition":"in psychology, the state of being prevented from reaching a goal, studied as a trigger of aggression","definitionCN":"在心理学中，被阻止达到目标的状态，被研究为攻击行为的触发因素","example":"The study tested the frustration-aggression hypothesis with a simple puzzle task.","exampleCN":"该研究用一个简单的拼图任务检验挫折与攻击的假说。","why":"A research programme gave the everyday feeling a technical definition so it could be measured.","whyCN":"一个研究纲领给日常感受下了技术定义，好让它能被测量。"},{"no":"07","title":"Frustration of a contract","titleCN":"合同落空","definition":"in law, the ending of an agreement because an unforeseen event makes performance impossible","definitionCN":"在法律中，因不可预见的事件使履行成为不可能而终止协议","example":"The storm led to the frustration of the shipping contract.","exampleCN":"这场风暴导致运输合同落空。","why":"The legal use keeps the old sense of making an obligation vain without anyone being at fault.","whyCN":"法律用法保留了古老的意思：在无人有过错的情况下使义务变成空文。"},{"no":"08","title":"The point where a learner gives up","titleCN":"学习者的挫败临界点","definition":"in education, the level of difficulty at which a student stops trying","definitionCN":"在教育中，学生停止努力的那个难度水平","example":"Reading tasks were kept just below the frustration level.","exampleCN":"阅读任务的难度被控制在挫败临界点之下。","why":"Teaching borrows the word for the moment when challenge stops being productive and becomes a wall.","whyCN":"教学借这个词指挑战不再有成效、变成一堵墙的那一刻。"}],"etymology":{"intro":{"en":"Frustration comes from the Latin noun for a disappointment, built on an adverb meaning 'in vain'. The original picture is an effort that comes to nothing.","cn":"frustration 来自拉丁语中指「失望」的名词，它由意为「徒然」的副词构成。原始画面是一次落空的努力。"},"items":[{"era":"LATIN FRUSTRA","en":"Frustra was an adverb meaning 'in vain, to no purpose'. It is the seed of the whole family and already contains the idea of wasted effort.","cn":"frustra 是副词，意为「徒然、无结果」。它是整个词族的种子，本身已经含有「努力被浪费」的意思。"},{"era":"LATIN FRUSTRARI","en":"The verb frustrari meant 'to disappoint, deceive, bring to nothing'. It could describe both a failed attempt and a deliberate act of defeating someone.","cn":"动词 frustrari 意为「使失望、欺骗、使成空」。它既能描述失败的尝试，也能描述刻意使某人落空的行为。"},{"era":"LATIN FRUSTRATIO","en":"The noun frustratio named a disappointment or a deception, and this is the form that passed into English.","cn":"名词 frustratio 指失望或欺骗，进入英语的正是这个形式。"},{"era":"MIDDLE ENGLISH","en":"English adopted the noun in the seventeenth century in the sense of defeating a design, and the psychological sense grew from that use.","cn":"英语在 17 世纪接受了这个名词，意为使计谋失败；心理学义就从这个用法生长出来。"},{"era":"TWENTIETH-CENTURY PSYCHOLOGY","en":"Psychologists made the word a technical term for a blocked goal, and later borrowed it for the difficulty level at which learners stop working.","cn":"心理学家把这个词变成指「目标受阻」的术语，后来又借它指学习者停止努力的难度水平。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the link sometimes proposed between the 'in vain' adverb and the Latin word for fraud is a hypothesis, not a demonstrated derivation, and the deeper origin is unsettled.","cn":"来源不确定：有人提出「徒然」副词与拉丁语中指欺诈的词之间有联系，但那只是假说，并非已证实的派生，更深来源也无定论。"}]},"similar":{"note":{"en":"The first group holds forms of the same word that are regularly mixed up; the second holds other words for being stopped short.","cn":"第一组是同一个词的各种形式，常被混用；第二组是其他表示「被挡住」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"frustrated","ipa":"/frʌˈstreɪtɪd/","tag":"the person","definition":"The past participle used as an adjective: it describes the person who feels the block, not the block itself.","definitionCN":"过去分词用作形容词：描写感到受阻的人，而非阻碍本身。"},{"word":"frustrating","ipa":"/frʌˈstreɪtɪŋ/","tag":"the cause","definition":"The present participle: it describes the thing or task that produces the feeling.","definitionCN":"现在分词：描写产生这种感受的事物或任务。"},{"word":"frustrate","ipa":"/frʌˈstreɪt/","tag":"the verb","definition":"The base verb: to block someone's aim, or, in law, to make an agreement impossible to perform.","definitionCN":"基础动词：阻碍某人的目标；在法律中指使协议无法履行。"},{"word":"fraud","ipa":"/frɔːd/","tag":"probably unrelated","definition":"From a Latin word for deceit; the resemblance to the 'in vain' family is misleading and the two are usually treated as separate roots.","definitionCN":"来自拉丁语中指欺骗的词；与「徒然」词族的相似是误导，两者通常被视为不同词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"disappointment","ipa":"/ˌdɪsəˈpɔɪntmənt/","tag":"expectation unmet","definition":"It focuses on a result falling short of hope, with no emphasis on a barrier.","definitionCN":"侧重结果不及期望，不强调有障碍。"},{"word":"thwarting","ipa":"/ˈθwɔːtɪŋ/","tag":"deliberate blocking","definition":"It implies an outside agent actively defeating a plan, close to the oldest sense of frustration.","definitionCN":"暗含外部力量主动挫败计划，接近 frustration 最古老的意思。"},{"word":"blockage","ipa":"/ˈblɒkɪdʒ/","tag":"the physical obstacle","definition":"Concrete and physical: something is stuck in a passage, with no emotional content.","definitionCN":"具体而物理：有东西堵在通道里，不含情绪成分。"},{"word":"irritation","ipa":"/ˌɪrɪˈteɪʃn/","tag":"the temper only","definition":"It names the surface anger alone, while frustration keeps the cause of the anger in view.","definitionCN":"只指表层的恼怒，而 frustration 始终把恼怒的成因留在视野里。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin adverb behind the word means 'in vain', so frustration is literally effort made vain.","cn":"这个词背后的拉丁副词意为「徒然」，所以 frustration 字面上就是「被弄成徒劳的努力」。"},{"en":"The family runs frustrate, frustrated, frustrating, frustratingly, frustration.","cn":"同族词包括 frustrate、frustrated、frustrating、frustratingly、frustration。"},{"en":"Fixed phrases mark the target: frustration with a person, frustration at a delay, in frustration.","cn":"固定搭配标出对象：对某人的不满、对延误的不满、气恼地。"},{"en":"Law uses the phrase for a contract that an unforeseen event makes impossible to perform.","cn":"法律用这个词组指因不可预见事件而无法履行的合同。"},{"en":"Education speaks of a frustration level, the difficulty at which a learner stops trying.","cn":"教育学讲「挫败水平」，即学习者停止尝试的那个难度。"}],"abstract":[{"en":"Picture a screw turning forever because the thread is gone.","cn":"想象一颗永远在转、因为螺纹已经磨平的螺丝。"},{"en":"Picture a door that opens inward every time you push outward.","cn":"想象一扇你往外推、它却往里开的门。"},{"en":"Picture a kettle with the lid held down while the water boils.","cn":"想象水在沸腾，壶盖却被按住了。"}]},"examples":[{"en":"He slammed the folder shut in frustration and walked out.","cn":"他气恼地把文件夹合上，走了出去。"},{"en":"The delay caused growing frustration among passengers.","cn":"延误在乘客中引起了越来越深的挫败感。"},{"en":"Therapy helped her separate frustration from the person she was angry with.","cn":"治疗帮助她把挫败感与那个让她生气的人分开。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"frustr（徒然）+ ation（状态）＝ 力气使出去却什么都没成 → 挫败感、挫折。","word":"frustration"},"root":"拉丁 frustratio「失望、使成空」，来自 frustrari「使徒劳、使失望」，再上溯副词 frustra「徒然」。frustra 更深来源不确定，与拉丁语中指欺诈的词的联系仅为假说。","sensesIntro":{"en":"Eight senses follow one empty result: an effort made vain. The result can be felt, named as an obstacle, caused by someone, stretched over years, turned into temper, made a research variable, written into a contract, or measured as a limit in a classroom.","cn":"八个义项沿一个空结果展开：被弄成徒劳的努力。这个结果可以被感受到、被指为障碍、被某人造成、拉成多年经历、转成脾气、变成研究变量、写进合同，或被量成教室里的一个界限。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand pushing a door that will not open.","cn":"核心意象：一只手推着一扇打不开的门。"},"chain":["MADE VAIN","THE BARRIER ITSELF","THE FEELING LEFT BEHIND","ANGER WITH NO EXIT","TIME SPENT FAILING","A RULE THAT ENDS THE TRYING"],"branches":[{"senses":"01 · 04","en":"ONE FEELING, TWO LENGTHS: a single blocked moment, and the same moment repeated until it becomes an era.","cn":"一种感受、两种长度：一次受阻的瞬间，以及同一瞬间重复到成为一段岁月。"},{"senses":"02 · 03","en":"THE WALL AND WHO BUILT IT: the obstacle as a thing, then the act of putting it there.","cn":"墙与造墙的人：先看作为物的障碍，再看把墙立起来的那一举。"},{"senses":"05","en":"PRESSURE WITH NO OUTLET: energy that cannot reach the goal turns into temper.","cn":"无处可去的压力：到不了目标的力量转成脾气。"},{"senses":"06 · 08","en":"MEASURED TWICE: once as a variable in a laboratory, once as the line where a student stops.","cn":"被测量两次：一次作为实验室变量，一次作为学生停手的那条线。"},{"senses":"07","en":"WRITTEN INTO LAW: an obligation made empty by events nobody caused.","cn":"写进法律：无人造成的事件把义务变成空文。"}]},"affixes":{"intro":{"en":"Frustration is formed from the Latin noun of action, and the same stem supplies the verb and both participles that English uses as adjectives.","cn":"frustration 由拉丁语的表动作名词构成，同一词干还提供英语用作形容词的两个分词。"},"latinIntro":{"en":"The Latin family turns on an adverb meaning 'in vain'; from it come the verb, the noun of action and the English verb.","cn":"这个拉丁词族围绕一个意为「徒然」的副词展开；由它产生动词、表动作名词与英语动词。"},"items":[{"word":"frustra","structure":"frustra (Latin adverb)","meaning":"in vain, to no purpose","meaningCN":"徒然；无结果","example":"The adverb states the outcome before anything happens.","exampleCN":"这个副词在事情发生前就说出了结果。"},{"word":"frustrari","structure":"frustrari, frustratus sum (Latin deponent verb)","meaning":"to disappoint, bring to nothing","meaningCN":"使失望；使成空","example":"The attempt was made and brought to nothing.","exampleCN":"那番尝试做出来，又被弄成了空。"},{"word":"frustratio","structure":"frustratio, frustrationis (f., third declension)","meaning":"a disappointment, a deception","meaningCN":"失望；欺骗","example":"The noun names the outcome, not the effort.","exampleCN":"这个名词指结果，而非努力。"},{"word":"frustrate","structure":"frustrate (English verb, from the Latin participle)","meaning":"to block, to defeat","meaningCN":"阻碍；挫败","example":"Poor planning frustrated the whole project.","exampleCN":"规划不当让整个项目受挫。"},{"word":"frustrated","structure":"frustrate + -ed (past participle as adjective)","meaning":"blocked and therefore annoyed","meaningCN":"受挫而恼怒的","example":"The frustrated driver stopped the engine.","exampleCN":"那位受挫的司机熄了火。"},{"word":"frustrating","structure":"frustrate + -ing (present participle as adjective)","meaning":"causing a blocked feeling","meaningCN":"令人受挫的","example":"The frustrating part was the missing page.","exampleCN":"让人恼火的是那一页不见了。"},{"word":"frustration","structure":"frustrate + -ion (noun of action or result)","meaning":"the state of being blocked","meaningCN":"受阻的状态","example":"Frustration built up over three weeks.","exampleCN":"挫败感在三周里积累起来。"},{"word":"frustratingly","structure":"frustrating + -ly (adverb)","meaning":"in a way that annoys","meaningCN":"令人气恼地","example":"Frustratingly, the file was saved on another machine.","exampleCN":"令人气恼的是，文件存在另一台机器上。"}],"latinEntries":[{"word":"frustra","structure":"frustra (adv.)","meaning":"in vain, without effect","meaningCN":"徒然；无效"},{"word":"frustrari","structure":"frustrari, frustratus sum (deponent verb, first conjugation)","meaning":"to deceive, disappoint","meaningCN":"欺骗；使失望"},{"word":"frustratio","structure":"frustratio, frustrationis (f., third declension)","meaning":"a disappointment","meaningCN":"失望；落空"}],"derivatives":[{"word":"frustrate","pos":"v.","zh":"使受挫；使落空（拉丁动词「使成为徒劳」直接进入英语）"},{"word":"frustrated","pos":"adj.","zh":"受挫的；沮丧的（动词过去分词转为形容词）"},{"word":"frustrating","pos":"adj.","zh":"令人挫败的（动词现在分词转为形容词，指引起这种感受）"},{"word":"frustratingly","pos":"adv.","zh":"令人气恼地（分词形容词加副词后缀）"}]}},{"word":"frustrated","ipa_uk":"/frʌˈstreɪtɪd/","ipa_us":"/frʌˈstreɪtɪd/","definition_zh":"受挫的；沮丧的；受阻的；未能实现的","definition_en":"blocked in what one is trying to do, and therefore annoyed or discouraged","core_image":"木工第三次把榫头对着榫眼推去，总是差半毫米，木屑粘在手背上","scene":"车间里的老师傅第三次把同一块木料放回台面，榫头总是差半毫米塞不进去，他摘下护目镜揉了揉眼睛。The frustrated carpenter set the chisel down when the joint refused to close.","sceneCN":"这里 frustrated 指「因反复受阻而恼火又无力」（第 1 个义项：计划在半路被挡住）；句意为榫头就是合不上，这位受挫的木工把凿子放了下来。","pos":[{"tag":"adj.","zh":"受挫的；沮丧的；未能实现的；受阻的"}],"collocations":[{"phrase":"frustrated with","zh":"对……感到沮丧"},{"phrase":"frustrated by delays","zh":"因延误而受挫"},{"phrase":"deeply frustrated","zh":"深感挫败的"},{"phrase":"frustrated attempt","zh":"受挫的尝试"},{"phrase":"frustrated expectations","zh":"落空的期望"},{"phrase":"left frustrated","zh":"被弄得灰心"}],"forms":[{"label":"比较级","form":"more frustrated"},{"label":"最高级","form":"most frustrated"},{"label":"原级（动词原形）","form":"frustrate"},{"label":"现在分词","form":"frustrating"},{"label":"名词","form":"frustration"},{"label":"副词","form":"frustratedly"}],"derivatives":[{"word":"frustrate","pos":"v.","zh":"使受挫；使落空（本词的动词原形）"},{"word":"frustrating","pos":"adj.","zh":"令人受挫的（现在分词转形容词，指引起这种状态）"},{"word":"frustration","pos":"n.","zh":"挫败感；挫折（同族名词，指状态本身）"},{"word":"frustratedly","pos":"adv.","zh":"带着挫败地（形容词加副词后缀）"}],"senses":[{"no":"01","title":"Stopped halfway in a plan","titleCN":"计划在半路被挡住","definition":"prevented from carrying out an intention that was already under way","definitionCN":"已经着手进行的意图被阻止继续","example":"The team felt frustrated when the permit arrived a month late.","exampleCN":"许可晚到一个月，团队感到受挫。","why":"The word is the past participle of a verb meaning 'to make vain', so it describes an effort already made vain.","whyCN":"这个词是意为「使成徒劳」的动词的过去分词，因此描写一次已被弄成空的努力。"},{"no":"02","title":"Annoyed at being blocked","titleCN":"因受阻而恼火的","definition":"irritated and short-tempered because something keeps standing in the way","definitionCN":"因为总有东西挡在路上而烦躁、易怒","example":"He grew frustrated with the same error appearing on every page.","exampleCN":"每页都出现同一个错误，他越来越恼火。","why":"Repeated blocking turns the disappointment into temper, and the adjective carries both at once.","whyCN":"反复受阻把失望变成脾气，而这个形容词同时带着两者。"},{"no":"03","title":"Unsuccessful, as an attempt","titleCN":"未成功的（尝试）","definition":"describing an effort that did not achieve what it set out to do","definitionCN":"形容没有达到既定目标的努力","example":"Three frustrated attempts later, they changed the whole method.","exampleCN":"三次未成功的尝试之后，他们换掉了整套方法。","why":"Here the participle modifies the attempt itself rather than the person, keeping only the outcome.","whyCN":"这里分词修饰的是尝试本身而不是人，只保留结果这一层。"},{"no":"04","title":"Sexually unsatisfied","titleCN":"性需求未满足的","definition":"a polite or clinical way of saying that physical desire has no outlet","definitionCN":"委婉或临床地表示生理欲望没有出口","example":"The counsellor asked whether either partner felt frustrated.","exampleCN":"咨询师问双方是否有人感到需求未被满足。","why":"The core image of blocked energy is applied to the body, and the wording stays deliberately indirect.","whyCN":"受阻能量的核心意象被用到身体上，措辞刻意保持间接。"},{"no":"05","title":"Made void by events, in law","titleCN":"因情势而落空的（合同）","definition":"describing an agreement that cannot be performed because circumstances have changed fundamentally","definitionCN":"形容因情况根本改变而无法履行的协议","example":"The contract was held frustrated when the port closed for a year.","exampleCN":"港口封闭一年，该合同被认定落空。","why":"The legal phrase keeps the oldest meaning: an obligation reduced to nothing without anyone's fault.","whyCN":"法律说法保留了最古老的意思：在无人有过错的情况下义务化为乌有。"},{"no":"06","title":"Creatively stifled","titleCN":"才华被压抑的","definition":"describing an artist or writer whose ability is held back by conditions rather than by lack of skill","definitionCN":"形容艺术家或写作者的能力被环境而非技艺所限","example":"A frustrated painter, he spent ten years drawing advertisements.","exampleCN":"作为一个才华受压抑的画家，他画了十年广告。","why":"The block is no longer a single task but a whole career, and the adjective describes a person held in place.","whyCN":"阻碍不再是单项任务，而是整个职业，形容词描写一个被按住不动的人。"},{"no":"07","title":"Impatient with slow progress","titleCN":"对缓慢进展不耐的","definition":"restless because improvement is arriving more slowly than expected","definitionCN":"因改善比预期来得慢而焦躁","example":"Readers grew frustrated with the story's slow middle section.","exampleCN":"读者对这故事缓慢的中段越来越不耐。","why":"Time itself becomes the obstacle, and impatience is the shape frustration takes when nothing is actively blocking.","whyCN":"时间本身成了障碍；当没有谁在主动阻挡时，挫败就表现为不耐。"},{"no":"08","title":"With expectations unmet","titleCN":"期望落空的","definition":"disappointed because what was hoped for did not arrive","definitionCN":"因为所希望的事没有到来而失望","example":"The audience left frustrated after the promised discussion was cancelled.","exampleCN":"承诺的讨论被取消，观众失望地离开。","why":"Here the block is between hope and outcome, with no effort at all required.","whyCN":"这里阻碍位于希望与结果之间，根本不需要付出努力。"}],"etymology":{"intro":{"en":"Frustrated is the past participle of the verb frustrate, used as an adjective. The verb goes back to a Latin participle meaning 'brought to nothing'.","cn":"frustrated 是动词 frustrate 的过去分词，被用作形容词。这个动词可上溯到拉丁语中意为「被弄成空」的分词。"},"items":[{"era":"LATIN FRUSTRA","en":"The adverb meant 'in vain'; every later form in the family carries its verdict of wasted effort.","cn":"这个副词意为「徒然」；词族里后出的每个形式都带着它对努力的判决。"},{"era":"LATIN FRUSTRATUS","en":"The past participle of the verb meant 'disappointed, deceived, made vain'. English took the participle stem and built its own verb on it.","cn":"该动词的过去分词意为「被使失望、被欺骗、被弄成空」。英语取了这个分词词干，在它之上造出自己的动词。"},{"era":"SIXTEENTH-CENTURY ENGLISH","en":"The English verb first meant 'to bring to nothing, to balk', and only later acquired the milder sense of causing annoyance.","cn":"英语动词最初意为「使成空、使受阻」，后来才获得「使人恼火」这个较轻的意思。"},{"era":"ADJECTIVAL USE","en":"From the nineteenth century the participle settled into regular use as an adjective for a person whose plans are blocked.","cn":"从 19 世纪起，这个分词稳定地用作形容词，指计划被挡住的人。"},{"era":"LEGAL AND MEDICAL SENSES","en":"Law fixed the phrase for a contract made impossible, and medicine adopted the word for unmet physical desire.","cn":"法律固定了「合同无法履行」的说法，医学则采用这个词指未被满足的生理欲望。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of the 'in vain' adverb is not established, and its supposed link to the Latin word for fraud remains a hypothesis.","cn":"来源不确定：意为「徒然」的那个副词的更早来源没有定论，它与拉丁语中指欺诈的词之间的所谓联系仍属假说。"}]},"similar":{"note":{"en":"The first group holds the forms of one verb that are constantly swapped; the second holds other words for being held back.","cn":"第一组是同一个动词的各种形式，常被互换；第二组是其他表示「被按住」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"frustrating","ipa":"/frʌˈstreɪtɪŋ/","tag":"the cause, not the person","definition":"It describes the task or situation that produces the feeling; saying 'I am frustrating' reverses the direction.","definitionCN":"它描写产生感受的任务或处境；说「我很令人受挫」就把方向反了。"},{"word":"frustration","ipa":"/frʌˈstreɪʃn/","tag":"the noun","definition":"The state or the obstacle itself, where the adjective names the person who is in that state.","definitionCN":"指状态或障碍本身，而形容词指处在那种状态中的人。"},{"word":"flustered","ipa":"/ˈflʌstəd/","tag":"different root","definition":"From a verb of uncertain origin meaning 'to make flushed or confused'; it is about agitation, not about a blocked goal.","definitionCN":"来自一个来源不确定的动词，意为「使脸红、使慌乱」；它说的是慌乱，而不是目标受阻。"},{"word":"frustrate","ipa":"/frʌˈstreɪt/","tag":"the verb","definition":"The base verb, active in form: it needs an object, as in 'the delay frustrated us'.","definitionCN":"基础动词，形式上主动：需要宾语，例如「延误让我们受挫」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"thwarted","ipa":"/ˈθwɔːtɪd/","tag":"blocked by someone","definition":"It usually implies a person or force deliberately defeating the plan.","definitionCN":"通常暗含有人或某种力量刻意破坏了计划。"},{"word":"discouraged","ipa":"/dɪsˈkʌrɪdʒd/","tag":"hope lost","definition":"It stresses loss of confidence rather than the barrier, and can exist with no obstacle at all.","definitionCN":"强调信心丧失而非障碍，甚至可以毫无障碍地存在。"},{"word":"stifled","ipa":"/ˈstaɪfld/","tag":"held down","definition":"It pictures something pressed down so it cannot grow, close to the creative sense of frustrated.","definitionCN":"画面是被按住而无法生长，接近 frustrated 的「才华受压抑」义。"},{"word":"annoyed","ipa":"/əˈnɔɪd/","tag":"mild temper","definition":"A lighter, more general word for irritation, with no blocked effort behind it.","definitionCN":"更轻、更泛的恼怒用词，背后没有受阻的努力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The ending marks a past participle, so the word says 'I have been made vain', not 'I make others vain'.","cn":"词尾标明这是过去分词，所以它说的是「我被弄成空」，而不是「我让别人空」。"},{"en":"The family runs frustrate, frustrated, frustrating, frustration, frustratedly.","cn":"同族词包括 frustrate、frustrated、frustrating、frustration、frustratedly。"},{"en":"Fixed phrases mark the target: frustrated with a person, frustrated by delays, left frustrated.","cn":"固定搭配标出对象：对某人不满、因延误受挫、被弄得灰心。"},{"en":"Law pairs the word with contract; medicine pairs it with an unmet physical need.","cn":"法律把它与合同搭配；医学把它与未被满足的生理需求搭配。"},{"en":"The base verb is active and takes an object, while the participle describes a state.","cn":"基础动词是主动的、带宾语，而分词描写一种状态。"}],"abstract":[{"en":"Picture a key that fits the lock but turns a quarter turn short.","cn":"想象一把钥匙插得进去，却总差四分之一圈转不到底。"},{"en":"Picture a staircase whose last step is missing.","cn":"想象一段楼梯，最后一阶不见了。"},{"en":"Picture a pot of water that will not quite reach the boil.","cn":"想象一锅水，怎么也到不了沸点。"}]},"examples":[{"en":"She was frustrated that nobody had answered her email.","cn":"没人回她的邮件，她感到很受挫。"},{"en":"The frustrated passengers waited three hours on the platform.","cn":"受挫的乘客在站台上等了三个小时。"},{"en":"His frustrated ambition found an outlet in night classes.","cn":"他那受压抑的抱负在夜校里找到了出口。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"frustr（徒然）+ ated（已经如此）＝ 力气使过、结果成空 → 受挫的、沮丧的。","word":"frustrated"},"root":"拉丁 frustratus「被使失望、被弄成空」，来自 frustrari，再上溯副词 frustra「徒然」；更深来源不确定。英语以这个过去分词为基础，既造出动词，也直接用作形容词。","sensesIntro":{"en":"Eight senses follow one blocked effort. What is blocked may be a plan, a temper, an attempt, a body, a contract, a career, an expectation of speed, or a hope, and each time the word reports that something was already set in motion and could not finish.","cn":"八个义项沿一次受阻的努力展开。被挡住的可以是计划、脾气、尝试、身体、合同、职业、对速度的期待，或一份希望；每次这个词都说明某件事已经启动却没能走完。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand that has already pushed, against a door that will not move.","cn":"核心意象：一只手已经推出去，门却不动。"},"chain":["ALREADY PUSHING","THE DOOR THAT HOLDS","TEMPER RISING","THE ATTEMPT THAT FAILS","HELD DOWN FOR YEARS","HOPE THAT DOES NOT ARRIVE"],"branches":[{"senses":"01 · 02","en":"THE PUSH AND THE TEMPER: being stopped and being angry about it are two moments of one event.","cn":"推与脾气：被挡住和为此发火，是同一件事的两个时刻。"},{"senses":"03 · 08","en":"TWO KINDS OF NOT ARRIVING: an effort that fails, and a hope that never lands.","cn":"两种未抵达：失败的尝试，与从未落地的希望。"},{"senses":"04","en":"BLOCKED IN THE BODY: the same picture applied to desire, and said as indirectly as possible.","cn":"身体里的受阻：同一幅画面被用到欲望上，并尽可能说得间接。"},{"senses":"05","en":"BLOCKED BY EVENTS: the law keeps the oldest reading, an obligation emptied without fault.","cn":"被情势挡住：法律保留了最古老的读法，义务在无人有过错时被掏空。"},{"senses":"06 · 07","en":"HELD DOWN OVER TIME: a career pressed flat, and impatience when the block is only slowness.","cn":"在时间中被按住：被压平的职业，以及当阻碍只是「慢」时的不耐。"}]},"affixes":{"intro":{"en":"Frustrated is a verb participle doing adjective work, so its ending tells the reader that the person is the one affected.","cn":"frustrated 是做形容词工作的动词分词，词尾告诉读者：受影响的是这个人。"},"latinIntro":{"en":"The Latin participle ending marks something already done to the subject; the same stem also yields the noun of state.","cn":"拉丁分词词尾标明某事已经落在主语身上；同一词干还产出表状态的名词。"},"items":[{"word":"frustra","structure":"frustra (Latin adverb)","meaning":"in vain","meaningCN":"徒然","example":"The adverb supplies the verdict of the whole family.","exampleCN":"这个副词提供了整个词族的判决。"},{"word":"frustratus","structure":"frustratus, frustrata, frustratum (Latin past participle)","meaning":"disappointed, made vain","meaningCN":"被使失望的；被弄成空的","example":"The participle already carries the passive sense.","exampleCN":"这个分词本身已带被动意思。"},{"word":"frustrate","structure":"frustrate (English verb from the participle stem)","meaning":"to block or defeat","meaningCN":"阻碍；挫败","example":"The rules frustrated every reform.","exampleCN":"那些规定让每一次改革都受挫。"},{"word":"-ed","structure":"-ed (English participle ending)","meaning":"having undergone the action","meaningCN":"已经经历该动作的","example":"The ending shows that the state was imposed, not chosen.","exampleCN":"这个词尾表明该状态是被加上的，而非自己选的。"},{"word":"frustrated","structure":"frustrate + -ed","meaning":"blocked and annoyed","meaningCN":"受阻而恼火的","example":"The frustrated carpenter put down the chisel.","exampleCN":"受挫的木工放下了凿子。"},{"word":"frustration","structure":"frustrate + -ion (noun of state)","meaning":"the state of being blocked","meaningCN":"受阻的状态","example":"His frustration was visible in his hands.","exampleCN":"他的挫败感在手上看得出来。"},{"word":"frustrating","structure":"frustrate + -ing (active participle)","meaning":"producing a blocked feeling","meaningCN":"产生受阻感的","example":"It was a frustrating afternoon.","exampleCN":"那是一个令人沮丧的下午。"},{"word":"frustratedly","structure":"frustrated + -ly (adverb)","meaning":"with a sense of being blocked","meaningCN":"带着受阻感地","example":"She shook her head frustratedly.","exampleCN":"她沮丧地摇了摇头。"}],"latinEntries":[{"word":"frustrari","structure":"frustrari, frustratus sum (deponent verb, first conjugation)","meaning":"to be disappointed; to bring to nothing","meaningCN":"受失望；使成空"},{"word":"frustratus","structure":"frustratus, frustrata, frustratum (past participle)","meaning":"disappointed, made vain","meaningCN":"被使失望的；被弄成空的"},{"word":"frustratio","structure":"frustratio, frustrationis (f., third declension)","meaning":"a disappointment","meaningCN":"失望；落空"}],"derivatives":[{"word":"frustrate","pos":"v.","zh":"使受挫；使落空（本词的动词原形）"},{"word":"frustrating","pos":"adj.","zh":"令人受挫的（现在分词转形容词，指引起这种状态）"},{"word":"frustration","pos":"n.","zh":"挫败感；挫折（同族名词，指状态本身）"},{"word":"frustratedly","pos":"adv.","zh":"带着挫败地（形容词加副词后缀）"}]}},{"word":"intellect","ipa_uk":"/ˈɪntəlekt/","ipa_us":"/ˈɪntəlekt/","definition_zh":"智力；理解力；才智；有才智的人；知识界","definition_en":"the power of the mind to reason and understand, or a person or group marked by that power","core_image":"书房里，读者把散落的线索逐条摆上桌面，最后拼出一条能自洽的线","scene":"图书馆的角落，一位老人把三本摊开的笔记并排放好，用铅笔在页边画出彼此呼应的句子。Her intellect showed in the way she joined three separate arguments into one clear line.","sceneCN":"这里 intellect 指「把材料组织成自洽整体的思维能力」（第 2 个义项：运用中的理解力）；句意为她把三套彼此独立的论证接成一条清晰的线，这份才智由此显现。","pos":[{"tag":"n.","zh":"智力；理解力；（可数）有才智的人；（集合）知识界"}],"collocations":[{"phrase":"human intellect","zh":"人类智力"},{"phrase":"a sharp intellect","zh":"敏锐的才智"},{"phrase":"the intellect of an age","zh":"一个时代的心智"},{"phrase":"appeal to the intellect","zh":"诉诸理性"},{"phrase":"a formidable intellect","zh":"令人敬畏的才智"},{"phrase":"intellect and emotion","zh":"理智与情感"}],"forms":[{"label":"复数","form":"intellects"},{"label":"形容词","form":"intellectual"},{"label":"副词","form":"intellectually"},{"label":"名词（智力，总称）","form":"intelligence"},{"label":"形容词（有理解力的）","form":"intelligent"},{"label":"名词（知识界群体）","form":"intelligentsia"}],"derivatives":[{"word":"intellectual","pos":"adj./n.","zh":"智力的；有才智的 / 知识分子（拉丁形容词「属于理解力的」进入英语）"},{"word":"intellectually","pos":"adv.","zh":"在智力上（形容词加副词后缀）"},{"word":"intelligence","pos":"n.","zh":"智力；情报（同出拉丁「理解」词干，后一条义线转指情报）"},{"word":"intelligible","pos":"adj.","zh":"可理解的（同词根，后缀表示「能够被……」）"}],"senses":[{"no":"01","title":"The power of reasoning","titleCN":"思维能力","definition":"the mind's capacity to reason, judge and understand, considered as a faculty","definitionCN":"心智推理、判断与理解的能力，被当作一种官能","example":"Philosophy has long treated intellect as distinct from the senses.","exampleCN":"哲学长期把理智与感官区别开来。","why":"The Latin verb meant 'to pick out between', so the faculty is first of all a power of discriminating.","whyCN":"拉丁动词意为「在之间挑出」，因此这种官能首先是一种分辨力。"},{"no":"02","title":"Mental power in use","titleCN":"运用中的理解力","definition":"the same capacity as it actually works on a problem, rather than as an abstract label","definitionCN":"这种能力实际作用于问题时，而非作为抽象标签","example":"Her intellect showed in the way she joined three separate arguments.","exampleCN":"她把三套独立论证接成一条线，才智由此显现。","why":"A faculty is invisible until it leaves a trace on material, and that trace is what this sense names.","whyCN":"官能本身看不见，直到它在材料上留下痕迹；这一义项指的正是那道痕迹。"},{"no":"03","title":"A person of great mental power","titleCN":"有才智的人","definition":"a countable use naming an individual whose mind is unusually strong","definitionCN":"可数用法，指心智格外强的个人","example":"He was one of the finest intellects of his generation.","exampleCN":"他是那一代人中最出色的才智之士之一。","why":"Metonymy turns the possession into the possessor: the mind stands for the person who has it.","whyCN":"借代把所拥有之物变成拥有者：心智代表了拥有它的人。"},{"no":"04","title":"The intellectual class","titleCN":"知识界、知识分子群体","definition":"the body of people who live by thought, writing and research, taken as a group","definitionCN":"以思考、写作与研究为业的人所成的群体","example":"The nation's intellect gathered in the new university.","exampleCN":"这个国家的知识界聚集在新大学里。","why":"Once enough individuals are named this way, the word can name the group they form.","whyCN":"当这样被称呼的个体足够多，这个词就能指他们所成的群体。"},{"no":"05","title":"Mind as opposed to feeling","titleCN":"与情感相对的心智","definition":"the side of a person that calculates and weighs, set against emotion","definitionCN":"人身上负责计算与权衡的一面，与情感相对","example":"The novel sets intellect against instinct in every chapter.","exampleCN":"这部小说在每一章里都把理智与本能对立。","why":"The old contrast between reason and passion gave the word a fixed place on one side of the divide.","whyCN":"理智与激情这一古老对立，给这个词在分野的一侧固定了位置。"},{"no":"06","title":"The shared mind of an age","titleCN":"一个时代的心智","definition":"the characteristic thinking of a period, treated as a single mind","definitionCN":"一个时期特有的思维方式，被当作一个整体心智","example":"The intellect of the century was shaped by print.","exampleCN":"那个世纪的心智是被印刷塑造的。","why":"A collective can be spoken of as having one mind, and the word extends to that imagined unity.","whyCN":"集体可以被说成拥有一个心智，这个词就延伸到那被想象出的统一体。"},{"no":"07","title":"Sharp judgment","titleCN":"敏锐的判断力","definition":"the ability to see what matters quickly and decide well","definitionCN":"迅速看出要害并作出好决定的能力","example":"She had the intellect to see which clause would fail.","exampleCN":"她有看出哪一条款会出问题的判断力。","why":"Understanding becomes practical when it must choose, and judgment is understanding under pressure.","whyCN":"理解必须在选择时变得实用；判断就是压力下的理解。"},{"no":"08","title":"Intellectual pursuits","titleCN":"智力活动、学问","definition":"the activities and subjects that exercise the mind, such as study and research","definitionCN":"锻炼心智的活动与题材，如研读与研究","example":"He gave his evenings to intellect rather than to company.","exampleCN":"他把夜晚给了学问，而不是交际。","why":"The faculty's name transfers to the things it works on, the way a tool's name can name its trade.","whyCN":"官能的名字转移到它所作用的对象上，正如工具的名字可以指那门行当。"}],"etymology":{"intro":{"en":"Intellect comes from the Latin noun for understanding, built on a verb that literally means 'to pick out between things'.","cn":"intellect 来自拉丁语中指「理解」的名词，它由一个字面意为「在事物之间挑出」的动词构成。"},"items":[{"era":"LATIN LEGERE","en":"Legere meant 'to gather, pick out, read'. Reading was understood as picking out letters from a surface, so the root joins choosing with reading.","cn":"legere 意为「收集、挑出、读」。读被理解为从表面上挑出字母，因此这个词根把「选择」与「阅读」连在一起。"},{"era":"LATIN INTELLEGERE","en":"The compound is generally analysed as 'between' plus 'pick out', giving 'to see the difference between things', hence 'to understand'. The doubled consonant comes from the prefix fusing with the root.","cn":"这个复合词一般认为由「在……之间」加「挑出」构成，得出「看出事物之间的区别」，进而指「理解」。重复的辅音来自前缀与词根融合。"},{"era":"LATIN INTELLECTUS","en":"The noun named both the act of understanding and the power behind it; it also came to mean 'meaning' or 'sense'.","cn":"这个名词既指理解的行为，也指它背后的能力；后来又指「含义」或「意思」。"},{"era":"MEDIEVAL AND EARLY MODERN ENGLISH","en":"English took the noun through learned Latin in the late medieval period, and scholastic writers fixed it as the name of one faculty of the soul.","cn":"英语在中世纪晚期经书面拉丁语接受了这个名词，经院学者把它固定为灵魂某一种官能的名称。"},{"era":"NINETEENTH CENTURY","en":"With the growth of universities and public debate, the plural and the collective use named people who live by thought, and a Russian coinage later supplied a word for that class.","cn":"随着大学与公共讨论的成长，复数与集合用法开始指以思考为业的人，后来一个俄语新造词又为这个阶层提供了名称。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: whether the prefix should be read as 'between' or as an intensive is debated, and the deeper Indo-European root proposed for the verb is a reconstructed form.","cn":"来源不确定：前缀该读作「在……之间」还是读作加强语气，学界仍有争论；为该动词提出的更深印欧词根属重构形式。"}]},"similar":{"note":{"en":"The first group holds words from the same 'pick out and read' family that are routinely confused; the second holds near neighbours for mental power.","cn":"第一组是同出「挑出与阅读」词族、常被混淆的词；第二组是表示心智能力的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"intelligence","ipa":"/ˈɪntelɪdʒəns/","tag":"capacity, then secrets","definition":"From the same verb: it names the capacity to learn and understand, and separately, by a later shift, information gathered about an enemy.","definitionCN":"同出那个动词：指学习与理解的能力；后来又经一次转指，指搜集到的敌方情报。"},{"word":"intellectual","ipa":"/ˌɪntəˈlektʃuəl/","tag":"adjective and person","definition":"The adjective built on the noun, and, as a noun, a person who lives by thought; it is not a synonym of the faculty itself.","definitionCN":"由该名词构成的形容词；作名词时指以思考为业的人；它不是那种官能本身的同义词。"},{"word":"intelligible","ipa":"/ˌɪntelɪdʒəbl/","tag":"can be understood","definition":"Same root with an ending meaning 'capable of being': it describes speech or writing, not a mind.","definitionCN":"同词根加「能够被……」的词尾：描写言语或文字，而非心智。"},{"word":"intelligentsia","ipa":"/ˌɪntelɪˈdʒentsiə/","tag":"a loan from Russian","definition":"A nineteenth-century Russian formation from the same root, naming the educated class as a social group.","definitionCN":"19 世纪俄语据同一词根造出，指作为社会群体的受教育阶层。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mind","ipa":"/maɪnd/","tag":"the whole","definition":"The broadest word: it covers thought, memory and feeling together, where intellect is only the reasoning part.","definitionCN":"最宽的词：把思维、记忆与感受一并包含，而 intellect 只是其中推理的那部分。"},{"word":"reason","ipa":"/ˈriːzn/","tag":"the process","definition":"It names the activity of drawing conclusions, while intellect names the power that makes the activity possible.","definitionCN":"指得出判断的活动，而 intellect 指使这活动得以发生的能力。"},{"word":"brainpower","ipa":"/ˈbreɪnpaʊə/","tag":"informal and collective","definition":"A plain compound for mental capacity, usually of a team or an organization rather than a faculty of one person.","definitionCN":"朴素的复合词，指心智能力，通常用于团队或组织，而非一个人的官能。"},{"word":"wit","ipa":"/wɪt/","tag":"quick and light","definition":"An older native word for quickness of mind, often with a flavour of humour that intellect lacks.","definitionCN":"更古老的本族词，指心思敏捷，常带 intellect 所没有的幽默意味。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin verb behind it means 'pick out between', so intellect is a power of telling things apart.","cn":"它背后的拉丁动词意为「在之间挑出」，所以 intellect 是一种分辨事物的能力。"},{"en":"The family runs intellect, intellectual, intellectually, intelligence, intelligible.","cn":"同族词包括 intellect、intellectual、intellectually、intelligence、intelligible。"},{"en":"Fixed phrases mark the contrast: intellect and emotion, appeal to the intellect, a sharp intellect.","cn":"固定搭配标出对照：理智与情感、诉诸理性、敏锐的才智。"},{"en":"The same root appears in words for reading and choosing, because reading was picking letters out.","cn":"同一个词根还出现在表示「阅读」与「选择」的词里，因为阅读就是挑出字母。"},{"en":"The noun can name a person, a class of people, or the mind of a whole period.","cn":"这个名词可以指一个人、一个阶层，或一整个时期的心智。"}],"abstract":[{"en":"Picture a table where loose threads are laid out until one continuous line appears.","cn":"想象一张桌子，散乱的线头摆开来，直到一条连续的线出现。"},{"en":"Picture a key ring with many keys, and the one hand that knows which fits.","cn":"想象一串钥匙，和那只知道哪把能开的手。"},{"en":"Picture a lamp that lights the inside of a room and leaves the street dark.","cn":"想象一盏灯把屋里照亮，街上却是暗的。"}]},"examples":[{"en":"The debate appealed to intellect rather than to sentiment.","cn":"这场辩论诉诸理智，而不是情绪。"},{"en":"She was a formidable intellect and a patient teacher.","cn":"她才智过人，又是位有耐心的老师。"},{"en":"The printing press reshaped the intellect of an entire century.","cn":"印刷机重塑了整个世纪的心智。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"intel（在之间）+ lect（挑选）＝ 在众多线索之间挑出关键，连成一条线 → 智力、才智。","word":"intellect"},"root":"拉丁 intellectus「理解；含义」，来自 intellegere「理解」，一般分析为 inter「在……之间」+ legere「挑出、读」；更早来源不确定，前缀读法亦有争论。同源有 intelligence、intelligible、intellectual。","sensesIntro":{"en":"Eight senses follow one act of discrimination: picking the right thing out of many. That act can be named as a faculty, seen at work, embodied in a person, gathered into a class, set against feeling, spread over an age, sharpened into judgment, and finally applied to the pursuits themselves.","cn":"八个义项沿一个分辨动作展开：从众多事物中挑出对的那些。这个动作可以被称作官能、被看见在运作、被具体化为一个人、聚成一个阶层、与情感对立、铺展到一个时代、磨成判断力，最后落到它所作用的活动上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand sorting many loose pieces until the useful ones lie in a row.","cn":"核心意象：一只手把许多散件分拣开来，直到有用的那些排成一列。"},"chain":["PICK OUT BETWEEN","THE POWER TO DO IT","THE POWER AT WORK","THE PERSON WHO HAS IT","A CLASS OF SUCH PEOPLE","A MIND SHARED BY AN AGE"],"branches":[{"senses":"01 · 05","en":"FACULTY AND ITS OPPOSITE: the power itself, and the side of a person it is measured against.","cn":"官能与其对立面：能力本身，以及人身上用来与它对照的那一面。"},{"senses":"02 · 07","en":"POWER IN ACTION: understanding that works on material, and understanding forced to choose.","cn":"运作中的能力：作用于材料的理解，以及被迫做出选择的理解。"},{"senses":"03","en":"THE HOLDER: by standing for the person, the possession becomes a description of someone.","cn":"拥有者：通过代表那个人，所拥有之物成了对人的一种描写。"},{"senses":"04 · 06","en":"SCALE UPWARD: from a group of such people to the imagined single mind of a period.","cn":"向上放大：从这样一群人到被想象为一个整体的时代心智。"},{"senses":"08","en":"THE WORK IT DOES: the faculty finally names the studies that keep it busy.","cn":"它所做的事：这一官能最终指那些让它忙碌的学问。"}]},"affixes":{"intro":{"en":"Intellect is a Latin noun of result built from a prefix and a verb, and both parts recur across a large English family.","cn":"intellect 是由前缀与动词构成的拉丁结果名词，两部分都在一大批英语词中反复出现。"},"latinIntro":{"en":"The verb for picking out and reading also gives English words for choosing, gathering and reading aloud, so the family is wider than it first appears.","cn":"表示「挑出、读」的这个动词还给出英语中表示选择、收集与朗读的词，因此这个词族比初看更宽。"},"items":[{"word":"inter-","structure":"inter- (Latin prefix, 'between, among')","meaning":"between","meaningCN":"在……之间","example":"The prefix places the action in the gap between things.","exampleCN":"这个前缀把动作放在事物之间的空隙里。"},{"word":"legere","structure":"legere, legi, lectum (Latin verb, third conjugation)","meaning":"to gather, pick out, read","meaningCN":"收集；挑出；读","example":"The root joins choosing with reading.","exampleCN":"这个词根把「选择」与「阅读」连在一起。"},{"word":"intellegere","structure":"inter- + legere","meaning":"to understand","meaningCN":"理解","example":"To understand is to tell one thing from another.","exampleCN":"理解就是把一件事与另一件区分开。"},{"word":"intellectus","structure":"intellegere + -tus (noun of result)","meaning":"understanding; meaning","meaningCN":"理解；含义","example":"The noun names both the act and its result.","exampleCN":"这个名词同时指行为与结果。"},{"word":"intellect","structure":"intellectus (Latin noun taken into English)","meaning":"the power of understanding","meaningCN":"理解的能力","example":"Her intellect joined three arguments.","exampleCN":"她的才智把三套论证接了起来。"},{"word":"intellectual","structure":"intellect + -ual (adjective ending)","meaning":"belonging to the understanding","meaningCN":"属于理解力的","example":"The question was an intellectual one.","exampleCN":"那是一个智力层面的问题。"},{"word":"intelligence","structure":"intellegere + -entia (noun of state)","meaning":"the capacity to understand","meaningCN":"理解的能力","example":"Tests measure only part of intelligence.","exampleCN":"测验只测出智力的一部分。"},{"word":"intelligible","structure":"intellegere + -ibilis ('capable of being')","meaning":"able to be understood","meaningCN":"可被理解的","example":"His lecture was intelligible even to beginners.","exampleCN":"他的讲座连初学者也听得懂。"},{"word":"collect","structure":"com- + legere","meaning":"to gather together","meaningCN":"收集；聚集","example":"The same root gathers things in other words.","exampleCN":"同一词根在别的词里表示把东西聚起来。"}],"latinEntries":[{"word":"legere","structure":"legere, legi, lectum (verb, third conjugation)","meaning":"to gather, choose, read","meaningCN":"收集；选择；读"},{"word":"intellegere","structure":"intellegere, intellexi, intellectum (verb, third conjugation)","meaning":"to understand, perceive","meaningCN":"理解；领会"},{"word":"intellectus","structure":"intellectus, intellectus (m., fourth declension)","meaning":"understanding, comprehension","meaningCN":"理解；领会"},{"word":"intellegentia","structure":"intellegentia, intellegentiae (f., first declension)","meaning":"intelligence, understanding","meaningCN":"智力；理解力"}],"derivatives":[{"word":"intellectual","pos":"adj./n.","zh":"智力的；有才智的 / 知识分子（拉丁形容词「属于理解力的」进入英语）"},{"word":"intellectually","pos":"adv.","zh":"在智力上（形容词加副词后缀）"},{"word":"intelligence","pos":"n.","zh":"智力；情报（同出拉丁「理解」词干，后一条义线转指情报）"},{"word":"intelligible","pos":"adj.","zh":"可理解的（同词根，后缀表示「能够被……」）"}]}},{"word":"intellectual ability","ipa_uk":"/ˌɪntəˈlektʃuəl əˈbɪləti/","ipa_us":"/ˌɪntəˈlektʃuəl əˈbɪləti/","definition_zh":"智力；心智能力；理解与推理的能力","definition_en":"the capacity to understand, reason and solve problems with the mind","core_image":"一张白纸上写满杂乱线索，一只手把它们连成一张能读的图","scene":"招工面试的房间里，考官把一张纸推到年轻人面前，让他用三分钟把一组混乱的图形排成有规律的序列。The test was designed to measure intellectual ability rather than memorized facts.","sceneCN":"这里「智力」指「理解与推理的心智能力」（第 1 个义项：一般的心智容量）；句意为这项测验意在测出智力，而不是测背下来的事实。","pos":[{"tag":"n. phrase","zh":"智力；心智能力（作不可数，指一种能力；作可数时指某一具体方面的能力）"}],"collocations":[{"phrase":"high intellectual ability","zh":"很高的智力"},{"phrase":"measure intellectual ability","zh":"测量智力"},{"phrase":"intellectual ability and achievement","zh":"智力与学业成就"},{"phrase":"decline in intellectual ability","zh":"智力衰退"},{"phrase":"assess intellectual ability","zh":"评估智力"},{"phrase":"intellectual ability tests","zh":"智力测验"}],"forms":[{"label":"复数","form":"intellectual abilities"},{"label":"形容词（智力的）","form":"intellectual"},{"label":"副词","form":"intellectually"},{"label":"名词（能力）","form":"ability"},{"label":"名词（智力，总称）","form":"intelligence"}],"derivatives":[{"word":"intellectual","pos":"adj./n.","zh":"智力的 / 知识分子（拉丁词干「理解」，后缀表示「属于」）"},{"word":"ability","pos":"n.","zh":"能力（拉丁词根「持有」加「易于」后缀，由「拿得稳」转为「做得来」）"},{"word":"intellectually","pos":"adv.","zh":"在智力方面（形容词加副词后缀）"},{"word":"intellectually disabled","pos":"adj. phrase","zh":"智力受损的（短语，用于描述智力功能受限）"}],"senses":[{"no":"01","title":"General mental capacity","titleCN":"一般的心智容量","definition":"the overall power of the mind to understand and deal with ideas","definitionCN":"心智理解与处理观念的整体能力","example":"The test was designed to measure intellectual ability rather than memorized facts.","exampleCN":"这项测验意在测出智力，而非背下来的事实。","why":"The phrase pairs 'capacity to hold' with 'belonging to the understanding', so it names the mind's general grip.","whyCN":"这个词组把「拿得住的能力」与「属于理解力的」放在一起，因此指心智的一般握力。"},{"no":"02","title":"Capacity for abstract reasoning","titleCN":"抽象推理能力","definition":"the part of mental capacity that works on symbols, rules and abstract relations","definitionCN":"心智能力中处理符号、规则与抽象关系的部分","example":"Abstract problems reveal intellectual ability more clearly than routine ones.","exampleCN":"抽象问题比程式化问题更能显出抽象推理能力。","why":"Once things are stripped of their surface, only the relations remain, and this sense names the power to hold them.","whyCN":"一旦剥去表面，只剩下关系；这一义项指把握这些关系的能力。"},{"no":"03","title":"Capacity as measured by a test","titleCN":"测得的智力水平","definition":"the quantity a standardized instrument reports when it assesses mental capacity","definitionCN":"标准化工具评估心智能力时给出的数值","example":"Her intellectual ability score placed her in the top tenth.","exampleCN":"她的智力得分落在最高的十分之一。","why":"Assessment turns a capacity into a number, and the phrase follows the number rather than the person.","whyCN":"评估把能力变成数字，而这个词组随之落在数字上，而不是人身上。"},{"no":"04","title":"Capacity for learning","titleCN":"学习能力","definition":"the ability to acquire new knowledge or skills from experience and instruction","definitionCN":"从经验与教学中获得新知识或技能的能力","example":"Early schooling chiefly develops intellectual ability through language.","exampleCN":"早期学校教育主要通过语言发展学习能力。","why":"Understanding must first take something in; learning is that intake seen from the side of the learner.","whyCN":"理解先要接纳某物；学习就是从学习者一侧看到的这种接纳。"},{"no":"05","title":"Ability to solve novel problems","titleCN":"解决新问题的能力","definition":"the capacity to find a workable path when no routine applies","definitionCN":"在没有现成程序可用时找出可行路径的能力","example":"Employers value intellectual ability when the task has no precedent.","exampleCN":"任务没有先例时，雇主看重的是解决新问题的能力。","why":"A mind shows its strength most plainly when the usual script fails.","whyCN":"当惯常脚本失效时，心智的力量最为明显。"},{"no":"06","title":"Capacity for critical judgment","titleCN":"批判判断力","definition":"the ability to weigh evidence and decide what should be accepted","definitionCN":"权衡证据并决定应接受什么的能力","example":"The course aims at intellectual ability, not at accumulation of names and dates.","exampleCN":"这门课着眼于批判判断力，而不是堆积分年与人名。","why":"Judgment is understanding that has to commit, so it belongs to the same capacity as reasoning.","whyCN":"判断是需要表态的理解，因此与推理同属一种能力。"},{"no":"07","title":"Cognitive ability in psychology","titleCN":"认知能力（心理学术语）","definition":"the technical label for mental functions studied as a measurable set","definitionCN":"指被当作一组可测功能来研究的心理机能的技术名称","example":"The study tracked cognitive ability from childhood to middle age.","exampleCN":"该研究追踪认知能力从童年到中年。","why":"A research tradition renamed the everyday phrase so that separate functions could be tested one by one.","whyCN":"一个研究传统给日常说法换了名称，好让各项功能被逐一测量。"},{"no":"08","title":"Academic aptitude in education","titleCN":"学业潜能","definition":"the capacity that predicts how well a student will do in formal study","definitionCN":"预测学生在正规学习中表现的能力","example":"Admissions officers treat intellectual ability as a predictor, not a verdict.","exampleCN":"招生人员把学业潜能当作预测，而非定论。","why":"Schools need a forward-looking measure, so the phrase turns capacity into a forecast.","whyCN":"学校需要一个面向未来的度量，于是这个词组把能力变成一项预测。"}],"etymology":{"intro":{"en":"Intellectual ability joins a Latin adjective for 'belonging to the understanding' to a Latin noun for 'capacity to hold'. The two halves come from different Latin roots, one about picking out and one about holding.","cn":"intellectual ability 把一个意为「属于理解力的」拉丁形容词，接到一个意为「拿得住的能力」的拉丁名词上。两半来自不同的拉丁词根：一半关乎挑出，一半关乎持有。"},"items":[{"era":"LATIN LEGERE","en":"The root of the first word means 'to gather, pick out, read'; understanding was pictured as telling one thing from another.","cn":"第一个词的词根意为「收集、挑出、读」；理解被描绘为把一物与另一物区分开。"},{"era":"LATIN INTELLECTUALIS","en":"Late Latin built an adjective from the noun for understanding, and this adjective reached English through learned channels.","cn":"晚期拉丁语由指「理解」的名词造出形容词，这个形容词经书面渠道进入英语。"},{"era":"LATIN HABERE","en":"The second word goes back to a verb meaning 'to hold, have'. Its adjective meant 'easy to handle, apt', and from that came the noun for fitness or capacity.","cn":"第二个词可上溯到意为「持有、拥有」的动词。它的形容词意为「易于操控、合手」，指「合适、能力」的名词由此而来。"},{"era":"LATIN HABILITAS","en":"The noun named aptness or fitness, and medieval and modern English used it for a general power to do something.","cn":"这个名词指「合宜、适宜」，中世纪及现代英语用它指做事的一般能力。"},{"era":"MODERN EDUCATION AND PSYCHOLOGY","en":"Testing movements in the twentieth century fixed the whole phrase as the object that standardized instruments try to measure.","cn":"20 世纪的测验运动把整个词组固定为标准化工具试图测量的对象。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of the holding verb is not settled, and the analysis of the prefix in the first word is still debated.","cn":"来源不确定：表示「持有」的动词更早的来源没有定论，第一个词中前缀的分析也仍有争论。"}]},"similar":{"note":{"en":"The first group holds words built on the same two roots that are often confused; the second holds near neighbours for mental capacity.","cn":"第一组是由同样两个词根构成、常被混淆的词；第二组是表示心智能力的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"intellect","ipa":"/ˈɪntəlekt/","tag":"the faculty alone","definition":"The noun names the power itself, while the phrase adds the notion of a measurable capacity.","definitionCN":"名词指能力本身，而词组加上了「可被度量的容量」这一层。"},{"word":"capability","ipa":"/kəˈpæbəti/","tag":"different root","definition":"From a Latin verb meaning 'to take or hold', so it shares the idea of holding but not the root of ability; it often implies a developed skill.","definitionCN":"来自意为「拿取、握住」的拉丁动词，与 ability 共享「握」的意象但词根不同；常暗含已练成的技能。"},{"word":"intellectual","ipa":"/ˌɪntəˈlektʃuəl/","tag":"adjective or person","definition":"The adjective describes something belonging to thought, and as a noun it names a person, not the capacity.","definitionCN":"形容词描写属于思维的事物；作名词时指人，而不是能力。"},{"word":"intellectualism","ipa":"/ˌɪntəˈlektʃuəlɪzəm/","tag":"an outlook","definition":"The same base with a suffix for a doctrine: it names an attitude that overvalues the intellect.","definitionCN":"同一词基加表示学说的后缀：指一种过分推崇理智的态度。"}]},{"heading":"NEAR MEANING","entries":[{"word":"intelligence","ipa":"/ˈɪntelɪdʒəns/","tag":"the common label","definition":"The everyday and technical word for the capacity to learn and reason; testing traditions often treat the two as interchangeable.","definitionCN":"指学习与推理能力的日常及技术用词；测验传统常把两者当作可互换。"},{"word":"cognitive ability","ipa":"/ˈkɒɡnətɪv əˈbɪləti/","tag":"broader","definition":"It covers perception and memory as well as reasoning, so it is wider than the intellectual part alone.","definitionCN":"还涵盖知觉与记忆，因此比单指理智部分更宽。"},{"word":"aptitude","ipa":"/ˈæptɪtjuːd/","tag":"readiness to learn","definition":"It stresses readiness for a particular kind of training rather than general mental power.","definitionCN":"强调对某类训练的准备程度，而非一般心智能力。"},{"word":"mental capacity","ipa":"/ˈmentl kəˈpæsəti/","tag":"also a legal term","definition":"It can mean the same thing in ordinary use, but in law it names the ability to make one's own decisions.","definitionCN":"日常用法可同义，但在法律中指自行作决定的能力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Two roots meet here: one for picking out, one for holding. Ability is what the mind can keep hold of.","cn":"两个词根在此相遇：一个表示挑出，一个表示持有。能力就是心智握得住的东西。"},{"en":"The family runs intellect, intellectual, ability, capable, capability.","cn":"同族词包括 intellect、intellectual、ability、capable、capability。"},{"en":"Fixed phrases come from testing: measure, assess and score intellectual ability.","cn":"固定搭配多来自测验：测量、评估、给智力打分。"},{"en":"The first word belongs to reasoning and reading; the second belongs to holding and handling.","cn":"第一个词属于推理与阅读；第二个词属于持有与操控。"},{"en":"Psychologists often say cognitive ability when they want to include memory and perception.","cn":"心理学家想说包含记忆与知觉时，常说认知能力。"}],"abstract":[{"en":"Picture a net thrown over a heap of loose ideas until they hold together.","cn":"想象一张网罩在一堆散乱的想法上，直到它们彼此连住。"},{"en":"Picture a hand that can carry more than it can lift.","cn":"想象一只手能拿住的比它能举起的多。"},{"en":"Picture a staircase whose height is measured before anyone climbs it.","cn":"想象一段楼梯，在有人爬之前就被量好了高度。"}]},"examples":[{"en":"Intellectual ability develops fastest when children are asked to explain their answers.","cn":"当孩子被要求解释自己的答案时，智力发展得最快。"},{"en":"The job requires intellectual ability rather than physical strength.","cn":"这份工作要求的是智力，而不是体力。"},{"en":"Scores of intellectual ability predict school success only imperfectly.","cn":"智力分数对学业成功的预测并不完美。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"intellectual（属于理解的）+ ability（拿得住的能力）＝ 心智握得住观念的本事 → 智力、心智能力。","word":"intellectual ability"},"root":"前半 intellectual 来自晚期拉丁 intellectualis「属于理解力的」，源自 intellegere「理解」，一般分析为 inter「在……之间」+ legere「挑出」；后半 ability 来自拉丁 habilitas「适宜」，源自 habilis「合手的」，再上溯 habere「持有」。两半词根不同，一处关乎「挑出」，一处关乎「握持」。","sensesIntro":{"en":"Eight senses follow one capacity that has to take hold of ideas. It can be named in general, narrowed to abstraction, turned into a score, seen as learning, tested on new problems, sharpened into judgment, renamed by psychologists, and read as a forecast for school.","cn":"八个义项沿一种必须握得住观念的容量展开。它可以被一般地命名、收窄到抽象、变成分数、被看作学习、用新问题来检验、磨成判断、被心理学家改名，最后被读成对学业的预测。"},"semanticMap":{"core":{"en":"CORE IMAGE: a net drawn over scattered ideas until they can be carried.","cn":"核心意象：一张网罩住散乱的想法，直到它们能被拿走。"},"chain":["A MIND THAT HOLDS","GRASPING RELATIONS","TAKING IN NEW THINGS","WORKING WITHOUT A SCRIPT","WEIGHING AND DECIDING","PUTTING A NUMBER ON IT"],"branches":[{"senses":"01 · 02","en":"GRIP AND GRIP ON SHAPES: the general capacity, then the part of it that handles rules and relations.","cn":"握力与握住形状：先是一般容量，再是其中处理规则与关系的部分。"},{"senses":"03","en":"THE NUMBER: a standardized instrument turns the capacity into something reportable.","cn":"数字：标准化工具把容量变成可以报告的东西。"},{"senses":"04 · 05","en":"TWO KINDS OF USE: taking something in, and finding a way when nothing familiar helps.","cn":"两种用法：把东西纳进来，以及在无熟悉路径时找出路。"},{"senses":"06","en":"THE COMMITMENT: understanding that must finally accept or reject.","cn":"表态：最终必须接受或拒绝的理解。"},{"senses":"07 · 08","en":"RENAMED AND FORECAST: the psychologist's wider label, and the school's forward-looking reading.","cn":"改名与预测：心理学家更宽的标签，以及学校面向未来的读法。"}]},"affixes":{"intro":{"en":"The phrase is built from two Latin borrowings, each with its own suffix, so it can be read as four pieces.","cn":"这个词组由两个拉丁借词构成，每个各带自己的后缀，因此可以读成四块。"},"latinIntro":{"en":"One half comes from the verb for picking out and reading, the other from the verb for holding; the two families stay separate in Latin.","cn":"一半来自表示「挑出、读」的动词，另一半来自表示「持有」的动词；这两个词族在拉丁语里是分开的。"},"items":[{"word":"inter-","structure":"inter- (Latin prefix, 'between')","meaning":"between","meaningCN":"在……之间","example":"The prefix places understanding in the gaps between things.","exampleCN":"这个前缀把理解放在事物之间的空隙里。"},{"word":"legere","structure":"legere (Latin verb, 'to pick out, read')","meaning":"to pick out; to read","meaningCN":"挑出；读","example":"The root supplies the first half of the phrase.","exampleCN":"这个词根提供词组的前半。"},{"word":"-al","structure":"-alis (Latin adjective ending, 'belonging to')","meaning":"belonging to","meaningCN":"属于……的","example":"The ending makes an adjective from a noun.","exampleCN":"这个词尾把名词变成形容词。"},{"word":"habere","structure":"habere (Latin verb, 'to hold, have')","meaning":"to hold","meaningCN":"持有","example":"The second half begins with the idea of holding.","exampleCN":"后半从「持有」这个意思开始。"},{"word":"habilis","structure":"habere + -ilis ('easy to')","meaning":"easy to handle, apt","meaningCN":"易于操控的；合手的","example":"What is easy to hold becomes what is easy to do.","exampleCN":"容易握住的东西，变成了容易做到的事。"},{"word":"ability","structure":"habilis + -ity (noun of quality)","meaning":"capacity to do something","meaningCN":"做事的能力","example":"Ability is the power to hold a task steady.","exampleCN":"能力就是把任务握稳的力量。"},{"word":"intellectual","structure":"intellect + -ual","meaning":"of the understanding","meaningCN":"属于理解力的","example":"The work was an intellectual one.","exampleCN":"那是一件智力性的工作。"},{"word":"intellectual ability","structure":"intellectual + ability","meaning":"capacity of the understanding","meaningCN":"理解力的容量","example":"The test measured intellectual ability.","exampleCN":"这项测验测量智力。"},{"word":"capability","structure":"capere + -ability","meaning":"capacity, often a developed one","meaningCN":"能力，常指已练成的","example":"The two nouns look alike but rest on different verbs.","exampleCN":"这两个名词形近，却立在不同的动词上。"}],"latinEntries":[{"word":"intellectualis","structure":"intellectualis, intellectuale (adj., late Latin)","meaning":"of the understanding","meaningCN":"属于理解力的"},{"word":"habilitas","structure":"habilitas, habilitatis (f., third declension)","meaning":"aptness, fitness","meaningCN":"合宜；适宜"},{"word":"habilis","structure":"habilis, habile (adj.)","meaning":"easy to handle, apt","meaningCN":"易于操控的；合手的"},{"word":"habere","structure":"habere, habui, habitum (verb, second conjugation)","meaning":"to hold, have","meaningCN":"持有；拥有"}],"derivatives":[{"word":"intellectual","pos":"adj./n.","zh":"智力的 / 知识分子（拉丁词干「理解」，后缀表示「属于」）"},{"word":"ability","pos":"n.","zh":"能力（拉丁词根「持有」加「易于」后缀，由「拿得稳」转为「做得来」）"},{"word":"intellectually","pos":"adv.","zh":"在智力方面（形容词加副词后缀）"},{"word":"intellectually disabled","pos":"adj. phrase","zh":"智力受损的（短语，用于描述智力功能受限）"}]}},{"word":"reasoning","ipa_uk":"/ˈriːzənɪŋ/","ipa_us":"/ˈriːzənɪŋ/","definition_zh":"推理；论证；推理能力；思路","definition_en":"the process of thinking in steps from evidence to a conclusion, or the argument that results","core_image":"白板上三行证据，箭头一条接一条，最后指向一个被圈起来的结论","scene":"辩论社的教室里，学生把三条证据依次写在白板上，再用箭头标出它们指向的结论。Her reasoning moved step by step from three observations to one careful conclusion.","sceneCN":"这里 reasoning 指「由证据一步步推到结论的过程」（第 1 个义项：推理过程）；句意为她的推理从三条观察一步一步走到一个谨慎的结论。","pos":[{"tag":"n.","zh":"推理；论证；推理能力（不可数指过程，可数指一套论证）"}],"collocations":[{"phrase":"line of reasoning","zh":"思路；论证路线"},{"phrase":"logical reasoning","zh":"逻辑推理"},{"phrase":"faulty reasoning","zh":"有谬误的推理"},{"phrase":"mathematical reasoning","zh":"数学推理"},{"phrase":"reasoning skills","zh":"推理能力"},{"phrase":"follow someone's reasoning","zh":"跟上某人的论证"},{"phrase":"sound reasoning","zh":"可靠的推理"}],"forms":[{"label":"复数","form":"reasonings"},{"label":"动词","form":"reason"},{"label":"形容词（作定语，如推理过程）","form":"reasoning"},{"label":"名词（理性）","form":"reason"},{"label":"形容词（有理性的）","form":"rational"}],"derivatives":[{"word":"reason","pos":"n./v.","zh":"原因；理性 / 推理（本词的动词原形，拉丁词根意为「计算、思量」）"},{"word":"rational","pos":"adj.","zh":"理性的；合理的（同词根加形容词后缀，指合乎计算与权衡）"},{"word":"rationale","pos":"n.","zh":"理由说明；原理（同词根的名词，指一套背后的道理）"},{"word":"reasoner","pos":"n.","zh":"推理者（动词加表施动者的后缀）"}],"senses":[{"no":"01","title":"The process of drawing a conclusion","titleCN":"推理过程","definition":"the mental process of moving in steps from evidence or premises to a conclusion","definitionCN":"从证据或前提出发、分步骤走向结论的心理过程","example":"Her reasoning moved step by step from three observations to one careful conclusion.","exampleCN":"她的推理从三条观察一步步走到一个谨慎的结论。","why":"The Latin noun meant 'reckoning', so reasoning is the mind doing arithmetic on ideas.","whyCN":"拉丁名词意为「计算」，所以推理就是心智在对观念做算术。"},{"no":"02","title":"A chain of argument","titleCN":"一套论证","definition":"the linked statements produced by that process, viewed as an object one can inspect","definitionCN":"由该过程产生的、可被逐条检视的关联陈述","example":"The examiner could not fault the reasoning, only the data.","exampleCN":"考官挑不出这套论证的毛病，只能挑数据的毛病。","why":"Once the steps are written down, the process becomes a structure that others can check.","whyCN":"一旦步骤被写下来，过程就变成一个别人可以核查的结构。"},{"no":"03","title":"The faculty of reason","titleCN":"理性能力","definition":"the underlying power of mind that makes such step-by-step thinking possible","definitionCN":"使这种分步思考得以发生的底层心智能力","example":"Reasoning is what separates a proof from an assertion.","exampleCN":"正是理性能力把证明与断言区别开来。","why":"A process needs a power behind it, and the same noun names both the doing and the capacity.","whyCN":"过程背后需要一种能力，同一个名词因此既指所做之事，也指那种能力。"},{"no":"04","title":"A trainable skill","titleCN":"可训练的推理能力","definition":"the capacity as something that can be improved by practice and instruction","definitionCN":"可以通过练习与教学提高的那种能力","example":"The course teaches reasoning through puzzles rather than lectures.","exampleCN":"这门课用谜题而不是讲授来训练推理能力。","why":"What can be learned can be named as a skill, and the word shifts from a gift to a curriculum.","whyCN":"能被学会的东西可以被命名为技能，这个词于是从天赋转为课程内容。"},{"no":"05","title":"A line of reasoning","titleCN":"思路、论证路线","definition":"the particular route a thinker takes, including its starting point and its order","definitionCN":"思考者所走的具体路径，包括起点与顺序","example":"I lost the line of reasoning when the speaker changed examples.","exampleCN":"讲者换了例子，我就跟不上这条思路了。","why":"Two people can reach the same end by different routes, so the word also names the route.","whyCN":"两个人可以走不同的路径到达同一终点，因此这个词也指那条路径。"},{"no":"06","title":"Legal reasoning","titleCN":"法律推理","definition":"the disciplined method by which courts apply rules to facts","definitionCN":"法院把规则适用于事实时所遵循的受训练的方法","example":"Legal reasoning binds the conclusion to the statute, not to the judge's mood.","exampleCN":"法律推理把结论绑在法条上，而不是绑在法官的情绪上。","why":"Courts must show that a result follows from published rules, so this is the same step-taking under an institutional constraint.","whyCN":"法院必须表明结果是由公布过的规则推出的，因此这是同一套分步思考在制度约束下的形态。"},{"no":"07","title":"Faulty reasoning","titleCN":"有谬误的推理","definition":"thinking that breaks a rule of inference while still sounding persuasive","definitionCN":"违反推理规则、听起来却仍有说服力的思考","example":"The report's faulty reasoning survived because nobody checked the second step.","exampleCN":"那份报告的推理有谬误，却因为没人核查第二步而留了下来。","why":"A step can be skipped while the surface still persuades, and the word marks exactly that kind of failure.","whyCN":"步骤可以被跳过而表面仍有说服力，这个词标记的正是这类失败。"},{"no":"08","title":"Mathematical reasoning","titleCN":"数学推理","definition":"the form of step-by-step thinking that works with symbols, definitions and proofs","definitionCN":"以符号、定义与证明为对象的分步思考形式","example":"Mathematical reasoning demands that every step be justified.","exampleCN":"数学推理要求每一步都有依据。","why":"Symbols strip away subject matter and leave only relations, which is the purest version of the same walking.","whyCN":"符号剥去题材，只留下关系，这是同一种行走最纯粹的版本。"}],"etymology":{"intro":{"en":"Reasoning is the English noun formed from the verb reason with the ending that names an activity. The Latin source is a noun meaning 'reckoning' or 'account'.","cn":"reasoning 是由动词 reason 加表活动的词尾构成的英语名词。它的拉丁来源是一个意为「计算、账目」的名词。"},"items":[{"era":"LATIN RERI","en":"The verb meant 'to reckon, calculate, think'. Thinking was pictured as counting, which is why the family keeps the image of a sum.","cn":"这个动词意为「计算、估量、思考」。思考被描绘成数数，因此这个词族一直保留着「求和」的画面。"},{"era":"LATIN RATIO","en":"The noun meant 'reckoning, account, method, reason'. It could name a business account as easily as a chain of thought.","cn":"这个名词意为「计算、账目、方法、理性」。它既能指生意上的账，也能指一串思路。"},{"era":"LATIN RATUS","en":"The past participle meant 'reckoned, settled, fixed'. What has been settled can be relied on, which explains the later sense of something confirmed.","cn":"过去分词意为「已算清、已定下、已固定」。算清的东西可以依靠，这解释了后来「已确认」的意思。"},{"era":"OLD FRENCH","en":"Old French carried the noun into English in the twelfth century, where it first named a statement offered in explanation or defence.","cn":"古法语在 12 世纪把这个名词带入英语，最初指为解释或辩护而提出的说法。"},{"era":"MODERN ENGLISH","en":"The verbal noun in -ing was fixed in the sixteenth century for the activity of drawing conclusions, and later for the argument produced.","cn":"带这个动名词词尾的说法在 16 世纪固定下来，指得出结论的活动，后又指所产生的论证。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper Indo-European root proposed for the verb is a reconstructed form, and the exact relation between the counting and thinking senses is not settled.","cn":"来源不确定：为该动词提出的更深印欧词根属重构形式，「计算」与「思考」两义的确切关系也没有定论。"}]},"similar":{"note":{"en":"The first group holds forms and relatives of one root that get swapped in writing; the second holds other names for thinking in steps.","cn":"第一组是同一词根的形式与亲属词，写作时常被互换；第二组是其他表示「分步思考」的名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reason","ipa":"/ˈriːzn/","tag":"the verb and the faculty","definition":"The base verb and the noun for the faculty or a cause; reasoning is the activity or its product.","definitionCN":"基础动词，以及指官能或原因的名词；reasoning 指活动本身或其产物。"},{"word":"rationale","ipa":"/ˌræʃəˈnɑːl/","tag":"the stated grounds","definition":"Same root, but it names the explanation offered for a decision rather than the steps taken to reach it.","definitionCN":"同词根，但指为一个决定给出的说明，而非走到它的那些步骤。"},{"word":"rational","ipa":"/ˈræʃənl/","tag":"the adjective","definition":"It describes a person or act as following reason; it never names the chain of steps.","definitionCN":"形容人或行为合乎理性；它从不指那串步骤。"},{"word":"reasoning","ipa":"/ˈriːzənɪŋ/","tag":"spelling trap","definition":"Note the dropped vowel in the middle: the noun keeps the short form of the stem, and the doubled consonant of the participle does not appear.","definitionCN":"注意中段元音被略去：名词保留了词干的短形式，也没有出现分词里那个重复的辅音。"}]},{"heading":"NEAR MEANING","entries":[{"word":"logic","ipa":"/ˈlɒdʒɪk/","tag":"the rules","definition":"From a Greek word for word and reason: it names the system of rules that reasoning should follow.","definitionCN":"来自希腊语中指「言辞、理性」的词：指推理应当遵循的那套规则。"},{"word":"argument","ipa":"/ˈɑːɡjumənt/","tag":"the whole case","definition":"The complete case, premises plus conclusion, often with the purpose of persuading.","definitionCN":"完整的论证，包括前提与结论，常带说服目的。"},{"word":"inference","ipa":"/ˈɪnfərəns/","tag":"the single step","definition":"One move from what is known to what follows; reasoning is the whole series of such moves.","definitionCN":"从已知到推出的单步；reasoning 是这类步骤的整串。"},{"word":"thinking","ipa":"/ˈθɪŋkɪŋ/","tag":"much broader","definition":"Any mental activity at all, including imagining and remembering, where reasoning must be disciplined.","definitionCN":"泛指任何心理活动，包括想象与回忆，而推理必须是受约束的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin noun meant 'reckoning', so reasoning is counting your way to a conclusion.","cn":"拉丁名词意为「计算」，所以推理就是一路数到结论。"},{"en":"The family runs reason, reasoning, rational, rationale, reasoner.","cn":"同族词包括 reason、reasoning、rational、rationale、reasoner。"},{"en":"Fixed phrases mark it as a route: a line of reasoning, follow the reasoning, sound reasoning.","cn":"固定搭配把它标成一条路线：思路、跟上论证、可靠的推理。"},{"en":"Two fields give it a fixed form: legal reasoning and mathematical reasoning.","cn":"两个领域给了它固定形态：法律推理与数学推理。"},{"en":"The word names both the activity and the written argument it leaves behind.","cn":"这个词既指活动，也指活动留下的那套书面论证。"}],"abstract":[{"en":"Picture stepping stones across water, each one close enough to reach.","cn":"想象水面上的一串踏脚石，每一块都近得够得着。"},{"en":"Picture a receipt for every claim, kept in a drawer.","cn":"想象每一个主张都有一张收据，收在抽屉里。"},{"en":"Picture a route drawn on a map, with the crossings numbered.","cn":"想象地图上画出的一条路线，每个转折都编了号。"}]},"examples":[{"en":"The judge praised the clarity of the student's reasoning.","cn":"评委称赞这名学生论证清晰。"},{"en":"One weak link in the reasoning brought down the whole conclusion.","cn":"论证中一个薄弱的环节让整个结论垮掉。"},{"en":"Training in reasoning improves performance on unfamiliar problems.","cn":"推理训练能提高解决陌生问题的表现。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"reason（计算、思量）+ ing（进行中）＝ 一步步算下去的过程 → 推理、论证。","word":"reasoning"},"root":"来自拉丁名词 ratio「计算、账目、方法、理性」，源自 reri「计算、思量」，过去分词 ratus 意为「已算清、已定下」；更早印欧词根属重构形式。同族有 reason、rational、rationale、ratify。","sensesIntro":{"en":"Eight senses follow one walk: step after step from what is known to what follows. The walk can be named as an activity, inspected as a written chain, traced to the power behind it, trained, followed as a route, fixed by law, broken by error, or sharpened into proof.","cn":"八个义项沿一次行走展开：从已知之物一步一步走到随之而来的结论。这次行走可以作为活动被命名、作为书面链条被检视、被追到背后的能力、被训练、被当作路线跟随、被法律固定、被错误打断，或被磨成证明。"},"semanticMap":{"core":{"en":"CORE IMAGE: stepping stones laid across water, one after another.","cn":"核心意象：一块接一块铺过水面的踏脚石。"},"chain":["COUNTING IT OUT","STEP AFTER STEP","THE CHAIN WRITTEN DOWN","THE POWER BEHIND THE STEPS","A ROUTE OTHERS CAN FOLLOW","A STEP THAT FAILS"],"branches":[{"senses":"01 · 03","en":"WALK AND WALKER: the activity, and the capacity that makes anyone able to take the steps.","cn":"行走与行路人：活动本身，以及使任何人能迈出这些步骤的能力。"},{"senses":"02 · 05","en":"CHAIN AND ROUTE: the finished series, and the particular path chosen through it.","cn":"链条与路线：完成的整串，以及在其中的那条具体路径。"},{"senses":"04","en":"TRAINED FEET: what can be practised becomes a skill with exercises.","cn":"受过训练的脚：可以练习的东西变成有习题的技能。"},{"senses":"06 · 08","en":"TWO DISCIPLINED FORMS: the courtroom and the proof both insist that every step be licensed.","cn":"两种受约束的形式：法庭与证明都坚持每一步都要有依据。"},{"senses":"07","en":"THE BROKEN STEP: one unjustified move is enough to bring the whole path down.","cn":"断掉的一步：一个没有依据的动作就足以让整条路塌掉。"}]},"affixes":{"intro":{"en":"Reasoning is a verb plus an ending that turns it into the name of an activity, and the root behind the verb also builds several abstract nouns.","cn":"reasoning 是动词加一个使它成为活动名称的词尾，动词背后的词根还构成若干抽象名词。"},"latinIntro":{"en":"The reckoning root gives the noun for an account, the adjective for what is calculated, and the noun for a stated ground.","cn":"这个「计算」词根给出指账目的名词、指「已算定的」形容词，以及指所陈理由的名词。"},"items":[{"word":"reri","structure":"reri, ratus sum (Latin deponent verb)","meaning":"to reckon, think","meaningCN":"计算；思量","example":"The root treats thought as a kind of counting.","exampleCN":"这个词根把思考当作一种数数。"},{"word":"ratio","structure":"ratio, rationis (f., third declension)","meaning":"reckoning, account, reason","meaningCN":"计算；账目；理性","example":"The noun covers both a ledger and a chain of thought.","exampleCN":"这个名词同时涵盖账簿与思路。"},{"word":"reason","structure":"reason (English noun and verb, from the Latin noun)","meaning":"a cause; the faculty; to think","meaningCN":"原因；理性；推理","example":"She reasoned until the answer appeared.","exampleCN":"她一路推理，直到答案出现。"},{"word":"-ing","structure":"-ing (English ending forming a verbal noun)","meaning":"the activity of doing something","meaningCN":"做某事的过程","example":"The ending turns a verb into the name of its activity.","exampleCN":"这个词尾把动词变成其活动的名称。"},{"word":"reasoning","structure":"reason + -ing","meaning":"the activity of concluding","meaningCN":"得出结论的活动","example":"Her reasoning moved from evidence to conclusion.","exampleCN":"她的推理从证据走到结论。"},{"word":"rational","structure":"ratio + -al (adjective ending)","meaning":"following calculation and reason","meaningCN":"合乎计算与理性的","example":"A rational choice can still be a wrong one.","exampleCN":"合乎理性的选择仍可能选错。"},{"word":"rationale","structure":"rational + -e (noun of grounds)","meaning":"the stated reason for something","meaningCN":"所陈述的理由","example":"The report gave no rationale for the cut.","exampleCN":"报告没有为这次削减给出理由。"},{"word":"reasoner","structure":"reason + -er (one who acts)","meaning":"a person who reasons","meaningCN":"推理者","example":"A careful reasoner checks the second step.","exampleCN":"谨慎的推理者会核查第二步。"},{"word":"ratify","structure":"ratus + -ify (to make)","meaning":"to confirm formally","meaningCN":"正式批准","example":"What is reckoned and settled can be formally confirmed.","exampleCN":"算清并定下的事可以被正式确认。"}],"latinEntries":[{"word":"reri","structure":"reri, ratus sum (deponent verb, third conjugation)","meaning":"to reckon, calculate, think","meaningCN":"计算；估量；思考"},{"word":"ratio","structure":"ratio, rationis (f., third declension)","meaning":"reckoning, account, reason","meaningCN":"计算；账目；理性"},{"word":"ratus","structure":"ratus, rata, ratum (adj.)","meaning":"reckoned, settled, fixed","meaningCN":"已算清的；已定下的"},{"word":"rationalis","structure":"rationalis, rationale (adj.)","meaning":"of reason, rational","meaningCN":"理性的；合乎理性的"}],"derivatives":[{"word":"reason","pos":"n./v.","zh":"原因；理性 / 推理（本词的动词原形，拉丁词根意为「计算、思量」）"},{"word":"rational","pos":"adj.","zh":"理性的；合理的（同词根加形容词后缀，指合乎计算与权衡）"},{"word":"rationale","pos":"n.","zh":"理由说明；原理（同词根的名词，指一套背后的道理）"},{"word":"reasoner","pos":"n.","zh":"推理者（动词加表施动者的后缀）"}]}},{"word":"reason","ipa_uk":"/ˈriːzn/","ipa_us":"/ˈriːzn/","definition_zh":"原因；理由；理性；推理；说服","definition_en":"a cause or justification for something, the power of logical thought, or the act of thinking and arguing","core_image":"会议室的白板上写着一条结论，旁边拉出三条箭头，每条箭头起点都标着一个事实","scene":"会议室的灯还亮着，经理把两份报表并排摆在桌上，问团队为什么差额会这么大。Nobody could give a clear reason for the sudden fall in sales.","sceneCN":"这里 reason 指「解释某事为何发生的原因」（第 1 个义项：事情的成因）；句意为没有人能为销售额的骤降给出一个清楚的原因。","pos":[{"tag":"n.","zh":"原因；理由；理性；情理"},{"tag":"v.","zh":"推理；思考；说服（与某人讲理）"}],"collocations":[{"phrase":"the reason for","zh":"……的原因"},{"phrase":"for this reason","zh":"因此；出于这个原因"},{"phrase":"for reasons of","zh":"出于……的考虑"},{"phrase":"within reason","zh":"在合理范围内"},{"phrase":"reason with someone","zh":"与某人讲理"},{"phrase":"by reason of","zh":"由于（正式）"},{"phrase":"the main reason","zh":"主要原因"}],"forms":[{"label":"三单（he/she/it）","form":"reasons"},{"label":"过去式","form":"reasoned"},{"label":"过去分词","form":"reasoned"},{"label":"现在分词","form":"reasoning"},{"label":"复数（名词）","form":"reasons"},{"label":"形容词","form":"reasonable"}],"derivatives":[{"word":"reasoning","pos":"n.","zh":"推理；论证（动词加表活动的后缀）"},{"word":"reasonable","pos":"adj.","zh":"合理的；讲理的（名词加「能够……」的后缀）"},{"word":"rational","pos":"adj.","zh":"理性的（同词根加形容词后缀）"},{"word":"reasonably","pos":"adv.","zh":"合理地（形容词加副词后缀）"}],"senses":[{"no":"01","title":"A cause of something","titleCN":"事情的原因","definition":"the cause that explains why an event happened","definitionCN":"解释某事为何发生的成因","example":"Nobody could give a clear reason for the sudden fall in sales.","exampleCN":"没有人能为销售额的骤降给出一个清楚的原因。","why":"The Latin noun meant 'account', and an account explains where a number came from.","whyCN":"拉丁名词意为「账目」，而账目说明一个数字从何而来。"},{"no":"02","title":"A justification","titleCN":"理由、依据","definition":"a ground offered in defence of an action or belief","definitionCN":"为某个行动或信念作辩解而提出的依据","example":"She gave a reason for missing the deadline, but not a good one.","exampleCN":"她为错过期限给了理由，但不是个好理由。","why":"The same structure that explains can also excuse, so cause slides into justification.","whyCN":"能解释的结构也能开脱，因此「成因」滑向「辩解」。"},{"no":"03","title":"The faculty of logic","titleCN":"理性","definition":"the human power of forming judgments in a disciplined way","definitionCN":"人以受约束的方式作出判断的能力","example":"Reason separates a proof from an assertion.","exampleCN":"理性把证明与断言分开。","why":"A capacity for accounts becomes, in philosophy, the name of the capacity itself.","whyCN":"在哲学里，会算账的能力变成了这种能力本身的名称。"},{"no":"04","title":"To think logically","titleCN":"推理、思考","definition":"to work something out step by step in the mind","definitionCN":"在心里一步一步想出某事","example":"He reasoned that the train must have left early.","exampleCN":"他推断列车一定是提前开走了。","why":"The noun becomes a verb: doing what the faculty does, which is to calculate toward a conclusion.","whyCN":"名词转为动词：做那种官能所做的事，也就是算向一个结论。"},{"no":"05","title":"To argue a case","titleCN":"论证、推断","definition":"to present linked grounds for a conclusion, usually in speech or writing","definitionCN":"为结论提出相互关联的依据，通常在口头或书面中","example":"The paper reasons from three studies to a single policy.","exampleCN":"这篇论文从三项研究推导出一项政策。","why":"Thinking made public becomes an argument, and the verb covers both the silent and the spoken form.","whyCN":"思考公开出来就成了论证，而这个动词同时涵盖无声与有声的形式。"},{"no":"06","title":"To persuade by talking","titleCN":"劝服、讲理","definition":"to bring someone to a view by presenting grounds rather than by force","definitionCN":"以陈述依据而非强制的方式使某人接受某种看法","example":"We tried to reason with the crowd at the gate.","exampleCN":"我们试着和门口的人群讲理。","why":"Reasoning aimed at another person becomes an attempt at persuasion.","whyCN":"指向他人的推理就变成一次说服的尝试。"},{"no":"07","title":"Sanity and moderation","titleCN":"情理、适度","definition":"in fixed phrases, the quality of staying sensible and not excessive","definitionCN":"在固定说法中，指保持明理而不走极端的性质","example":"The price was high, but within reason.","exampleCN":"价格是高了些，但还在合理范围内。","why":"A person who can reckon is a person who does not overshoot, and the word names that restraint.","whyCN":"会计算的人不会越过限度，于是这个词也指这种节制。"},{"no":"08","title":"Grounds in formal phrasing","titleCN":"由于、凭借（正式说法）","definition":"in fixed legal and official phrases, the basis on which something is done","definitionCN":"在法律与公文的固定说法中，指做某事的依据","example":"The permit was refused by reason of a missing signature.","exampleCN":"许可因缺少一个签名而被拒绝。","why":"Official language keeps the oldest sense of 'account' and turns it into a stated basis.","whyCN":"公文语言保留了最古老的「账目」义，并把它变成一项陈述出来的依据。"}],"etymology":{"intro":{"en":"Reason came into English from Old French, which had it from a Latin noun meaning 'reckoning, account'. The word begins as bookkeeping and ends as philosophy.","cn":"reason 经古法语进入英语，古法语则来自一个意为「计算、账目」的拉丁名词。这个词从记账开始，最后走到哲学。"},"items":[{"era":"LATIN RERI","en":"The verb meant 'to reckon, calculate, think'. Its past participle meant 'settled, fixed', and both meanings survive in the family.","cn":"这个动词意为「计算、估量、思考」。它的过去分词意为「已定下、已固定」，这两层意思都在词族里留存。"},{"era":"LATIN RATIO","en":"The noun meant 'reckoning, account, method, reason'. A merchant's ledger and a philosopher's argument were the same word.","cn":"这个名词意为「计算、账目、方法、理性」。商人的账簿与哲学家的论证用的是同一个词。"},{"era":"OLD FRENCH RAISON","en":"Old French softened the consonant and passed the noun into English in the twelfth century, first in the sense of a statement offered in explanation.","cn":"古法语软化了其中的辅音，在 12 世纪把这个名词传入英语，最初指为解释而提出的说法。"},{"era":"MIDDLE ENGLISH","en":"By the fourteenth century the word covered both the cause of an event and the human faculty, and the verb followed.","cn":"到 14 世纪，这个词已同时覆盖事件的原因与人的官能，动词形式随后出现。"},{"era":"PHILOSOPHY AND LAW","en":"Philosophers fixed the faculty sense, while legal and official formulas kept the older sense of a stated basis.","cn":"哲学家固定了「官能」义，法律与公文套语则保留了较古老的「所陈依据」义。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper Indo-European root proposed for the verb is a reconstructed form, and it is not settled how the counting sense produced the sense of thinking.","cn":"来源不确定：为该动词提出的更深印欧词根属重构形式，「计算」如何产生「思考」一义也没有定论。"}]},"similar":{"note":{"en":"The first group holds words that are constantly offered in the wrong slot; the second holds near neighbours for cause and for thinking.","cn":"第一组是常在句中放错位置的词；第二组是表示「原因」与「思考」的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cause","ipa":"/kɔːz/","tag":"the mechanism","definition":"It names what actually produces an effect, while reason names the explanation a person gives; a cause can exist with nobody knowing the reason.","definitionCN":"指实际产生结果的东西，而 reason 指人给出的解释；成因可以在无人知道理由的情况下存在。"},{"word":"reasoning","ipa":"/ˈriːzənɪŋ/","tag":"the activity","definition":"The verbal noun for the process or the argument, not for a single cause.","definitionCN":"指过程或论证的动名词，而不是单一的原因。"},{"word":"rationale","ipa":"/ˌræʃəˈnɑːl/","tag":"grounds set out","definition":"A formal statement of the grounds behind a decision, usually written after the fact.","definitionCN":"对某决定背后依据的正式陈述，通常事后写成。"},{"word":"reasonable","ipa":"/ˈriːzənəbl/","tag":"the adjective","definition":"It describes something as fair or sensible; it cannot stand where a noun is needed.","definitionCN":"形容某事公平或明理；不能放在需要名词的位置。"}]},{"heading":"NEAR MEANING","entries":[{"word":"motive","ipa":"/ˈməʊtɪv/","tag":"what drives a person","definition":"It explains why someone acted, and carries a hint of intention that cause does not.","definitionCN":"解释某人为何行动，带有 cause 所没有的意图暗示。"},{"word":"explanation","ipa":"/ˌekspləˈneɪʃn/","tag":"the full account","definition":"A complete account that makes something understandable, of which a reason may be one part.","definitionCN":"使某事可被理解的完整说明，原因可能只是其中一部分。"},{"word":"logic","ipa":"/ˈlɒdʒɪk/","tag":"the system","definition":"The formal rules of valid inference, as opposed to the faculty that uses them.","definitionCN":"有效推理的形式规则，与使用这些规则的官能相对。"},{"word":"sense","ipa":"/sens/","tag":"practical judgment","definition":"In phrases like 'good sense', it means practical wisdom rather than formal reasoning.","definitionCN":"在「判断力好」这类说法中，指实际的明智而非形式推理。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin noun meant 'account', so a reason is the account you give for a number or an act.","cn":"拉丁名词意为「账目」，所以 reason 就是你为一个数字或一个行为给出的那笔账。"},{"en":"The family runs reason, reasoning, reasonable, rational, rationale.","cn":"同族词包括 reason、reasoning、reasonable、rational、rationale。"},{"en":"Fixed phrases mark the grammar: the reason for, for this reason, within reason, by reason of.","cn":"固定搭配标出语法位置：……的原因、因此、在合理范围内、由于。"},{"en":"The word is both a noun and a verb, so it can name the cause and the act of thinking.","cn":"这个词既是名词也是动词，因此既能指原因，也能指思考的动作。"},{"en":"Philosophy keeps the faculty sense, while law keeps the older sense of a stated basis.","cn":"哲学保留「官能」义，法律则保留较古老的「所陈依据」义。"}],"abstract":[{"en":"Picture a receipt that explains every line of a bill.","cn":"想象一张能把账单每一行都解释清楚的收据。"},{"en":"Picture a door with three hinges, and each hinge a fact.","cn":"想象一扇门有三个铰链，每个铰链都是一个事实。"},{"en":"Picture a scale that refuses to tip until both pans are full.","cn":"想象一架天平，两边都不满就不肯倾斜。"}]},"examples":[{"en":"The reason for the delay was a broken signal.","cn":"延误的原因是信号故障。"},{"en":"She reasoned that the cheapest option would cost more in the end.","cn":"她推断最便宜的方案最终会花更多钱。"},{"en":"It is hard to reason with someone who will not listen.","cn":"和一个不肯听的人讲理很难。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"reason（算账）＝ 把一件事的来龙去脉算清楚 → 先指原因与理由，再指算这件事的理性与推理。","word":"reason"},"root":"经古法语 raison 来自拉丁 ratio「计算、账目、方法、理性」，源自 reri「计算、思量」，过去分词 ratus「已算清、已定下」；更深来源不确定。同族有 reasoning、reasonable、rational、rationale、ratify。","sensesIntro":{"en":"Eight senses follow one account: something is reckoned and explained. The account can be the cause of an event, a defence, the faculty that produces accounts, the act of producing one silently, the same act spoken aloud, an attempt to persuade, the restraint of staying sensible, or a formal stated basis.","cn":"八个义项沿一笔账展开：某事被算清并被说明。这笔账可以是事件的原因、一句辩解、产生账目的官能、无声地算的过程、把同一过程说出口、一次说服的尝试、保持明理的节制，或公文里陈述出来的依据。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ledger that shows where every figure came from.","cn":"核心意象：一本账，写明每个数字从何而来。"},"chain":["RECKONED ACCOUNT","WHAT PRODUCED IT","WHAT DEFENDS IT","THE MIND THAT RECKONS","RECKONING ALOUD","STILL WITHIN SENSE"],"branches":[{"senses":"01 · 08","en":"THE ACCOUNT AND ITS OFFICIAL FORM: the plain cause, then the same basis written into a formula.","cn":"账目与其公文形态：先是朴素的原因，再是同一依据被写进套语。"},{"senses":"02","en":"THE ACCOUNT AS DEFENCE: explaining becomes excusing.","cn":"作为辩解的账目：解释变成开脱。"},{"senses":"03 · 07","en":"THE RECKONER: the faculty itself, and the restraint that shows when it holds.","cn":"算账者：官能本身，以及它守住时表现出的节制。"},{"senses":"04 · 05","en":"SILENT AND SPOKEN: the same steps taken in the head and laid out for others.","cn":"无声与有声：同样的步骤，一在脑中走，一摊给别人看。"},{"senses":"06","en":"AIMED AT ANOTHER: reasoning turned into an attempt to move someone.","cn":"指向他人：推理转为推动某人的尝试。"}]},"affixes":{"intro":{"en":"Reason is a bare Latin noun with no separable English ending, but the root behind it builds a wide family of abstract words.","cn":"reason 是一个不带可分离英语词尾的拉丁名词，但它背后的词根构成了一大批抽象词。"},"latinIntro":{"en":"The reckoning root yields the account, the settled participle and the adjective for what follows reason.","cn":"这个「计算」词根产出账目、表示「已定下」的分词，以及指「合乎理性的」形容词。"},"items":[{"word":"ratio","structure":"ratio (Latin noun, 'reckoning, account')","meaning":"account; reason","meaningCN":"账目；理性","example":"The noun is the direct source of the English word.","exampleCN":"这个名词是英语词的直接来源。"},{"word":"reri","structure":"reri (Latin deponent verb, 'to reckon')","meaning":"to reckon, think","meaningCN":"计算；思考","example":"Thinking is pictured as counting.","exampleCN":"思考被描绘为数数。"},{"word":"reason","structure":"reason (English noun and verb)","meaning":"cause; faculty; to think","meaningCN":"原因；理性；推理","example":"He reasoned that the train had left early.","exampleCN":"他推断列车提前开走了。"},{"word":"reasoning","structure":"reason + -ing (verbal noun)","meaning":"the process of concluding","meaningCN":"得出结论的过程","example":"The reasoning was sound at every step.","exampleCN":"这套推理每一步都可靠。"},{"word":"reasonable","structure":"reason + -able ('capable of being')","meaning":"fair, sensible","meaningCN":"公平的；明理的","example":"The price was reasonable.","exampleCN":"价格是合理的。"},{"word":"reasonably","structure":"reasonable + -ly (adverb)","meaning":"in a sensible way","meaningCN":"合理地","example":"She answered reasonably enough.","exampleCN":"她回答得相当讲理。"},{"word":"rational","structure":"ratio + -al (adjective)","meaning":"following reason","meaningCN":"合乎理性的","example":"A rational plan can still fail.","exampleCN":"合理的计划仍可能失败。"},{"word":"rationale","structure":"rational + -e (noun)","meaning":"the stated grounds","meaningCN":"所陈述的理由","example":"No rationale was offered for the change.","exampleCN":"没有人说明这次改动的理由。"},{"word":"ratify","structure":"ratus + -ify (to make)","meaning":"to confirm formally","meaningCN":"正式批准","example":"The senate ratified the treaty.","exampleCN":"参议院批准了这项条约。"}],"latinEntries":[{"word":"reri","structure":"reri, ratus sum (deponent verb)","meaning":"to reckon, think","meaningCN":"计算；思考"},{"word":"ratio","structure":"ratio, rationis (f., third declension)","meaning":"reckoning, account, reason","meaningCN":"计算；账目；理性"},{"word":"ratus","structure":"ratus, rata, ratum (adj.)","meaning":"settled, fixed","meaningCN":"已定下的；固定的"},{"word":"rationabilis","structure":"rationabilis, rationabile (adj.)","meaning":"reasonable, rational","meaningCN":"合理的；有理性的"}],"derivatives":[{"word":"reasoning","pos":"n.","zh":"推理；论证（动词加表活动的后缀）"},{"word":"reasonable","pos":"adj.","zh":"合理的；讲理的（名词加「能够……」的后缀）"},{"word":"rational","pos":"adj.","zh":"理性的（同词根加形容词后缀）"},{"word":"reasonably","pos":"adv.","zh":"合理地（形容词加副词后缀）"}]}},{"word":"logical","ipa_uk":"/ˈlɒdʒɪkl/","ipa_us":"/ˈlɑːdʒɪkl/","definition_zh":"合乎逻辑的；合理的；逻辑学的；条理清楚的","definition_en":"following the rules of valid inference, or sensible and well ordered","core_image":"黑板上每一步都从上一行推出，写完最后一行时，结论已经无处可躲","scene":"数学教室的黑板上，老师把条件一行行写下去，最后一行还没落笔，后排已经有学生点头。The argument was logical at every step, so the conclusion seemed unavoidable.","sceneCN":"这里 logical 指「每一步都由前一步合法推出」（第 1 个义项：合乎有效推理）；句意为这个论证每一步都合乎逻辑，所以结论显得无法回避。","pos":[{"tag":"adj.","zh":"合乎逻辑的；合理的；逻辑学的；有条理的"}],"collocations":[{"phrase":"logical conclusion","zh":"合乎逻辑的结论"},{"phrase":"logical step","zh":"合乎逻辑的一步"},{"phrase":"logical order","zh":"逻辑顺序"},{"phrase":"logical possibility","zh":"逻辑上的可能性"},{"phrase":"logical reasoning","zh":"逻辑推理"},{"phrase":"the logical choice","zh":"合乎情理的选择"}],"forms":[{"label":"比较级","form":"more logical"},{"label":"最高级","form":"most logical"},{"label":"副词","form":"logically"},{"label":"名词（逻辑）","form":"logic"},{"label":"名词（逻辑性）","form":"logicalness"},{"label":"名词（逻辑学者）","form":"logician"}],"derivatives":[{"word":"logic","pos":"n.","zh":"逻辑；逻辑学（希腊词根「言辞、理性」，由「说话」转为「推理规则」）"},{"word":"logically","pos":"adv.","zh":"逻辑上；必然地（形容词加副词后缀）"},{"word":"logician","pos":"n.","zh":"逻辑学家（名词词干加表从业者的后缀）"},{"word":"logicalness","pos":"n.","zh":"合乎逻辑的性质（形容词加名词后缀）"}],"senses":[{"no":"01","title":"Following valid inference","titleCN":"合乎有效推理的","definition":"arranged so that each step is licensed by the rules of inference","definitionCN":"安排得使每一步都由推理规则许可","example":"The argument was logical at every step, so the conclusion seemed unavoidable.","exampleCN":"这个论证每一步都合乎逻辑，所以结论显得无法回避。","why":"The Greek root means 'word' and 'reason at work', so the adjective first says that the arrangement follows reason's rules.","whyCN":"希腊词根意为「言辞」与「运作中的理性」，因此这个形容词首先说明安排合乎理性的规则。"},{"no":"02","title":"Sensible and practical","titleCN":"合理的、明智的","definition":"being the choice or arrangement that a sensible person would make","definitionCN":"是明理的人会作出的选择或安排","example":"Taking the earlier train was the logical thing to do.","exampleCN":"坐早一班车才是合理的做法。","why":"Outside formal proof, valid inference is replaced by ordinary good judgment, and the word follows the looser use.","whyCN":"在形式证明之外，有效推理被日常判断替代，这个词也随这种较松的用法走。"},{"no":"03","title":"Belonging to the discipline of logic","titleCN":"逻辑学的","definition":"relating to logic as a formal subject of study","definitionCN":"与作为正式研究科目的逻辑学相关","example":"A logical system needs rules for negation before it can do anything else.","exampleCN":"一个逻辑系统先要有否定规则，才谈得上做别的。","why":"Once the discipline was named, its adjective began to describe the objects inside it.","whyCN":"学科一旦被命名，它的形容词就开始描写学科内部的对象。"},{"no":"04","title":"Internally consistent","titleCN":"前后一致的","definition":"not contradicting itself, so that the parts can hold together","definitionCN":"不自相矛盾，因此各部分能彼此撑住","example":"The account was logical but built on a false premise.","exampleCN":"这套说法前后一致，却建立在一个假前提上。","why":"Consistency is the minimum that reasoning requires: no step may cancel an earlier one.","whyCN":"自洽是推理的最低要求：任何一步都不能取消前面某一步。"},{"no":"05","title":"The expected next step","titleCN":"顺理成章的、必然的","definition":"following so directly that it appears forced","definitionCN":"接得如此直接，以致显得非如此不可","example":"Retirement was the logical end of a forty-year career.","exampleCN":"退休是四十年职业生涯顺理成章的终点。","why":"When the chain is tight, the last link looks inevitable rather than chosen.","whyCN":"当链条足够紧，最后一环看起来就不是选择，而是必然。"},{"no":"06","title":"Clear-headed as a person","titleCN":"思路清晰的","definition":"describing a mind that proceeds in order and does not jump","definitionCN":"形容心思按顺序推进、不跳跃","example":"She is a logical thinker even under pressure.","exampleCN":"即使在压力下，她也是思路清晰的思考者。","why":"The same quality that belongs to arguments is transferred to the people who make them.","whyCN":"属于论证的性质被转移到制造论证的人身上。"},{"no":"07","title":"Of boolean operations in computing","titleCN":"逻辑运算的","definition":"in computing, describing operations on true and false values","definitionCN":"在计算机领域，形容对真值与假值进行的运算","example":"A logical error is often a single reversed condition.","exampleCN":"逻辑运算上的错误常常只是一个条件写反了。","why":"Machines were built on the formal rules of inference, so the discipline's adjective became a technical label.","whyCN":"机器建立在形式推理规则之上，于是这门学科的形容词成了技术标签。"},{"no":"08","title":"Ordered and methodical","titleCN":"有条理的","definition":"laid out in an order where each part has a place","definitionCN":"按某种次序排列，使每一部分各就其位","example":"Arrange the files in a logical order before the audit.","exampleCN":"审计之前把文件按条理排好。","why":"Order is the visible trace of reasoning, even when no conclusion is being drawn.","whyCN":"即使没有在得出结论，条理也是推理留下的可见痕迹。"}],"etymology":{"intro":{"en":"Logical comes from a Greek word for 'of speech or reason', which reached English through Latin and French. Its root treats speaking and reasoning as one act.","cn":"logical 来自希腊语中意为「属于言辞或理性的」的词，经拉丁语与法语进入英语。它的词根把说话与推理当作同一件事。"},"items":[{"era":"GREEK LOGOS","en":"Logos meant 'word, speech, account, reason'. The same noun served for a sentence, a story, a ratio and the order of the world.","cn":"logos 意为「词、言语、说明、理性」。同一个名词既可指一句话、一个故事、一个比值，也可指世界的秩序。"},{"era":"GREEK LEGEIN","en":"The verb behind the noun meant 'to say, to pick out, to gather'. Speech and selection share one root because speaking was seen as selecting words.","cn":"名词背后的动词意为「说、挑出、收集」。说话与选择共享一个词根，因为说话被视为在挑选词语。"},{"era":"GREEK LOGIKOS","en":"The adjective meant 'skilled in speech or reasoning', and it named the art of argument rather than a branch of study.","cn":"这个形容词意为「擅长言辞或推理的」，它指论证的艺术，而不是一门学科。"},{"era":"LATIN AND OLD FRENCH","en":"Latin borrowed the adjective and the noun; Old French passed them to English, where the noun first named the art of arguing well.","cn":"拉丁语借入该形容词与名词；古法语把它们传给英语，名词最初指善于论证的艺术。"},{"era":"MEDIEVAL UNIVERSITIES","en":"As a taught subject, the noun settled into its modern sense, and the adjective came to describe whatever obeyed its rules.","cn":"作为被教授的科目，名词固定为现代意义，形容词则用来描写任何服从其规则的东西。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of the Greek verb is not established, and the reconstructed Indo-European root proposed for it is a hypothesis.","cn":"来源不确定：这个希腊动词的更早来源没有定论，为它提出的印欧词根属重构，只是假说。"}]},"similar":{"note":{"en":"The first group holds words from the same speech-and-reason root that are easy to confuse; the second holds near neighbours for being sensible or orderly.","cn":"第一组是同出「言辞与理性」词根、容易混淆的词；第二组是表示「明理」或「有条理」的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"logic","ipa":"/ˈlɒdʒɪk/","tag":"the noun","definition":"The discipline or the system of rules; the adjective describes what follows those rules.","definitionCN":"指学科或规则体系；形容词则描写服从这些规则的东西。"},{"word":"logistics","ipa":"/ləˈdʒɪstɪks/","tag":"same root, other branch","definition":"From a Greek word for reckoning: it names the practical business of moving and supplying, not reasoning.","definitionCN":"来自希腊语中指「计算」的词：指运输与补给的实际事务，而非推理。"},{"word":"logician","ipa":"/ləˈdʒɪʃn/","tag":"the person","definition":"One who studies the discipline, not something that conforms to it.","definitionCN":"研究这门学科的人，而不是服从它的某物。"},{"word":"analogy","ipa":"/əˈnælədʒi/","tag":"same root, different prefix","definition":"Built on the same noun with a prefix meaning 'according to': it names a comparison, not a rule of inference.","definitionCN":"同一名词加意为「按照」的前缀：指比较，而非推理规则。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reasonable","ipa":"/ˈriːzənəbl/","tag":"fair as well as sound","definition":"It adds a judgment about fairness or moderation, which logical does not contain.","definitionCN":"多了对公平或适度的判断，而 logical 不含这一层。"},{"word":"consistent","ipa":"/kənˈsɪstənt/","tag":"no contradiction","definition":"It claims only that the parts do not clash, leaving open whether the whole is valid.","definitionCN":"只声称各部分不冲突，至于整体是否有效则不论。"},{"word":"systematic","ipa":"/sɪˈstæmətɪk/","tag":"method first","definition":"It praises a method followed throughout, even where the method itself is not logical.","definitionCN":"称赞贯穿始终的方法，即使方法本身并不合乎逻辑。"},{"word":"sound","ipa":"/saʊnd/","tag":"valid and true","definition":"In logic it means both correctly structured and built on true premises, a stronger claim than logical.","definitionCN":"在逻辑中兼指结构正确与前提为真，比 logical 的主张更强。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Greek root means both 'word' and 'reason', so logical is about words that hold together by reason.","cn":"希腊词根同时意为「言辞」与「理性」，所以 logical 说的是靠理性站得住的话。"},{"en":"The family runs logic, logical, logically, logician, logicalness.","cn":"同族词包括 logic、logical、logically、logician、logicalness。"},{"en":"Fixed phrases mark the chain: a logical step, a logical conclusion, a logical order.","cn":"固定搭配标出链条：合乎逻辑的一步、合乎逻辑的结论、逻辑顺序。"},{"en":"The same root appears in words for dialogue, analogy and catalogue, all built on speech or gathering.","cn":"同一个词根还出现在表示对话、类比与目录的词里，都由「说话」或「收集」构成。"},{"en":"Computing uses the word for operations on true and false, because machines run on these rules.","cn":"计算机领域用这个词指对真假的运算，因为机器就运行在这些规则上。"}],"abstract":[{"en":"Picture a row of dominoes standing close enough that the first one settles the last.","cn":"想象一排立着的多米诺，近得第一张就能决定最后一张。"},{"en":"Picture a staircase with no missing step and no extra one.","cn":"想象一段楼梯，既没有缺一阶，也没有多一阶。"},{"en":"Picture two maps of the same city that agree on every street.","cn":"想象同一座城市的两张地图，每条街都对得上。"}]},"examples":[{"en":"The logical conclusion of the policy is higher taxes.","cn":"这项政策合乎逻辑的结论是更高的税。"},{"en":"Her explanation was logical, but it began from a wrong assumption.","cn":"她的解释合乎逻辑，但出发点是错的假设。"},{"en":"Put the chapters in a logical order before you submit.","cn":"交稿前把各章按逻辑顺序排好。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"log（言辞、理性）+ ical（属于……的）＝ 属于理性规则的 → 合乎逻辑的、合理的。","word":"logical"},"root":"希腊 logikos「擅长言辞或推理的」，来自 logos「词、言语、说明、理性」，其背后的动词 legein 意为「说、挑出、收集」；更深来源不确定。经拉丁与古法语进入英语。同族有 logic、logician、dialogue、analogy。","sensesIntro":{"en":"Eight senses follow one chain of steps. It can be a formal derivation, a sensible choice, a branch of study, a self-consistent whole, the step that seems forced, the mind that keeps order, a machine's operation on true and false, or simply an arrangement with a place for everything.","cn":"八个义项沿一条步骤链展开。它可以是形式推导、明智的选择、一门学科、自洽的整体、显得非如此不可的一步、保持次序的心智、机器对真假的运算，或仅仅是各得其所的排列。"},"semanticMap":{"core":{"en":"CORE IMAGE: a chain in which every link is fastened to the one before.","cn":"核心意象：一条每一环都扣在前一环上的链。"},"chain":["WORD AND REASON","STEP FROM STEP","PARTS THAT DO NOT CLASH","THE SENSIBLE CHOICE","WHAT MUST FOLLOW","A MIND THAT KEEPS ORDER"],"branches":[{"senses":"01 · 03","en":"RULE AND DISCIPLINE: the valid step, then the subject that studies such steps.","cn":"规则与学科：有效的一步，以及研究这类步骤的科目。"},{"senses":"02","en":"OUTSIDE THE PROOF: the same approval given to ordinary good judgment.","cn":"走出证明之外：同样的认可被给了日常的明智判断。"},{"senses":"04 · 08","en":"COHERENCE AND LAYOUT: parts that do not cancel each other, shown as a visible order.","cn":"自洽与排布：彼此不取消的部分，显现为可见的次序。"},{"senses":"05","en":"THE LAST LINK: the step that looks forced rather than chosen.","cn":"最后一环：看起来不是被选择、而是被逼出的那一步。"},{"senses":"06 · 07","en":"KEEPER AND MACHINE: the person whose thinking keeps order, and the circuit that runs on the same rules.","cn":"守序者与机器：思维保持次序的人，以及运行在同样规则上的电路。"}]},"affixes":{"intro":{"en":"Logical is a Greek-derived adjective carrying a Latin adjective ending, and the root behind it builds a large family in English.","cn":"logical 是一个源自希腊语的形容词，带着拉丁形容词词尾，它背后的词根在英语中构成一大批词。"},"latinIntro":{"en":"Greek supplied the noun for word and reason; Latin and French supplied the endings that turned it into the English adjective and its relatives.","cn":"希腊语提供了指「言辞与理性」的名词；拉丁语与法语提供了把它变成英语形容词及其亲属的词尾。"},"items":[{"word":"logos","structure":"logos (Greek noun, 'word, speech, reason')","meaning":"word; reason","meaningCN":"言辞；理性","example":"One noun covers a sentence and the order of the world.","exampleCN":"一个名词同时涵盖一句话与世界的秩序。"},{"word":"legein","structure":"legein (Greek verb, 'to say, gather, pick out')","meaning":"to say; to gather","meaningCN":"说；收集","example":"Speaking is pictured as picking words out.","exampleCN":"说话被描绘为把词挑出来。"},{"word":"-ikos","structure":"-ikos (Greek adjective ending, 'skilled in, belonging to')","meaning":"skilled in; of","meaningCN":"擅长……的；属于……的","example":"The ending makes an adjective of skill.","exampleCN":"这个词尾造出表示「擅长」的形容词。"},{"word":"logic","structure":"logos + -ike (the art or study)","meaning":"the art of valid argument","meaningCN":"有效论证的艺术","example":"Logic supplies the rules that reasoning follows.","exampleCN":"逻辑提供推理所遵循的规则。"},{"word":"logical","structure":"logic + -al (Latin adjective ending)","meaning":"following the rules of logic","meaningCN":"合乎逻辑规则的","example":"The argument was logical at every step.","exampleCN":"这个论证每一步都合乎逻辑。"},{"word":"logically","structure":"logical + -ly (adverb)","meaning":"by valid inference","meaningCN":"按有效推理地","example":"The two claims cannot both be true logically.","exampleCN":"这两个主张在逻辑上不可能同时为真。"},{"word":"logician","structure":"logic + -ian (one who practises)","meaning":"a student of logic","meaningCN":"逻辑学家","example":"A logician tests the form, not the content.","exampleCN":"逻辑学家检验形式，而非内容。"},{"word":"dialogue","structure":"dia- + logos","meaning":"conversation between people","meaningCN":"对话","example":"The prefix means 'across', so speech passes between two.","exampleCN":"前缀意为「穿过」，言语在两人之间往返。"},{"word":"analogy","structure":"ana- + logos","meaning":"a comparison of relations","meaningCN":"类比","example":"The prefix means 'according to', giving a matching of ratios.","exampleCN":"前缀意为「按照」，给出比值的对应。"},{"word":"-logy","structure":"-logia (Greek ending, 'the study of')","meaning":"a field of study","meaningCN":"某门学问","example":"The ending names disciplines built on ordered speech.","exampleCN":"这个词尾命名建立在有序言说之上的学科。"}],"latinEntries":[{"word":"logicus","structure":"logicus, logica, logicum (adj., from Greek)","meaning":"of logic, logical","meaningCN":"逻辑的；合乎逻辑的"},{"word":"logica","structure":"logica, logicae (f., from Greek)","meaning":"the art of reasoning","meaningCN":"推理的艺术"},{"word":"logice","structure":"logice (adv., from Greek)","meaning":"logically","meaningCN":"合乎逻辑地"}],"derivatives":[{"word":"logic","pos":"n.","zh":"逻辑；逻辑学（希腊词根「言辞、理性」，由「说话」转为「推理规则」）"},{"word":"logically","pos":"adv.","zh":"逻辑上；必然地（形容词加副词后缀）"},{"word":"logician","pos":"n.","zh":"逻辑学家（名词词干加表从业者的后缀）"},{"word":"logicalness","pos":"n.","zh":"合乎逻辑的性质（形容词加名词后缀）"}]}},{"word":"induction","ipa_uk":"/ɪnˈdʌkʃn/","ipa_us":"/ɪnˈdʌkʃən/","definition_zh":"归纳；归纳法；就职（入伍）典礼；感应；诱导","definition_en":"reasoning from particular cases to a general rule, or the act of bringing someone or something into a role, a body or a state","core_image":"桌上排着一列深浅不同的样本，研究员从最浅的一支开始记录，最后在纸页顶端写下一条通则","scene":"实验室的桌上摆着一排颜色深浅不一的溶液，研究员从最浅的开始逐一记录，再把共同点写到本子上。Induction begins with many small observations and ends with one general rule.","sceneCN":"这里 induction 指「从许多个别事例推出通则」（第 1 个义项：归纳推理）；句意为归纳从许多细小的观察开始，最后得到一个通则。","pos":[{"tag":"n.","zh":"归纳；归纳法；就职典礼；入伍；感应；诱导（多数义项不可数）"}],"collocations":[{"phrase":"induction from examples","zh":"由例证归纳"},{"phrase":"induction ceremony","zh":"就职典礼"},{"phrase":"electromagnetic induction","zh":"电磁感应"},{"phrase":"induction into a role","zh":"让某人进入某个职位"},{"phrase":"induction of labour","zh":"引产；催产"},{"phrase":"the problem of induction","zh":"归纳问题（哲学难题）"}],"forms":[{"label":"复数","form":"inductions"},{"label":"动词","form":"induce"},{"label":"动词（使正式进入）","form":"induct"},{"label":"形容词","form":"inductive"},{"label":"副词","form":"inductively"},{"label":"形容词（被引入的）","form":"induced"}],"derivatives":[{"word":"induce","pos":"v.","zh":"引起；诱导；劝说（拉丁动词「引入」进入英语，由「领进来」转为「使发生」）"},{"word":"induct","pos":"v.","zh":"使正式就职；征召入伍（同一拉丁分词的另一条进入路径）"},{"word":"inductive","pos":"adj.","zh":"归纳的；感应的（名词词干加形容词后缀）"},{"word":"inductively","pos":"adv.","zh":"以归纳方式（形容词加副词后缀）"}],"senses":[{"no":"01","title":"Reasoning from particular cases","titleCN":"从个别事例推出通则","definition":"the move from a number of observed instances to a general statement about all such cases","definitionCN":"从若干被观察的实例走向关于所有同类情形的概括陈述","example":"Induction begins with many small observations and ends with one general rule.","exampleCN":"归纳从许多细小的观察开始，最后得到一个通则。","why":"The Latin verb means 'to lead in', so the mind is led from scattered cases into one rule.","whyCN":"拉丁动词意为「领进来」，心智被从零散事例领进一条规则。"},{"no":"02","title":"The method itself","titleCN":"归纳法","definition":"the systematic procedure of collecting cases and generalizing from them","definitionCN":"收集事例并从中概括的系统程序","example":"Bacon urged induction as a corrective to inherited opinion.","exampleCN":"培根主张以归纳法纠正沿袭的成见。","why":"A single move becomes a repeatable procedure with rules of its own.","whyCN":"单次动作变成了有自身规则、可重复的程序。"},{"no":"03","title":"A ceremony of taking office","titleCN":"就职典礼","definition":"the formal occasion on which a person is installed in a position","definitionCN":"正式使某人进入某个职位的场合","example":"The new rector's induction filled the hall.","exampleCN":"新校长的就职典礼坐满了礼堂。","why":"The old sense of leading someone in survives socially: a person is led into a chair.","whyCN":"「把某人领进来」的古义在社会场合留存：一个人被领进一个位子。"},{"no":"04","title":"Admission into an organization","titleCN":"入伍、入门","definition":"the process of bringing a recruit or member formally into a group","definitionCN":"正式把新成员引入某个群体的过程","example":"Induction into the unit took two weeks of training.","exampleCN":"加入该部队的入门训练花了两周。","why":"Institutions literalize the image: a body is brought inside a gate and a set of rules.","whyCN":"机构把这个意象字面化：一个人被带进一道门与一套规则之内。"},{"no":"05","title":"Electromagnetic induction","titleCN":"电磁感应","definition":"the production of a current in a conductor by a changing magnetic field","definitionCN":"变化的磁场在导体中产生电流","example":"Faraday's induction made the electric motor possible.","exampleCN":"法拉第的电磁感应使电动机成为可能。","why":"Nothing is physically led in; a state is induced in a nearby body without contact.","whyCN":"并没有东西被实际领入；一种状态在不接触的情况下被引发于邻近物体。"},{"no":"06","title":"Induction of anaesthesia","titleCN":"麻醉诱导","definition":"the process of bringing a patient into anaesthesia","definitionCN":"使病人进入麻醉状态的过程","example":"Induction takes about two minutes in adults.","exampleCN":"成人的麻醉诱导约需两分钟。","why":"Medicine keeps the metaphor of leading a person into a state.","whyCN":"医学保留了「把一个人领进某种状态」的比喻。"},{"no":"07","title":"Biological induction","titleCN":"生物诱导、基因诱导","definition":"the triggering of gene activity or tissue development by a signal","definitionCN":"由信号触发基因活动或组织发育","example":"Induction of the gene followed the hormone signal.","exampleCN":"该基因的诱导随激素信号而来。","why":"A signal from outside switches on a programme inside, which is the same leading-in at cellular scale.","whyCN":"外部信号开启内部程序，这是细胞尺度上的同一种「引入」。"},{"no":"08","title":"The conclusion reached","titleCN":"归纳所得的结论","definition":"the general statement produced by the procedure, viewed as its output","definitionCN":"由该程序产生、被当作其产物的一般陈述","example":"The induction held until a single counter-example appeared.","exampleCN":"这个归纳结论一直成立，直到出现一个反例。","why":"The movement of thought leaves a product behind, and the word can name that product too.","whyCN":"思维的运动留下产物，这个词也能指那个产物。"}],"etymology":{"intro":{"en":"Induction comes from a Latin noun of action built on a verb meaning 'to lead in'. The logical sense grew out of the physical one.","cn":"induction 来自拉丁语的表动作名词，它建立在一个意为「领进来」的动词上。逻辑义是从物理义生长出来的。"},"items":[{"era":"LATIN DUCERE","en":"Ducere meant 'to lead, draw, conduct'. It is one of the most productive verbs in the Latin vocabulary and supplies a large English family.","cn":"ducere 意为「引领、拉、导」。它是拉丁语中构词能力最强的动词之一，提供了大批英语词。"},{"era":"LATIN INDUCERE","en":"The compound meant 'to lead or bring in', and also 'to introduce, to persuade'. The two shades have stayed together ever since.","cn":"这个复合词意为「引入、带进」，也指「介绍、劝说」。这两层意思此后一直并存。"},{"era":"LATIN INDUCTIO","en":"The noun of action covered both a physical bringing in and, in later Latin, an argument that leads the mind to a conclusion.","cn":"这个表动作名词既涵盖物理上的引入，也在后来的拉丁语中指把心智引向结论的论证。"},{"era":"MEDIEVAL AND EARLY MODERN ENGLISH","en":"English took the noun in the fifteenth century; by the sixteenth it named the ceremony of installing a person in office.","cn":"英语在 15 世纪接受了这个名词；到 16 世纪它指使某人就职的典礼。"},{"era":"BACON AND LOGIC","en":"The method of generalizing from observed cases was promoted as a corrective to inherited reasoning, and the word became its standard name.","cn":"从观察事例概括的方法被提倡为对沿袭推理的纠正，这个词成了它的标准名称。"},{"era":"PHYSICS AND MEDICINE","en":"Nineteenth-century physics used the word for a current produced without contact, and medicine used it for bringing a patient into anaesthesia.","cn":"19 世纪的物理学用这个词指不接触而产生的电流，医学用同词指使病人进入麻醉。"}]},"similar":{"note":{"en":"The first group holds words built on the same leading-in verb that are constantly confused; the second holds near neighbours in reasoning.","cn":"第一组是同出「引入」动词、常被混淆的词；第二组是推理领域里的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"induce","ipa":"/ɪnˈdjuːs/","tag":"the verb","definition":"Same Latin verb: to cause a state, to persuade, or to bring on labour; it is the everyday verb behind the noun.","definitionCN":"同一拉丁动词：指使某种状态发生、劝说，或引产；是这个名词背后的日常动词。"},{"word":"induct","ipa":"/ɪnˈdʌkt/","tag":"install by ceremony","definition":"Structurally the same verb but used for formal installation into a post, and for admission into military service.","definitionCN":"结构上同源，但专用于正式使就职，以及征召入伍。"},{"word":"deduction","ipa":"/dɪˈdʌkʃn/","tag":"the opposite road","definition":"From the same leading verb with a prefix meaning 'down or away': it moves from general rules to particular cases.","definitionCN":"同一「引领」动词加意为「向下、离开」的前缀：从通则走向个别情形。"},{"word":"inductance","ipa":"/ɪnˈdʌktəns/","tag":"a physical quantity","definition":"The property of a circuit that opposes a change of current; it shares the electrical sense but names a measurement, not a process.","definitionCN":"电路阻碍电流变化的性质；共享「电」这一义，但指一个量而非过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"generalization","ipa":"/ˌdʒenrəlaɪˈzeɪʃn/","tag":"the product","definition":"The broad statement produced by induction, stated as a result rather than as a method.","definitionCN":"由归纳产生的宽泛陈述，被表述为结果而非方法。"},{"word":"inference","ipa":"/ˈɪnfərəns/","tag":"the umbrella","definition":"Any move from evidence to conclusion, covering both the inductive and the deductive road.","definitionCN":"从证据到结论的任何推进，涵盖归纳与演绎两条路。"},{"word":"estimation","ipa":"/ˌestɪˈmeɪʃn/","tag":"numbers, not rules","definition":"It generalizes from samples to a quantity, where induction generalizes to a rule.","definitionCN":"从样本概括到一个数量，而归纳概括到一条规则。"},{"word":"swearing-in","ipa":"/ˈsweərɪŋ ɪn/","tag":"plain paraphrase","definition":"A transparent phrase for the ceremony sense, with no Latin root at all.","definitionCN":"就职典礼义的大白话说法，完全不带拉丁词根。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin verb means 'lead in', so induction leads the mind from cases into a rule.","cn":"拉丁动词意为「领进来」，所以归纳把心智从事例领进一条规则。"},{"en":"The family runs induce, induct, induction, inductive, inductively.","cn":"同族词包括 induce、induct、induction、inductive、inductively。"},{"en":"Fixed phrases mark the domains: induction from examples, induction ceremony, electromagnetic induction.","cn":"固定搭配标出领域：由例证归纳、就职典礼、电磁感应。"},{"en":"The same leading verb, with a few other prefixes, gives conduct, produce, reduce and deduce.","cn":"同一个「引领」动词配上别的前缀，就得到 conduct、produce、reduce、deduce。"},{"en":"Philosophy knows it as the problem of induction: no number of cases can guarantee the rule.","cn":"哲学把它称作归纳问题：再多事例也无法保证那条规则。"}],"abstract":[{"en":"Picture a hand drawing one line through a hundred scattered dots.","cn":"想象一只手在一百个散点上画出一条线。"},{"en":"Picture a door held open while someone is walked through it.","cn":"想象一扇门被扶着敞开，有人正被领过去。"},{"en":"Picture a magnet moving near a wire, and the wire answering without being touched.","cn":"想象一块磁铁在导线旁移动，导线没被碰却有了回应。"}]},"examples":[{"en":"Induction from a handful of cases is useful but never certain.","cn":"从少数事例归纳有用，但从不保证确定。"},{"en":"The induction of new staff includes a week of shadowing.","cn":"新员工的入职引导包括一周的跟岗。"},{"en":"The coil produces a current by induction when the field changes.","cn":"磁场变化时，线圈通过感应产生电流。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"in（向内）+ duct（引导）＝ 把心智从一个个事例领进一条通则 → 归纳；也指把人领进职位或某种状态。","word":"induction"},"root":"拉丁 inductio「引入」，来自 inducere「领进来、引入」，由 in-「向内」+ ducere「引领」构成。同族有 induce、induct、deduce、conduct、produce、reduce。","sensesIntro":{"en":"Eight senses follow one leading-in. The mind can be led from cases to a rule, the procedure can be made a method, a person can be led into an office or a unit, a state can be led into a body or a circuit, and the rule itself can be the thing left behind.","cn":"八个义项沿一次「领进来」展开。心智可以被从事例领进一条规则，程序可以被做成方法，一个人可以被领进职位或队伍，某种状态可以被引入身体或电路，而那条规则本身也可以是留下的东西。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand leading someone through a doorway into a place they were not in before.","cn":"核心意象：一只手领着某人穿过门口，进入他原本不在的地方。"},"chain":["LED INWARD","MANY CASES, ONE RULE","A METHOD WITH RULES","BROUGHT INTO A CHAIR","BROUGHT INTO A BODY","THE RULE LEFT BEHIND"],"branches":[{"senses":"01 · 08","en":"THE MOVE AND WHAT IT LEAVES: the leading-in of the mind, and the general statement that remains afterwards.","cn":"这次引领与它留下的东西：把心智领进去，以及之后留下的那句概括。"},{"senses":"02","en":"MADE INTO A PROCEDURE: one move repeated by rule becomes a method with a name.","cn":"变成程序：一次动作按规则重复，就成了有名称的方法。"},{"senses":"03 · 04","en":"PEOPLE LED THROUGH DOORS: into an office by ceremony, into a unit by training.","cn":"被领过门的人：以典礼领进职位，以训练领进队伍。"},{"senses":"05","en":"LED WITHOUT CONTACT: physics keeps only the effect, a state induced at a distance.","cn":"不接触的引领：物理学只保留效果，即在远处被引发的状态。"},{"senses":"06 · 07","en":"LED INTO A STATE: a patient into sleep, a cell into a switched-on programme.","cn":"被领进某种状态：病人进入麻醉，细胞进入被开启的程序。"}]},"affixes":{"intro":{"en":"Induction is a prefix plus a verb plus a noun ending, and each piece can be read separately.","cn":"induction 由前缀、动词与名词词尾构成，每一块都可以单独读出。"},"latinIntro":{"en":"The leading verb with different prefixes builds a whole set of English verbs, so the family is unusually easy to read.","cn":"这个「引领」动词配上不同前缀，造出一整组英语动词，因此这个词族读起来格外容易。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'into, toward')","meaning":"into","meaningCN":"向内；进入","example":"The prefix marks movement toward an inside.","exampleCN":"这个前缀标出朝内部去的运动。"},{"word":"ducere","structure":"ducere, duxi, ductum (Latin verb, third conjugation)","meaning":"to lead, draw","meaningCN":"引领；拉","example":"The root supplies the pulling hand.","exampleCN":"这个词根提供那只牵引的手。"},{"word":"inducere","structure":"in- + ducere","meaning":"to lead in, introduce","meaningCN":"引入；介绍","example":"The compound adds direction to the pulling.","exampleCN":"复合词在牵引之上加了方向。"},{"word":"-tion","structure":"-tio (Latin noun of action ending)","meaning":"the act or result of","meaningCN":"……的动作或结果","example":"The ending turns the verb into an event.","exampleCN":"这个词尾把动词变成一个事件。"},{"word":"induction","structure":"inducere + -tion","meaning":"a leading in","meaningCN":"引入；归纳","example":"Induction led the mind from cases to a rule.","exampleCN":"归纳把心智从事例引向规则。"},{"word":"induce","structure":"induce (English verb from the Latin form)","meaning":"to cause or persuade","meaningCN":"引起；劝说","example":"The drug induces sleep within minutes.","exampleCN":"这种药几分钟内引起睡意。"},{"word":"induct","structure":"induct (English verb from the Latin participle)","meaning":"to install formally","meaningCN":"正式使就职","example":"They inducted her into the academy.","exampleCN":"他们正式接纳她进入学会。"},{"word":"inductive","structure":"induct + -ive (adjective ending)","meaning":"of induction","meaningCN":"归纳的","example":"An inductive step moves from cases to a rule.","exampleCN":"归纳的一步从事例走向规则。"},{"word":"conduct","structure":"con- + ducere","meaning":"to lead together","meaningCN":"引导；指挥","example":"The same verb with another prefix leads a group.","exampleCN":"同一动词配另一个前缀，就是引领一群人。"},{"word":"deduce","structure":"de- + ducere","meaning":"to lead down from","meaningCN":"由……推出","example":"The prefix reverses the direction of travel.","exampleCN":"这个前缀把行进方向反过来。"}],"latinEntries":[{"word":"ducere","structure":"ducere, duxi, ductum (verb, third conjugation)","meaning":"to lead, draw, conduct","meaningCN":"引领；拉；导"},{"word":"inducere","structure":"inducere, induxi, inductum (verb, third conjugation)","meaning":"to lead in, introduce, persuade","meaningCN":"引入；介绍；劝说"},{"word":"inductio","structure":"inductio, inductionis (f., third declension)","meaning":"a bringing in, an introduction","meaningCN":"引入；引导"},{"word":"inductivus","structure":"inductivus, inductiva, inductivum (adj., late Latin)","meaning":"of induction","meaningCN":"归纳的"}],"derivatives":[{"word":"induce","pos":"v.","zh":"引起；诱导；劝说（拉丁动词「引入」进入英语，由「领进来」转为「使发生」）"},{"word":"induct","pos":"v.","zh":"使正式就职；征召入伍（同一拉丁分词的另一条进入路径）"},{"word":"inductive","pos":"adj.","zh":"归纳的；感应的（名词词干加形容词后缀）"},{"word":"inductively","pos":"adv.","zh":"以归纳方式（形容词加副词后缀）"}]}},{"word":"inductive","ipa_uk":"/ɪnˈdʌktɪv/","ipa_us":"/ɪnˈdʌktɪv/","definition_zh":"归纳的；由个别到一般的；感应的；诱导的","definition_en":"relating to reasoning that moves from particular cases to a general rule, or to effects produced without direct contact","core_image":"七个样本按颜色排成一列，一条细线从最左端拉到最右端，线的另一端写着一条通则","scene":"地质课上，学生把七块岩石样本按颗粒大小排成一列，然后写下一条适用于整层的判断。Her inductive method turned seven samples into a single working rule.","sceneCN":"这里 inductive 指「由个别样本推向一般规则的」（第 2 个义项：由个别到一般）；句意为她的归纳方法把七块样本变成了一条可用的规则。","pos":[{"tag":"adj.","zh":"归纳的；由个别到一般的；感应的；可被诱导的"}],"collocations":[{"phrase":"inductive reasoning","zh":"归纳推理"},{"phrase":"inductive method","zh":"归纳方法"},{"phrase":"inductive approach","zh":"归纳进路"},{"phrase":"inductive step","zh":"归纳的一步"},{"phrase":"inductive coupling","zh":"电感耦合"},{"phrase":"inductive bias","zh":"归纳偏置（机器学习术语）"}],"forms":[{"label":"比较级","form":"more inductive"},{"label":"最高级","form":"most inductive"},{"label":"副词","form":"inductively"},{"label":"名词（归纳）","form":"induction"},{"label":"名词（归纳性）","form":"inductiveness"},{"label":"动词","form":"induce"}],"derivatives":[{"word":"induction","pos":"n.","zh":"归纳；感应（形容词背后的名词，指该过程或该现象）"},{"word":"inductively","pos":"adv.","zh":"以归纳方式（形容词加副词后缀）"},{"word":"inductiveness","pos":"n.","zh":"归纳的性质（形容词加名词后缀）"},{"word":"inductor","pos":"n.","zh":"电感器（拉丁动词加表器具的后缀，指利用感应的元件）"}],"senses":[{"no":"01","title":"Of inductive reasoning","titleCN":"归纳推理的","definition":"belonging to the kind of inference that generalizes from observed cases","definitionCN":"属于从被观察事例进行概括的那类推理","example":"Inductive reasoning cannot prove a rule, only support it.","exampleCN":"归纳推理无法证明一条规则，只能支持它。","why":"The adjective simply labels the process named by the noun behind it.","whyCN":"这个形容词只是给它背后那个名词所指的过程贴上标签。"},{"no":"02","title":"Proceeding from particulars to a general","titleCN":"由个别到一般的","definition":"describing a method that starts with individual facts and ends with a wider statement","definitionCN":"形容从个别事实开始、以较宽陈述结束的方法","example":"Her inductive method turned seven samples into a single working rule.","exampleCN":"她的归纳方法把七块样本变成了一条可用的规则。","why":"Direction is the whole point: the same facts read upward give a rule, read downward give instances.","whyCN":"方向就是全部要点：同样的事实往上读得到规则，往下读得到实例。"},{"no":"03","title":"Of electrical induction","titleCN":"感应的","definition":"describing effects produced in a conductor by a changing magnetic field","definitionCN":"形容由变化磁场在导体中产生的效应","example":"Inductive coupling charges the smaller coil without a wire.","exampleCN":"电感耦合不用导线就给较小的线圈充电。","why":"Here nothing is led in physically; a state appears in a nearby body, which is the old image at a distance.","whyCN":"这里没有东西被实际引入；一种状态出现在邻近物体上，这是那个古老意象的远距离版本。"},{"no":"04","title":"Of an inductor","titleCN":"电感元件的","definition":"in electronics, describing a component that stores energy in a magnetic field","definitionCN":"在电子学中，形容以磁场储存能量的元件","example":"The inductive load made the switch arc.","exampleCN":"电感负载使开关产生了电弧。","why":"A component is named for the effect it exploits, so the adjective attaches to hardware.","whyCN":"元件因它所利用的效应而得名，于是这个形容词附着到硬件上。"},{"no":"05","title":"Capable of being induced","titleCN":"可被诱导的","definition":"able to be brought about or brought on by an outside agent","definitionCN":"能够被外部因素引起或触发的","example":"Some genes are inductive only under stress.","exampleCN":"有些基因只在应激时才可被诱导。","why":"The passive possibility is expressed by the same ending that marks other capacities.","whyCN":"被动的可能性由标记其他「能力」的同一词尾表达。"},{"no":"06","title":"Introductory or leading on","titleCN":"引导性的、开场的","definition":"in older usage, describing remarks that lead the hearer into a subject","definitionCN":"在较旧的用法中，形容把听者引入某个话题的开场话","example":"His inductive remarks prepared the audience for the argument.","exampleCN":"他那段开场话为听众进入论证做了铺垫。","why":"The literal sense of leading someone in survives in this mild rhetorical use.","whyCN":"「把某人领进来」的字面义在这种温和的修辞用法中留存。"},{"no":"07","title":"Empirical, based on observation","titleCN":"经验性的、基于观察的","definition":"resting on what has been observed rather than on principles fixed in advance","definitionCN":"依据已被观察到的内容，而非事先固定的原则","example":"The study took an inductive route, gathering cases before framing a theory.","exampleCN":"这项研究走归纳路线，先收集案例，再提出理论。","why":"When no framework is given, the only way forward is to look first and generalize later.","whyCN":"在没有现成框架时，唯一的前进方式就是先看、后概括。"},{"no":"08","title":"A built-in assumption in learning systems","titleCN":"归纳偏置的","definition":"in machine learning, describing the assumptions a model makes in order to generalize from limited data","definitionCN":"在机器学习中，形容模型为了从有限数据泛化而作出的假设","example":"Every model carries an inductive bias of some kind.","exampleCN":"每个模型都带着某种归纳偏置。","why":"A machine that generalizes must be tilted toward some patterns, and the older word supplies the label.","whyCN":"要泛化的机器必须偏向某些模式，这个古老的词为此提供了标签。"}],"etymology":{"intro":{"en":"Inductive is the adjective built on induction, with a Latin ending meaning 'having the nature of'. Its history is the history of the noun.","cn":"inductive 是建立在 induction 之上的形容词，带一个意为「具有……性质」的拉丁词尾。它的历史就是那个名词的历史。"},"items":[{"era":"LATIN DUCERE","en":"The verb meant 'to lead'; the whole family is about direction of movement, literal or mental.","cn":"这个动词意为「引领」；整个词族都关乎运动的方向，无论是实际还是心智上的。"},{"era":"LATIN INDUCERE","en":"The compound meant 'to lead in', and its participle supplied the stem that English adjectives use.","cn":"这个复合词意为「引入」，它的分词提供了英语形容词所用的词干。"},{"era":"LATE LATIN INDUCTIVUS","en":"Late Latin formed an adjective on the participle, meaning 'of a bringing in'; it passed into the modern languages as a label for a kind of argument.","cn":"晚期拉丁语在这个分词上造出形容词，意为「属于引入的」；它作为某类论证的标签传入近代语言。"},{"era":"EARLY MODERN ENGLISH","en":"English adopted the adjective in the sixteenth century, at first for rhetorical and then for logical use.","cn":"英语在 16 世纪接受了这个形容词，先用于修辞，后用于逻辑。"},{"era":"NINETEENTH CENTURY","en":"Physics gave the word its electrical sense, and engineering extended it to components that exploit the effect.","cn":"物理学给了它「电」这一义，工程学又把它扩展到利用该效应的元件上。"},{"era":"TWENTIETH CENTURIES AND SOURCE UNCERTAIN","en":"Learning theory and machine learning reused the word for the assumptions that allow generalization from limited data. Source uncertain: the deeper origin of the leading verb is not settled.","cn":"学习理论与机器学习再次使用这个词，指使有限数据得以泛化的那些假设。来源不确定：那个「引领」动词的更早来源没有定论。"}]},"similar":{"note":{"en":"The first group holds words that differ from inductive by a prefix or an ending; the second holds near neighbours in method.","cn":"第一组是与 inductive 只差一个前缀或词尾的词；第二组是方法上的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"deductive","ipa":"/dɪˈdʌktɪv/","tag":"the reverse direction","definition":"The same adjective pattern with a prefix meaning 'down from': it starts from general rules and works toward cases.","definitionCN":"同样的形容词模式，前缀却意为「由……而下」：从通则出发走向个别情形。"},{"word":"induction","ipa":"/ɪnˈdʌkʃn/","tag":"the noun","definition":"The process or event itself; the adjective is used to modify a method, a step or a reasoning type.","definitionCN":"指过程或事件本身；形容词用来修饰方法、步骤或推理类型。"},{"word":"induced","ipa":"/ɪnˈdjuːst/","tag":"caused from outside","definition":"The past participle: it says that something was brought about, not that a method generalizes.","definitionCN":"过去分词：说的是某事被引起，而不是某种方法在做概括。"},{"word":"inductor","ipa":"/ɪnˈdʌktə/","tag":"the object","definition":"A device, not a method; the ending marks a thing rather than a property.","definitionCN":"指器件而非方法；词尾标记的是物，而不是性质。"}]},{"heading":"NEAR MEANING","entries":[{"word":"empirical","ipa":"/ɪmˈpɪrɪkl/","tag":"from observation","definition":"It stresses reliance on observed data, which inductive methods usually need but do not define.","definitionCN":"强调依赖观察数据；归纳方法通常需要它，但并不等于它。"},{"word":"a posteriori","ipa":"/ˌeɪ pɒsteriˈɔːri/","tag":"known after experience","definition":"A philosophical label for knowledge that comes after experience, wider than any one method.","definitionCN":"哲学术语，指经验之后获得的知识，比任何一种方法都宽。"},{"word":"experimental","ipa":"/ˌeksperɪˈmentl/","tag":"arranged for testing","definition":"It describes work set up to produce observations, whereas inductive describes how conclusions are drawn from them.","definitionCN":"形容为产生观察而安排的工作，而 inductive 形容如何从中得出结论。"},{"word":"statistical","ipa":"/stəˈtɪstɪkl/","tag":"one toolkit","definition":"It names a mathematical apparatus for generalizing from samples, one modern form of inductive work.","definitionCN":"指从样本概括的一套数学工具，是归纳工作的现代形态之一。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The prefix means 'in' and the verb means 'lead': inductive work leads the mind inward from cases to a rule.","cn":"前缀意为「向内」，动词意为「引领」：归纳工作把心智从事例领向一条规则。"},{"en":"The family runs induce, induction, inductive, inductively, inductiveness, inductor.","cn":"同族词包括 induce、induction、inductive、inductively、inductiveness、inductor。"},{"en":"Fixed phrases mark the uses: inductive reasoning, inductive method, inductive coupling.","cn":"固定搭配标出用法：归纳推理、归纳方法、电感耦合。"},{"en":"The opposite adjective is deductive, which travels the other way with the other prefix.","cn":"反义的形容词是 deductive，用另一个前缀走相反方向。"},{"en":"Machine learning speaks of an inductive bias, the tilt that lets a model generalize.","cn":"机器学习讲「归纳偏置」，即让模型得以泛化的那种偏向。"}],"abstract":[{"en":"Picture a rope pulled from many small pegs into one knot.","cn":"想象一根绳从许多小木桩上收拢成一个结。"},{"en":"Picture a ladder whose rungs are separate facts.","cn":"想象一架梯子，每一级横档都是一个单独的事实。"},{"en":"Picture a magnet that makes a nearby needle turn before it is touched.","cn":"想象一块磁铁让旁边的针在被碰之前就转了方向。"}]},"examples":[{"en":"Inductive reasoning is powerful in discovery and weak in proof.","cn":"归纳推理在发现上很有力，在证明上很弱。"},{"en":"The team took an inductive approach, coding interviews before forming categories.","cn":"团队采取归纳进路，先编码访谈，再形成类别。"},{"en":"Inductive charging heats the phone less than a cable does.","cn":"感应充电比线缆充电让手机发热更少。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"in（向内）+ duct（引领）+ ive（具有……性质的）＝ 把心智从个别事例领向通则的 → 归纳的。","word":"inductive"},"root":"拉丁 inductivus「属于引入的」，来自 inducere「领进来」，由 in-「向内」+ ducere「引领」构成；更早来源不确定。同族有 induction、induce、deductive、inductor。","sensesIntro":{"en":"Eight senses follow one adjective's reach. It can label a kind of inference, a direction of method, an electrical effect, a component, a capacity to be brought about, an introductory remark, an empirical stance, or an assumption built into a model.","cn":"八个义项沿一个形容词的覆盖范围展开。它可以标记一类推理、一种方法的方向、一种电效应、一个元件、一种可被引起的性质、一段开场话、一种经验立场，或一个被装进模型里的假设。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line drawn from many separate dots up to a single knot.","cn":"核心意象：一条线从许多分散的点拉向一个结。"},"chain":["LEADING FROM CASES","PARTICULARS FIRST","THE RULE AT THE END","THE OPPOSITE ROAD","FORCE ACROSS A GAP","A TILT BUILT INTO THE MODEL"],"branches":[{"senses":"01 · 02","en":"THE LABEL AND THE DIRECTION: what kind of inference it is, and which way it travels.","cn":"标签与方向：它是哪一类推理，以及它朝哪边行进。"},{"senses":"07","en":"LOOK FIRST: when no framework exists, observation must come before the rule.","cn":"先看：没有框架时，观察必须走在规则之前。"},{"senses":"03 · 04","en":"ACROSS A GAP: the effect arrives without contact, and then the hardware is named for it.","cn":"越过空隙：效应不接触就到达，随后硬件因它得名。"},{"senses":"05 · 06","en":"BROUGHT ABOUT, OR LED IN: what can be caused, and the older habit of leading a listener in.","cn":"被引起，或被领入：可被引起的东西，以及把听者领进来的旧习惯。"},{"senses":"08","en":"THE MACHINE'S OWN TILT: generalization needs an assumption chosen in advance.","cn":"机器自身的偏向：泛化需要一个事先选定的假设。"}]},"affixes":{"intro":{"en":"Inductive is a Latin participle stem plus an adjective ending, so it is built from three recognisable pieces.","cn":"inductive 是拉丁分词词干加形容词词尾，因此由三块可辨认的成分构成。"},"latinIntro":{"en":"The same leading verb underlies the noun and the verb, while the ending marks a property rather than an action.","cn":"同一个「引领」动词支撑着名词与动词，而词尾标记的是性质而非动作。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'into')","meaning":"into","meaningCN":"向内","example":"The prefix fixes the direction of the leading.","exampleCN":"这个前缀固定了牵引的方向。"},{"word":"ducere","structure":"ducere (Latin verb, 'to lead')","meaning":"to lead","meaningCN":"引领","example":"The root is the hand that pulls.","exampleCN":"这个词根就是那只拉的手。"},{"word":"-ive","structure":"-ivus (Latin adjective ending, 'having the nature of')","meaning":"having the nature of","meaningCN":"具有……性质的","example":"The ending turns an action into a quality.","exampleCN":"这个词尾把动作变成性质。"},{"word":"inductive","structure":"induct + -ive","meaning":"of leading in","meaningCN":"属于引入的","example":"An inductive step goes from cases to a rule.","exampleCN":"归纳的一步从事例走向规则。"},{"word":"induction","structure":"induct + -ion (noun of action)","meaning":"the act of leading in","meaningCN":"引入；归纳","example":"Induction is the process the adjective describes.","exampleCN":"归纳就是这个形容词所描述的过程。"},{"word":"inductively","structure":"inductive + -ly (adverb)","meaning":"by generalizing from cases","meaningCN":"以归纳方式","example":"The rule was reached inductively.","exampleCN":"这条规则是归纳得出的。"},{"word":"inductiveness","structure":"inductive + -ness (noun of quality)","meaning":"the quality of being inductive","meaningCN":"归纳的性质","example":"Researchers debated the inductiveness of the method.","exampleCN":"研究者争论这套方法有多强的归纳性。"},{"word":"inductor","structure":"induct + -or (thing that acts)","meaning":"a component using induction","meaningCN":"电感器","example":"The inductor stores energy in a magnetic field.","exampleCN":"电感器以磁场储存能量。"},{"word":"deductive","structure":"de- + duct + -ive","meaning":"of leading down from rules","meaningCN":"演绎的","example":"The two adjectives name opposite directions.","exampleCN":"这两个形容词命名相反的方向。"}],"latinEntries":[{"word":"inducere","structure":"inducere, induxi, inductum (verb, third conjugation)","meaning":"to lead in","meaningCN":"引入"},{"word":"inductivus","structure":"inductivus, inductiva, inductivum (adj., late Latin)","meaning":"of a bringing in","meaningCN":"属于引入的"},{"word":"inductio","structure":"inductio, inductionis (f., third declension)","meaning":"a bringing in","meaningCN":"引入；归纳"}],"derivatives":[{"word":"induction","pos":"n.","zh":"归纳；感应（形容词背后的名词，指该过程或该现象）"},{"word":"inductively","pos":"adv.","zh":"以归纳方式（形容词加副词后缀）"},{"word":"inductiveness","pos":"n.","zh":"归纳的性质（形容词加名词后缀）"},{"word":"inductor","pos":"n.","zh":"电感器（拉丁动词加表器具的后缀，指利用感应的元件）"}]}},{"word":"problem","ipa_uk":"/ˈprɒbləm/","ipa_us":"/ˈprɑːbləm/","definition_zh":"问题；难题；习题；麻烦；故障","definition_en":"a difficulty that needs a solution, a question set for an answer, or a source of trouble","core_image":"一张纸上写着题干，下面留着一大片空白，空白等着被填上","scene":"晚自习的教室里，一道几何题在纸上留了大片空白，学生把橡皮屑推来推去。She stared at the problem on the page for ten minutes before drawing her first line.","sceneCN":"这里 problem 指「等待被解答的题目」（第 2 个义项：需要回答的问题）；句意为她盯着纸上的这道题看了十分钟，才画下第一条线。","pos":[{"tag":"n.","zh":"问题；难题；习题；麻烦；故障（可数）"}],"collocations":[{"phrase":"solve a problem","zh":"解决问题"},{"phrase":"a serious problem","zh":"严重的问题"},{"phrase":"the problem of","zh":"……的难题"},{"phrase":"no problem","zh":"没问题（口语）"},{"phrase":"problem-solving","zh":"解决问题（的能力或过程）"},{"phrase":"a technical problem","zh":"技术故障"},{"phrase":"face a problem","zh":"面对一个问题"}],"forms":[{"label":"复数","form":"problems"},{"label":"形容词","form":"problematic"},{"label":"副词","form":"problematically"},{"label":"复合名词","form":"problem-solving"},{"label":"复合名词（另有）","form":"problem-solver"}],"derivatives":[{"word":"problematic","pos":"adj.","zh":"成问题的；棘手的（名词词干加形容词后缀，指「充满难题的」）"},{"word":"problematically","pos":"adv.","zh":"成问题地（形容词加副词后缀）"},{"word":"problem-solving","pos":"n.","zh":"解决问题（复合名词，指这一活动或能力）"},{"word":"problem-solver","pos":"n.","zh":"善于解决问题的人（复合名词，指从事该活动的人）"}],"senses":[{"no":"01","title":"A difficulty that needs a solution","titleCN":"需要解决的难题","definition":"a situation or condition that obstructs a goal and calls for action","definitionCN":"阻碍目标、需要采取行动的情境或状况","example":"The city has a serious problem with clean water.","exampleCN":"这座城市在清洁用水上有严重问题。","why":"The Greek word meant 'something put forward', so a problem is first of all an obstacle laid in front of you.","whyCN":"希腊词意为「被放到前面之物」，因此难题首先是被放到你面前的障碍。"},{"no":"02","title":"A question set for an answer","titleCN":"需要回答的题目","definition":"an exercise or question posed in order to be worked out","definitionCN":"为被解答而提出的练习或问题","example":"She stared at the problem on the page for ten minutes.","exampleCN":"她盯着纸上的这道题看了十分钟。","why":"Education turns the obstacle into a designed task, with a known answer behind it.","whyCN":"教育把障碍变成设计好的任务，背后有一个已知答案。"},{"no":"03","title":"A source of trouble","titleCN":"麻烦的根源","definition":"a person, habit or arrangement that keeps producing difficulties","definitionCN":"不断制造困难的人、习惯或安排","example":"The old pipe is the real problem, not the tap.","exampleCN":"真正的问题在于旧管道，而不是水龙头。","why":"Instead of one blocked goal, the word now names a continuing generator of blocks.","whyCN":"这个词不再指一个被挡住的目标，而指持续产生阻碍的源头。"},{"no":"04","title":"A troublesome person","titleCN":"难对付的人","definition":"in informal use, someone who is difficult to manage or who causes difficulties","definitionCN":"口语中，指难以管束或不断制造麻烦的人","example":"The new midfielder is a problem for every defence.","exampleCN":"这名新中场对每条防线都是个麻烦。","why":"The word transfers from situation to person when a person becomes the situation.","whyCN":"当一个人本身成了处境，这个词就从处境转到人。"},{"no":"05","title":"A social issue","titleCN":"社会问题、议题","definition":"a matter of public concern that policy is expected to address","definitionCN":"需要政策回应的公共关切事项","example":"Housing is a problem no single ministry can solve.","exampleCN":"住房是一个任何单一部门都解决不了的问题。","why":"Collective life produces difficulties that no individual can remove, so the word grows a public scale.","whyCN":"集体生活会产出个人无法消除的困难，这个词因此长出一个公共尺度。"},{"no":"06","title":"A technical fault","titleCN":"故障","definition":"a failure in a machine, system or connection","definitionCN":"机器、系统或连接上的失效","example":"A problem with the cooling fan shut the server down.","exampleCN":"冷却风扇的故障让服务器停机。","why":"Machines fail in specific places, and the general word for difficulty narrows to a located defect.","whyCN":"机器在具体位置失效，这个泛指的困难词于是收窄为位置明确的缺陷。"},{"no":"07","title":"A puzzle to be solved","titleCN":"棋题、作图题","definition":"a constructed challenge with a designed solution, as in chess or geometry","definitionCN":"有设计好解法的构造性挑战，如棋题或几何作图","example":"The composer published a problem that takes twelve moves.","exampleCN":"这位作曲家发表了一道需要十二步的棋题。","why":"Pure form: all irrelevant detail removed, leaving only the obstacle and its one key.","whyCN":"纯粹形式：无关细节全被去掉，只剩障碍与它唯一的钥匙。"},{"no":"08","title":"A task stated for solving","titleCN":"待解任务、问题陈述","definition":"in computing and modelling, a formal statement of inputs and required output","definitionCN":"在计算与建模中，对输入与所需输出的形式化陈述","example":"The problem was defined before any code was written.","exampleCN":"在写任何代码之前，问题先被定义清楚。","why":"Machines need the obstacle written as a specification, so the word becomes a technical object.","whyCN":"机器需要把障碍写成规格说明，这个词于是成为技术对象。"}],"etymology":{"intro":{"en":"Problem came through Latin from Greek, where the noun meant 'a thing put forward'. Nothing in the original word implies that it cannot be solved.","cn":"problem 经拉丁语来自希腊语，那里的名词意为「被放到前面之物」。原词中没有任何「无法解决」的暗示。"},"items":[{"era":"GREEK BALLEIN","en":"The verb meant 'to throw'. Its compounds describe things thrown forward, thrown across or thrown together, and the family is large.","cn":"这个动词意为「投掷」。它的复合词描写被向前投、被投过、被投到一起的东西，这个家族很大。"},{"era":"GREEK PROBLEMA","en":"The noun meant 'a thing put forward, a task, a riddle'. It covered a geometric construction as easily as a matter for debate.","cn":"这个名词意为「被提出之物、任务、谜题」。它既能指几何作图，也能指可供辩论的议题。"},{"era":"LATIN PROBLEMA","en":"Latin borrowed the Greek noun unchanged in sense; it was a learned borrowing rather than a native formation.","cn":"拉丁语原样借入这个希腊名词，意义不变；它是书面借词，而非本族构词。"},{"era":"OLD FRENCH AND MIDDLE ENGLISH","en":"The word reached English through French in the fourteenth century, first as a question proposed for discussion.","cn":"这个词在 14 世纪经法语进入英语，最初指提出来供讨论的问题。"},{"era":"MODERN GENERAL USE","en":"The sense broadened from a set question to any difficulty, and then to a fault in a machine or a person who causes trouble.","cn":"词义从「设定的题目」扩展到任何困难，再扩展到机器的故障或制造麻烦的人。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of the throwing verb is not established, and the reconstructed root proposed for it is a hypothesis.","cn":"来源不确定：这个「投掷」动词的更早来源没有定论，为它提出的重构词根属假说。"}]},"similar":{"note":{"en":"The first group holds words that differ from problem by a suffix or a prefix; the second holds near neighbours for difficulty and question.","cn":"第一组是与 problem 只差一个词尾或前缀的词；第二组是表示「困难」与「问题」的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"problematic","ipa":"/ˌprɒbləˈmætɪk/","tag":"the adjective","definition":"Built on the noun with an ending meaning 'full of': it describes something as difficult or doubtful, not as a task.","definitionCN":"由名词加意为「充满」的词尾构成：形容某事棘手或可疑，而不是指一项任务。"},{"word":"problems","ipa":"/ˈprɒbləmz/","tag":"the plural","definition":"The plural is routine, but fixed phrases such as 'no problem' keep the singular for a single reply.","definitionCN":"复数形式很平常，但「没问题」这类固定说法在单次回应中仍用单数。"},{"word":"problem-solving","ipa":"/ˈprɒbləm ˌsɒlvɪŋ/","tag":"a compound","definition":"A compound naming the activity, not the difficulty; it behaves as one noun with a fixed order.","definitionCN":"复合名词，指这项活动而非困难本身；语序固定，整体当作一个名词。"},{"word":"probable","ipa":"/ˈprɒbəbl/","tag":"false friend","definition":"From a Latin verb meaning 'to prove or approve', a different root: it means likely, not difficult.","definitionCN":"来自意为「证明、认可」的拉丁动词，词根不同：意为「很可能」，而非困难。"}]},{"heading":"NEAR MEANING","entries":[{"word":"question","ipa":"/ˈkwestʃən/","tag":"asks, not obstructs","definition":"It names something asked; it need not block anything, while a problem always stands in the way.","definitionCN":"指被问出的东西，未必阻碍什么；而 problem 总是挡在路上。"},{"word":"difficulty","ipa":"/dɪˈfɪkəlti/","tag":"the effort involved","definition":"It stresses how hard something is to do rather than the existence of a task.","definitionCN":"强调做起来的费力程度，而非有一项任务存在。"},{"word":"issue","ipa":"/ˈɪʃuː/","tag":"the matter under discussion","definition":"A neutral word for a matter being debated, with no claim that it must be solved.","definitionCN":"指正在被讨论的事项，中性，不主张必须解决。"},{"word":"trouble","ipa":"/ˈtrʌbl/","tag":"the disturbance","definition":"It names the disruption itself, often emotional, rather than the thing that needs working out.","definitionCN":"指扰乱本身，常带情绪，而不是需要被算清的那个东西。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Greek noun means 'a thing put forward', so a problem is an obstacle placed in front of you.","cn":"希腊名词意为「被放到前面之物」，所以 problem 就是被摆在你面前的障碍。"},{"en":"The family runs problem, problems, problematic, problem-solving, problem-solver.","cn":"同族词包括 problem、problems、problematic、problem-solving、problem-solver。"},{"en":"Fixed phrases cover the range: solve a problem, a technical problem, no problem.","cn":"固定搭配覆盖各义：解决问题、技术故障、没问题。"},{"en":"The same throwing verb appears in words for a symbol, a parabola and an emblem.","cn":"同一个「投掷」动词还出现在表示符号、抛物线与徽记的词里。"},{"en":"Mathematics keeps the oldest sense: a problem is a construction set for a known answer.","cn":"数学保留了最古老的意思：问题是为已知答案设计的作图任务。"}],"abstract":[{"en":"Picture a stone rolled into the middle of a road.","cn":"想象一块石头被滚到路中间。"},{"en":"Picture a blank square at the bottom of a page, waiting.","cn":"想象纸页下方一个空白的方格，正在等待。"},{"en":"Picture a knot in a rope that someone must untie, not cut.","cn":"想象绳上的一个结，必须解开，不能剪断。"}]},"examples":[{"en":"The problem is not money but time.","cn":"问题不在钱，而在时间。"},{"en":"She solved the second problem on the page in under a minute.","cn":"她不到一分钟就解出了那页上的第二道题。"},{"en":"Engineers traced the problem to a cracked seal.","cn":"工程师把故障追查到一处开裂的密封。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"pro（向前）+ blem（投出）＝ 被丢到你面前、挡在路上的东西 → 问题、难题。","word":"problem"},"root":"经拉丁 problema 来自希腊 problema「被提出之物、任务、谜题」，源自 proballein「向前投出」，由 pro-「向前」+ ballein「投掷」构成；更早来源不确定。同族有 emblem、parabola、symbol、ballistic。","sensesIntro":{"en":"Eight senses follow one object put in front of someone: an obstacle. It can be a practical difficulty, a set exercise, a continuing source of trouble, a person who embodies it, a public matter, a fault inside a machine, a constructed puzzle, or a specification written for a machine.","cn":"八个义项沿一个被摆到人面前的东西展开：一个障碍。它可以是实际困难、设计好的练习、持续的麻烦源、体现了麻烦的人、公共议题、机器内部的故障、构造出的谜题，或为机器写好的规格说明。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stone rolled into the road, with the road continuing past it.","cn":"核心意象：一块被滚到路中间的石头，而路还在它后面继续。"},"chain":["THING PUT FORWARD","IN THE WAY","WAITING FOR AN ANSWER","A FAULT INSIDE A SYSTEM","A PERSON WHO RESISTS","A PUZZLE WITH ONE KEY"],"branches":[{"senses":"01 · 02","en":"OBSTACLE AND EXERCISE: a real difficulty, and the same shape deliberately built for practice.","cn":"障碍与练习：真实的困难，以及为练习而刻意造出的同一形状。"},{"senses":"03 · 04","en":"WHERE THE TROUBLE COMES FROM: an arrangement that keeps producing blocks, and a person who becomes one.","cn":"麻烦的来源：不断产生阻碍的安排，以及本身变成阻碍的人。"},{"senses":"05","en":"SCALED TO A SOCIETY: a difficulty no single hand can remove.","cn":"放大到社会：一只手无法搬走的困难。"},{"senses":"06","en":"LOCATED INSIDE A MACHINE: the general obstacle narrowed to a named defect.","cn":"定位在机器内部：泛指的障碍被收窄为有名字的缺陷。"},{"senses":"07 · 08","en":"PURE FORM: everything irrelevant stripped away, for a solver or for a program.","cn":"纯粹形式：无关之物全被剥去，无论对象是解题人还是程序。"}]},"affixes":{"intro":{"en":"Problem is a Greek compound borrowed whole, so its parts are visible but do not combine freely in English.","cn":"problem 是整体借入的希腊复合词，因此各部分可见，但在英语里不能自由组合。"},"latinIntro":{"en":"Latin took the Greek noun as a loan and passed it on; the productive part in English is the suffix that builds the adjective.","cn":"拉丁语把这个希腊名词作为借词收下并传出；在英语里真正能产的是构成形容词的那个词尾。"},"items":[{"word":"pro-","structure":"pro- (Greek prefix, 'before, forward')","meaning":"forward","meaningCN":"向前","example":"The prefix puts the object in front of someone.","exampleCN":"这个前缀把物体放到某人前面。"},{"word":"ballein","structure":"ballein (Greek verb, 'to throw')","meaning":"to throw","meaningCN":"投掷","example":"The root supplies the throwing hand.","exampleCN":"这个词根提供投掷的手。"},{"word":"problema","structure":"pro- + ballein + -ma (result noun)","meaning":"a thing put forward","meaningCN":"被提出之物","example":"A task is something thrown down in front of you.","exampleCN":"任务就是被扔到你面前的东西。"},{"word":"problem","structure":"problema (Greek noun through Latin)","meaning":"a difficulty or question","meaningCN":"难题；问题","example":"She stared at the problem for ten minutes.","exampleCN":"她盯着这道题看了十分钟。"},{"word":"-atic","structure":"-atikos (Greek adjective ending)","meaning":"of the nature of","meaningCN":"具有……性质的","example":"The ending builds the adjective from the noun.","exampleCN":"这个词尾由名词造出形容词。"},{"word":"problematic","structure":"problem + -atic","meaning":"full of difficulty, doubtful","meaningCN":"棘手的；可疑的","example":"The evidence was problematic.","exampleCN":"这些证据很成问题。"},{"word":"problematically","structure":"problematic + -ally (adverb)","meaning":"in a doubtful way","meaningCN":"成问题地","example":"The claim was problematically vague.","exampleCN":"这个主张模糊得成问题。"},{"word":"problem-solving","structure":"problem + solving (compound noun)","meaning":"the activity of working out difficulties","meaningCN":"解决问题","example":"Problem-solving is taught through cases.","exampleCN":"解决问题的能力通过案例来教。"},{"word":"emblem","structure":"en- + ballein","meaning":"something inserted as a sign","meaningCN":"徽记；象征","example":"The same throwing verb produces a sign put into a surface.","exampleCN":"同一个「投掷」动词产出被嵌进表面的标记。"},{"word":"symbol","structure":"syn- + ballein","meaning":"things thrown together as a token","meaningCN":"符号；象征","example":"A token was two halves thrown together to be matched.","exampleCN":"信物是两半被丢到一起以作核对。"}],"latinEntries":[{"word":"problema","structure":"problema, problematis (n., third declension, from Greek)","meaning":"a question, a problem","meaningCN":"问题；难题"},{"word":"problematicus","structure":"problematicus, problematica, problematicum (adj., from Greek)","meaning":"doubtful, disputed","meaningCN":"可疑的；有争议的"}],"derivatives":[{"word":"problematic","pos":"adj.","zh":"成问题的；棘手的（名词词干加形容词后缀，指「充满难题的」）"},{"word":"problematically","pos":"adv.","zh":"成问题地（形容词加副词后缀）"},{"word":"problem-solving","pos":"n.","zh":"解决问题（复合名词，指这一活动或能力）"},{"word":"problem-solver","pos":"n.","zh":"善于解决问题的人（复合名词，指从事该活动的人）"}]}},{"word":"solution","ipa_uk":"/səˈluːʃn/","ipa_us":"/səˈluːʃən/","definition_zh":"解决办法；溶液；解答；解决方案；解","definition_en":"an answer that removes a difficulty, a liquid with something dissolved in it, or the act of loosening a knot","core_image":"一只烧杯里，白色粉末在温水里一点点消失，液体重新变得清澈","scene":"化学课的通风橱前，学生把白色粉末一点点倒进温水里，用玻璃棒搅到颗粒全部消失。The solution cleared as the last of the powder dissolved.","sceneCN":"这里 solution 指「溶有某种物质的液体」（第 2 个义项：溶液）；句意为最后一点粉末溶尽时，这杯溶液变得清澈。","pos":[{"tag":"n.","zh":"解决办法；解答；溶液；解（可数或不可数）"}],"collocations":[{"phrase":"a solution to","zh":"……的解决办法"},{"phrase":"find a solution","zh":"找到解决办法"},{"phrase":"salt solution","zh":"盐溶液"},{"phrase":"a political solution","zh":"政治解决办法"},{"phrase":"solution set","zh":"解集"},{"phrase":"an effective solution","zh":"有效的方案"},{"phrase":"solution of an equation","zh":"方程的解"}],"forms":[{"label":"复数","form":"solutions"},{"label":"动词","form":"solve"},{"label":"形容词（可解决的）","form":"soluble"},{"label":"形容词（溶解性的）","form":"solvent"},{"label":"副词（罕用）","form":"solvedly"},{"label":"名词（解题者）","form":"solver"}],"derivatives":[{"word":"solve","pos":"v.","zh":"解决；解答（由 solution 反向缩合而成，指做那件「解开」的事）"},{"word":"soluble","pos":"adj.","zh":"可溶的；可解决的（拉丁词根加「能够……」的后缀）"},{"word":"solvent","pos":"n./adj.","zh":"溶剂 / 有偿付能力的（同词根，由「能解开」转为「能偿付」）"},{"word":"dissolve","pos":"v.","zh":"溶解；解散（前缀「分开」加同词根，指让结合散开）"},{"word":"resolution","pos":"n.","zh":"解决；决议；分辨率（前缀「再」加同族名词，指重新解开或下定决心）"}],"senses":[{"no":"01","title":"An answer that removes a difficulty","titleCN":"解决困难的办法","definition":"something that puts an end to a problem or makes it manageable","definitionCN":"使问题结束或变得可处理的东西","example":"There is no simple solution to the housing shortage.","exampleCN":"住房短缺没有简单的解决办法。","why":"The Latin verb meant 'to loosen', so an answer is what unties the knot rather than what covers it.","whyCN":"拉丁动词意为「解开」，因此办法是把结解开的东西，而不是把结盖住的东西。"},{"no":"02","title":"A liquid with something dissolved in it","titleCN":"溶液","definition":"a liquid in which a substance has been broken up and distributed evenly","definitionCN":"某种物质被分散均匀地分布于其中的液体","example":"The solution cleared as the last of the powder dissolved.","exampleCN":"最后一点粉末溶尽时，这杯溶液变得清澈。","why":"The same loosening applies to matter: the solid is loosened into the liquid and disappears as a separate phase.","whyCN":"同一种「松开」也适用于物质：固体被松开进入液体，作为一个独立相消失。"},{"no":"03","title":"The act of solving","titleCN":"解答的过程","definition":"the work of finding the answer, viewed as an activity rather than its result","definitionCN":"找出答案的工作，被视为活动而非结果","example":"The solution of that equation took the class a whole lesson.","exampleCN":"解出那道方程花了全班一节课。","why":"A noun of action can name either the doing or the thing done, and this sense keeps the doing.","whyCN":"表动作的名词既可指做的过程，也可指做成之物，这一义项保留了过程。"},{"no":"04","title":"A commercial offering","titleCN":"解决方案（产品）","definition":"a product or service packaged as the answer to a customer's difficulty","definitionCN":"被打包成客户困难之答案的产品或服务","example":"The firm sells software solutions rather than software.","exampleCN":"这家公司卖的是软件解决方案，而不是软件。","why":"Business language stretches the word until the answer becomes something you can buy.","whyCN":"商业语言把这个词拉长，直到「办法」变成可以买的东西。"},{"no":"05","title":"A value that satisfies an equation","titleCN":"方程的解","definition":"in mathematics, the value or set of values for which a statement is true","definitionCN":"在数学中，使某个陈述成立的那个值或那组值","example":"Every solution of the equation lies between zero and one.","exampleCN":"这个方程的每个解都落在零与一之间。","why":"Mathematics fixes the loosening as an exact condition: the value at which the constraint releases.","whyCN":"数学把「解开」固定为一个精确条件：约束松开时的那个值。"},{"no":"06","title":"Liquid medicine","titleCN":"药水","definition":"a medicine prepared as a liquid with the active substance dissolved","definitionCN":"把有效成分溶入液体制成的药物","example":"The nurse measured ten millilitres of the solution.","exampleCN":"护士量了十毫升药水。","why":"Pharmacy keeps the chemical sense and applies it to a dose.","whyCN":"药学保留了化学义，并把它用到一次剂量上。"},{"no":"07","title":"A political settlement","titleCN":"政治解决","definition":"an agreed way out of a conflict, reached by negotiation rather than force","definitionCN":"通过谈判而非武力为冲突找到的共同出路","example":"Both sides described the talks as the only solution.","exampleCN":"双方都把谈判说成唯一的解决办法。","why":"Public conflict is treated as a knot that can be untied by agreement.","whyCN":"公共冲突被当作一个可以靠协议解开的结。"},{"no":"08","title":"The unravelling of a plot","titleCN":"情节的解结","definition":"in drama and narrative, the point where complications are resolved","definitionCN":"在戏剧与叙事中，纠葛被解开的那一刻","example":"The play's solution arrives in a single unspoken gesture.","exampleCN":"这部剧的解结出现在一个无声的动作里。","why":"Literary criticism borrowed the chemical and logical word for the moment a story's tension dissolves.","whyCN":"文学批评借用了这个化学与逻辑的用词，指故事张力消解的那一刻。"}],"etymology":{"intro":{"en":"Solution comes from a Latin noun of action meaning 'a loosening, a dissolving, an explanation'. One root covers untiying a knot, dissolving a solid and settling a debt.","cn":"solution 来自拉丁语的表动作名词，意为「松开、溶解、解释」。同一个词根同时涵盖解结、溶解固体与清偿债务。"},"items":[{"era":"LATIN LUERE","en":"The verb meant 'to loosen, to pay'. Loosening and paying were one idea: a binding obligation is undone by payment.","cn":"这个动词意为「松开、偿付」。松开与偿付是同一个想法：一项有约束力的义务通过偿付被解开。"},{"era":"LATIN SOLVERE","en":"The compound added a prefix meaning 'apart', giving 'to loosen, untie, dissolve, pay'. It is the source of a large English family.","cn":"复合词加了一个意为「分开」的前缀，得出「解开、松绑、溶解、偿付」。它是一大批英语词的来源。"},{"era":"LATIN SOLUTIO","en":"The noun meant 'a loosening, a dissolving; an explanation; a payment'. An explanation was pictured as loosening a difficulty.","cn":"这个名词意为「松开、溶解；解释；偿付」。解释被描绘为把一个困难松开。"},{"era":"OLD FRENCH AND MIDDLE ENGLISH","en":"The word entered English in the fourteenth century, first as the act of dissolving or explaining, and the chemical sense came early.","cn":"这个词在 14 世纪进入英语，最初指溶解或解释的动作，化学义很早就出现了。"},{"era":"SEVENTEENTH-CENTURY BACK-FORMATION","en":"English formed the verb solve from the noun, so the verb is younger than the noun it is derived from.","cn":"英语由这个名词反向造出动词 solve，因此动词比它所派自的名词更年轻。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of the loosening verb is not established, and the reconstructed Indo-European root offered for it remains a hypothesis.","cn":"来源不确定：这个「松开」动词的更早来源没有定论，为它提出的印欧词根属重构形式，仍只是假说。"}]},"similar":{"note":{"en":"The first group holds words from the same loosening family that are often swapped; the second holds near neighbours for an answer.","cn":"第一组是同出「松开」词族、常被互换的词；第二组是表示「答案」的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"solve","ipa":"/sɒlv/","tag":"the verb","definition":"The back-formed verb: to find the answer, or to dissolve; it cannot replace the noun in a sentence slot.","definitionCN":"反向构成的动词：指找到答案或使溶解；在句中不能替代名词。"},{"word":"solvent","ipa":"/ˈsɒlvənt/","tag":"the liquid that dissolves","definition":"The substance doing the dissolving, and separately a person or firm able to pay debts, from the paying sense of the root.","definitionCN":"指起溶解作用的物质；另指有偿付能力的个人或公司，来自词根的「偿付」义。"},{"word":"soluble","ipa":"/ˈsɒljəbl/","tag":"the adjective","definition":"Same root with an ending meaning 'capable of being': able to be dissolved, or able to be solved.","definitionCN":"同词根加意为「能够被……」的词尾：可溶解的，或可解决的。"},{"word":"absolution","ipa":"/ˌæbsəˈluːʃn/","tag":"same root, other prefix","definition":"A prefix meaning 'away' plus the same noun: a release from guilt, not a chemical mixture.","definitionCN":"意为「离开」的前缀加同一名词：指罪责的赦免，而不是化学混合物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"answer","ipa":"/ˈɑːnsə/","tag":"the broad word","definition":"It can be a reply to anything, including a question that is not a difficulty, so it is wider than solution.","definitionCN":"可以是对任何东西的回应，包括并非困难的问题，因此比 solution 更宽。"},{"word":"remedy","ipa":"/ˈremədi/","tag":"cure what is wrong","definition":"It implies a fault or an illness being put right, with a medical flavour that solution lacks.","definitionCN":"暗示错处或病症被纠正，带 solution 所没有的医疗色彩。"},{"word":"resolution","ipa":"/ˌrezəˈluːʃn/","tag":"same root, more force","definition":"It stresses a firm decision or a formal settlement, and in optics it names the sharpness of an image.","definitionCN":"强调坚定的决定或正式的解决；在光学中指图像的清晰度。"},{"word":"workaround","ipa":"/ˈwɜːkəraʊnd/","tag":"temporary, not final","definition":"A plain compound for a way past a problem without removing it, the opposite of a true solution.","definitionCN":"朴素的复合词，指绕过问题而不消除它，与真正的解决相反。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin verb means 'to loosen', so a solution loosens the knot a problem tied.","cn":"拉丁动词意为「松开」，所以 solution 是把问题打的那个结松开。"},{"en":"The family runs solve, solution, soluble, solvent, dissolve, resolution.","cn":"同族词包括 solve、solution、soluble、solvent、dissolve、resolution。"},{"en":"Fixed phrases show the two main senses: a solution to a problem, and a salt solution.","cn":"固定搭配显示两大义：问题的办法，以及盐溶液。"},{"en":"The same root carries 'to pay', which is why a solvent firm is one that can meet its debts.","cn":"同一个词根还带「偿付」义，因此有偿付能力的公司用 solvent 这个词。"},{"en":"Mathematics and drama both use the word for the moment a tension is released.","cn":"数学与戏剧都用这个词指张力被释放的那一刻。"}],"abstract":[{"en":"Picture a knotted string laid flat, then pulled until it runs straight.","cn":"想象一根打了结的线被摊平，再被拉直。"},{"en":"Picture sugar disappearing into warm water without leaving a trace.","cn":"想象糖在温水里消失，不留痕迹。"},{"en":"Picture a locked door and the one key that was under the mat all along.","cn":"想象一扇锁着的门，和那把一直压在门垫下的钥匙。"}]},"examples":[{"en":"The simplest solution is to reduce the number of forms.","cn":"最简单的办法是减少表格的数量。"},{"en":"Stir the powder until it forms a clear solution.","cn":"搅拌粉末，直到形成澄清的溶液。"},{"en":"The equation has two solutions, one positive and one negative.","cn":"这个方程有两个解，一正一负。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"solut（松开）+ ion（动作或结果）＝ 把结松开的东西 → 解决办法；把固体松开进液体 → 溶液。","word":"solution"},"root":"拉丁 solutio「松开、溶解、解释」，来自 solvere「解开、溶解、偿付」，由意为「分开」的前缀加 luere「松开、偿付」构成；更深来源不确定。同族有 solve、soluble、solvent、dissolve、resolution。","sensesIntro":{"en":"Eight senses follow one loosening. A knot can be untied in a plan, a solid can be loosened into a liquid, the work of untiying can be named, the answer can be sold, a constraint can release at one exact value, a dose can be dissolved, a conflict can be untied by agreement, and a plot can come loose at the end.","cn":"八个义项沿一次「松开」展开。结可以在计划里被解开，固体可以被松开进液体，解结的工作可以被命名，答案可以被出售，约束可以在某个精确值上释放，一次剂量可以被溶成液体，冲突可以靠协议解开，情节也可以在结尾处松开。"},"semanticMap":{"core":{"en":"CORE IMAGE: a knot pulled apart until the rope lies straight.","cn":"核心意象：一个结被拉开，直到绳子摊直。"},"chain":["UNTIE AND RELEASE","THE KNOT COMES LOOSE","WHAT IS LEFT AFTER DISSOLVING","A MIXTURE THAT HOLDS","TENSION RELEASED AT ONE VALUE","A DISPUTE SETTLED"],"branches":[{"senses":"01 · 03","en":"THE ACT AND ITS ANSWER: untiying as work, and untiying as the thing that ends the difficulty.","cn":"动作与答案：作为工作的解开，以及作为结束困难之物的解开。"},{"senses":"02 · 06","en":"MATTER LOOSENED: a solid spread through a liquid, and the same mixture given as a dose.","cn":"被松开的物质：散布于液体的固体，以及同一混合物作为一次剂量。"},{"senses":"04","en":"THE ANSWER FOR SALE: business turns a release into a product with a price.","cn":"出售的答案：商业把一次释放变成有价格的产品。"},{"senses":"05","en":"RELEASE AT ONE VALUE: mathematics makes the loosening exact.","cn":"在一个值上释放：数学让这种松开变得精确。"},{"senses":"07 · 08","en":"TENSION SETTLED: a conflict untied by agreement, and a story untied by its final turn.","cn":"张力落定：靠协议解开的冲突，以及靠最后一转解开的故事。"}]},"affixes":{"intro":{"en":"Solution is a Latin noun of action, and the same root appears with several prefixes to give a whole English family.","cn":"solution 是拉丁语的表动作名词，同一词根配上若干前缀，给出了一整族英语词。"},"latinIntro":{"en":"The loosening verb builds words for dissolving, resolving and absolving, and the noun ending marks the act or its result.","cn":"这个「松开」动词构成表示溶解、解决与赦免的词，而名词词尾标记动作或其结果。"},"items":[{"word":"solvere","structure":"solvere, solvi, solutum (Latin verb, third conjugation)","meaning":"to loosen, dissolve, pay","meaningCN":"解开；溶解；偿付","example":"The root joins untiying with paying a debt.","exampleCN":"这个词根把解结与偿债连在一起。"},{"word":"luere","structure":"luere (Latin verb, 'to loosen, pay')","meaning":"to loosen; to pay","meaningCN":"松开；偿付","example":"The simpler verb already contains both ideas.","exampleCN":"更简单的那个动词已含两层意思。"},{"word":"-tion","structure":"-tio (Latin noun of action ending)","meaning":"the act or result","meaningCN":"动作或结果","example":"The ending turns the verb into an event or a product.","exampleCN":"这个词尾把动词变成事件或产物。"},{"word":"solution","structure":"solvere + -tion","meaning":"a loosening; an answer","meaningCN":"松开；解答","example":"The solution cleared as the powder dissolved.","exampleCN":"粉末溶尽，溶液变清。"},{"word":"solve","structure":"solve (English verb back-formed from the noun)","meaning":"to find the answer","meaningCN":"解决；解答","example":"She solved the second problem quickly.","exampleCN":"她很快解出了第二道题。"},{"word":"soluble","structure":"solvere + -ble ('capable of being')","meaning":"able to be dissolved","meaningCN":"可溶的","example":"The salt is highly soluble in warm water.","exampleCN":"这种盐在温水里极易溶解。"},{"word":"solvent","structure":"solvere + -ent (one that acts)","meaning":"a dissolving liquid; able to pay","meaningCN":"溶剂；有偿付能力的","example":"Water is the most common solvent.","exampleCN":"水是最常见的溶剂。"},{"word":"dissolve","structure":"dis- + solvere","meaning":"to break up into a liquid","meaningCN":"溶解；解散","example":"The prefix means 'apart', so the binding is undone.","exampleCN":"前缀意为「分开」，因此结合被解开。"},{"word":"resolution","structure":"re- + solutio","meaning":"a settling or a firm decision","meaningCN":"解决；决议","example":"The council passed a resolution.","exampleCN":"议会通过了一项决议。"},{"word":"absolute","structure":"ab- + solvere","meaning":"released from limits","meaningCN":"绝对的；不受限制的","example":"The prefix means 'away', so the thing is freed from conditions.","exampleCN":"前缀意为「离开」，因此该物脱离了条件。"}],"latinEntries":[{"word":"solvere","structure":"solvere, solvi, solutum (verb, third conjugation)","meaning":"to loosen, dissolve, pay","meaningCN":"解开；溶解；偿付"},{"word":"luere","structure":"luere, lui (verb, third conjugation)","meaning":"to loosen; to pay","meaningCN":"松开；偿付"},{"word":"solutio","structure":"solutio, solutionis (f., third declension)","meaning":"a loosening, an explanation","meaningCN":"松开；解释"},{"word":"solubilis","structure":"solubilis, solubile (adj.)","meaning":"that can be loosened","meaningCN":"可解开的；可溶的"}],"derivatives":[{"word":"solve","pos":"v.","zh":"解决；解答（由 solution 反向缩合而成，指做那件「解开」的事）"},{"word":"soluble","pos":"adj.","zh":"可溶的；可解决的（拉丁词根加「能够……」的后缀）"},{"word":"solvent","pos":"n./adj.","zh":"溶剂 / 有偿付能力的（同词根，由「能解开」转为「能偿付」）"},{"word":"dissolve","pos":"v.","zh":"溶解；解散（前缀「分开」加同词根，指让结合散开）"},{"word":"resolution","pos":"n.","zh":"解决；决议；分辨率（前缀「再」加同族名词，指重新解开或下定决心）"}]}},{"word":"synthesis","ipa_uk":"/ˈsɪnθəsɪs/","ipa_us":"/ˈsɪnθəsɪs/","definition_zh":"综合；合成；综合体；合题","definition_en":"the combining of separate parts into a whole, or the whole that results","core_image":"长桌上摊着十几张卡片，颜色相同的被归成一叠，最后连成一条完整的故事线","scene":"资料室的长桌上摊着十几张卡片，学生把颜色相同的归成一叠，再按线索连成一条完整的故事线。Synthesis came only after the scattered notes were grouped and read as one account.","sceneCN":"这里 synthesis 指「把分散的部分合为一个整体」（第 1 个义项：综合）；句意为只有把散乱的笔记归类并读成一份完整叙述之后，综合才发生。","pos":[{"tag":"n.","zh":"综合；合成；综合体；合题（复数形式不走常规英语规则，而沿用希腊式变化）"}],"collocations":[{"phrase":"chemical synthesis","zh":"化学合成"},{"phrase":"a synthesis of","zh":"……的综合体"},{"phrase":"protein synthesis","zh":"蛋白质合成"},{"phrase":"speech synthesis","zh":"语音合成"},{"phrase":"synthesis essay","zh":"综合论述文"},{"phrase":"thesis and synthesis","zh":"正题与合题"}],"forms":[{"label":"复数（希腊式）","form":"syntheses"},{"label":"动词","form":"synthesize"},{"label":"形容词","form":"synthetic"},{"label":"副词","form":"synthetically"},{"label":"名词（合成器）","form":"synthesizer"},{"label":"形容词（可合成的）","form":"synthesizable"}],"derivatives":[{"word":"synthesize","pos":"v.","zh":"合成；综合（名词加表「使成为」的动词后缀）"},{"word":"synthetic","pos":"adj.","zh":"合成的；人造的（希腊形容词后缀，指「由组合而成」）"},{"word":"synthesizer","pos":"n.","zh":"合成器；综合者（动词加表施动者或器具的后缀）"},{"word":"synthetically","pos":"adv.","zh":"以合成方式（形容词加副词后缀）"}],"senses":[{"no":"01","title":"Combining parts into a whole","titleCN":"把分散部分合为整体","definition":"the act of bringing separate elements together so that they form one coherent thing","definitionCN":"把彼此分离的要素合到一起，形成一件连贯之物的行为","example":"Synthesis came only after the scattered notes were grouped and read as one account.","exampleCN":"只有把散乱的笔记归类并读成一份完整叙述之后，综合才发生。","why":"The Greek noun means 'a putting together', and its verb means 'to place' — the image is literally placing side by side.","whyCN":"希腊名词意为「放到一起」，其动词意为「放置」——画面就是字面上的并排摆放。"},{"no":"02","title":"Chemical synthesis","titleCN":"化学合成","definition":"the building of a compound from simpler substances in a controlled reaction","definitionCN":"在受控反应中由较简单物质构建化合物","example":"The synthesis of the dye takes four steps and a cold bath.","exampleCN":"这种染料的合成需要四步和一个冰浴。","why":"Chemistry takes the literal meaning: separate substances are placed together and made to combine.","whyCN":"化学取了字面义：分离的物质被放到一起并被迫结合。"},{"no":"03","title":"The composite result","titleCN":"综合体","definition":"the whole produced by combining, considered as a thing in its own right","definitionCN":"由组合产生的整体，被当作独立存在之物","example":"The novel is a synthesis of two very different traditions.","exampleCN":"这部小说是两种极不相同传统的综合体。","why":"A verb of making yields a noun that can name what was made, not only the making.","whyCN":"表「制作」的动词产出的名词，既能指制作，也能指所制之物。"},{"no":"04","title":"The Hegelian synthesis","titleCN":"合题","definition":"in dialectical philosophy, the higher stage that reconciles a thesis and its opposite","definitionCN":"在辩证哲学中，调和正题与其对立面的更高阶段","example":"The argument moves from thesis to antithesis to synthesis.","exampleCN":"论证从正题走到反题，再走到合题。","why":"Philosophy borrowed the word for a resolution that keeps what was true in both earlier stages.","whyCN":"哲学借这个词指一种保留前两阶段中真东西的解决。"},{"no":"05","title":"A synthesis essay","titleCN":"综合论述文","definition":"a piece of writing that combines several sources into one supported position","definitionCN":"把若干来源合成一个有依据立场的写作","example":"The exam asks for a synthesis of three provided articles.","exampleCN":"这场考试要求综合所提供的三篇文章。","why":"Writing instruction took the word for making a whole and applied it to an exercise that must weld sources together.","whyCN":"写作教学把这个表示「造出整体」的词，用到一项必须把来源焊合起来的练习上。"},{"no":"06","title":"Speech synthesis","titleCN":"语音合成","definition":"the artificial production of speech from text or symbols","definitionCN":"由文字或符号人工生成语音","example":"Modern synthesis makes a recorded voice sound almost human.","exampleCN":"现代语音合成让录制的声音听起来几乎像真人。","why":"Engineering extends the act to sound: separate phonemes are placed in order until a voice is built.","whyCN":"工程把这动作扩展到声音上：分离的音素被按序放好，直到造出一个嗓音。"},{"no":"07","title":"Biological synthesis in cells","titleCN":"生物合成","definition":"the building of a substance by a living cell from simpler materials","definitionCN":"活细胞由较简单材料构建物质","example":"Protein synthesis begins at the ribosome.","exampleCN":"蛋白质合成从核糖体开始。","why":"The cell performs the chemist's act at a smaller scale, and the word needs no change of form.","whyCN":"细胞在更小的尺度上做化学家所做的事，而这个词无需改变形式。"},{"no":"08","title":"A level in a learning taxonomy","titleCN":"综合层级（教育目标分类）","definition":"in education, the stage at which a learner builds something new from existing knowledge","definitionCN":"在教育中，学习者用已有知识造出新东西的阶段","example":"The task sits at the synthesis level of the old taxonomy.","exampleCN":"这项任务处在旧分类体系的综合层级。","why":"A curriculum made the act into a measurable stage, so a verb of building became a place on a ladder.","whyCN":"一套课程把这个动作变成可测的阶段，于是表「构建」的动词成了阶梯上的一格。"}],"etymology":{"intro":{"en":"Synthesis is a Greek noun meaning 'a putting together', taken into English through Latin. Its parts are the same pieces that build thesis and hypothesis.","cn":"synthesis 是希腊名词，意为「放到一起」，经拉丁语进入英语。它的组成部分与构成 thesis 和 hypothesis 的是同样的碎片。"},"items":[{"era":"GREEK TITHENAI","en":"The verb meant 'to place, put, set'. It is the same placing verb that appears in thesis and in hypothesis.","cn":"这个动词意为「放置、摆、设立」。它就是出现在 thesis 与 hypothesis 里的那个「放置」动词。"},{"era":"GREEK SYN-","en":"The prefix meant 'together, with'. It appears in dozens of Greek compounds that English later borrowed.","cn":"这个前缀意为「一起、共同」。它出现在数十个后来被英语借入的希腊复合词中。"},{"era":"GREEK SYNTHESIS","en":"The noun meant 'a putting together, a composition'. It could name a compound object as well as the act of compounding.","cn":"这个名词意为「放到一起、组合」。它既能指被组合的物，也能指组合的行为。"},{"era":"LATIN SYNTHESIS","en":"Latin borrowed the noun with the same sense, and it also named a kind of composite garment; the borrowing is learned rather than native.","cn":"拉丁语以同样的意义借入这个名词，也用它指一种拼接式的衣服；这是书面借词，而非本族构词。"},{"era":"EARLY MODERN ENGLISH","en":"English used the word for logical composition first, and chemistry adopted it once the modern science took shape.","cn":"英语最初用它指逻辑上的组合，现代科学成形后化学采用了它。"},{"era":"MODERN TECHNICAL SENSES AND UNCERTAIN","en":"Twentieth-century biology, computing and education each gave the word a fixed place. Source uncertain: the deeper origin of the placing verb is a reconstructed form.","cn":"20 世纪的生物学、计算与教育学各自给了这个词一个固定位置。来源不确定：那个「放置」动词的更早来源属重构形式。"}]},"similar":{"note":{"en":"The first group holds words built from the same Greek placing verb; the second holds near neighbours for combining.","cn":"第一组是由同一个希腊「放置」动词构成的词；第二组是表示「结合」的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"thesis","ipa":"/ˈθiːsɪs/","tag":"placed down","definition":"Same placing verb without the 'together' prefix: a statement set down, hence a proposition or a long research essay.","definitionCN":"同一个「放置」动词但不带「一起」前缀：被放下的陈述，因此指论点或长篇研究论文。"},{"word":"hypothesis","ipa":"/haɪˈpɒθəsɪs/","tag":"placed underneath","definition":"The prefix means 'under': something placed beneath as a basis, hence a provisional explanation.","definitionCN":"前缀意为「在下」：作为基础被放在下面的东西，因此指暂定的解释。"},{"word":"antithesis","ipa":"/ænˈtɪθəsɪs/","tag":"placed against","definition":"The prefix means 'against': the counter-statement that a synthesis is said to reconcile.","definitionCN":"前缀意为「相对」：那个据说被合题调和的反面陈述。"},{"word":"synthetic","ipa":"/sɪnˈθetɪk/","tag":"the adjective","definition":"It describes what has been combined, or what is artificial; it never names the act of combining.","definitionCN":"形容已被组合的东西，或人造之物；它从不指组合这一行为。"}]},{"heading":"NEAR MEANING","entries":[{"word":"combination","ipa":"/ˌkɒmbɪˈneɪʃn/","tag":"parts joined","definition":"It says only that things are joined; it makes no claim that the result is coherent.","definitionCN":"只说明事物被接在一起，不主张结果连贯。"},{"word":"integration","ipa":"/ˌɪntɪˈɡreɪʃn/","tag":"parts made to work as one","definition":"It stresses that the joined parts function together, often of systems or groups.","definitionCN":"强调接起来的各部分共同运作，常用于系统或群体。"},{"word":"fusion","ipa":"/ˈfjuːʒn/","tag":"parts merged","definition":"It implies the parts lose their separate identity, which synthesis does not require.","definitionCN":"暗示各部分失去独立身份，而 synthesis 不要求如此。"},{"word":"composite","ipa":"/ˈkɒmpəzɪt/","tag":"the made object","definition":"It names the resulting object as a thing with visible parts, not the process.","definitionCN":"指结果之物，强调其各部分仍可见，而非指过程。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Greek parts mean 'together' plus 'place': synthesis is placing things together.","cn":"希腊成分意为「一起」加「放置」：synthesis 就是把东西放到一起。"},{"en":"The family runs synthesis, synthesize, synthetic, synthesizer, synthetically.","cn":"同族词包括 synthesis、synthesize、synthetic、synthesizer、synthetically。"},{"en":"Fixed phrases mark the fields: chemical synthesis, protein synthesis, speech synthesis.","cn":"固定搭配标出领域：化学合成、蛋白质合成、语音合成。"},{"en":"The same placing verb gives thesis, hypothesis and antithesis with other prefixes.","cn":"同一个「放置」动词配上别的前缀，给出 thesis、hypothesis、antithesis。"},{"en":"The plural is Greek in shape, so the second syllable changes rather than gaining a simple ending.","cn":"复数按希腊式变化，因此变的是第二个音节，而不是简单加一个词尾。"}],"abstract":[{"en":"Picture two colours mixed until a third appears that neither contained.","cn":"想象两种颜色调出一种两者都不曾含有的第三种。"},{"en":"Picture a dozen cards sorted into piles, then read as one story.","cn":"想象十几张卡片分堆之后，被读成一个故事。"},{"en":"Picture a bridge built from two banks that never touch.","cn":"想象一座桥由两岸搭起，而两岸从不接触。"}]},"examples":[{"en":"The report is a synthesis of five separate studies.","cn":"这份报告是五项独立研究的综合。"},{"en":"The laboratory completed the synthesis in a single afternoon.","cn":"实验室在一个下午就完成了这次合成。"},{"en":"Good synthesis needs disagreement as much as agreement.","cn":"好的综合既需要共识，也同样需要分歧。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"syn（一起）+ thesis（放置）＝ 把分开的东西放到一起 → 综合、合成。","word":"synthesis"},"root":"希腊 synthesis「放到一起、组合」，由 syn-「一起」+ tithenai「放置」构成；该动词更早来源属重构形式，一般认为与拉丁 facere「做」、英语 do 同出。经拉丁进入英语。同族有 thesis、hypothesis、antithesis、synthetic。","sensesIntro":{"en":"Eight senses follow one placement: parts set side by side until they hold as one. The parts can be ideas, chemicals, traditions, philosophical opposites, sources in an essay, phonemes in a voice, molecules in a cell, or pieces of knowledge in a learner's task.","cn":"八个义项沿一次摆放展开：部分被并排放好，直到合为一体。这些部分可以是观念、化学品、传统、哲学上的对立面、文章里的来源、语音里的音素、细胞里的分子，或学习者任务中的知识碎片。"},"semanticMap":{"core":{"en":"CORE IMAGE: many pieces laid side by side until they read as one object.","cn":"核心意象：许多碎片并排摆好，直到被读成一件东西。"},"chain":["PLACED TOGETHER","A WHOLE THAT DID NOT EXIST","THE THING MADE","AN OPPOSITE RECONCILED","MANY SOURCES, ONE VOICE","A STEP IN A TAXONOMY"],"branches":[{"senses":"01 · 03","en":"THE ACT AND THE MADE THING: placing together, and the composite that now stands on its own.","cn":"行为与成品：放到一起的动作，以及如今独立站立的综合体。"},{"senses":"02 · 07","en":"MADE IN A FLASK, MADE IN A CELL: the same building of a compound at two scales.","cn":"在烧瓶里造，在细胞里造：同一件构建化合物的事，两个尺度。"},{"senses":"04","en":"THE OPPOSITE KEPT: philosophy asks the whole to preserve what was true on both sides.","cn":"被保留的对立面：哲学要求整体保住两边各自为真的部分。"},{"senses":"05 · 06","en":"ONE VOICE FROM MANY PARTS: sources welded into an argument, phonemes welded into speech.","cn":"多部分合成一个声音：来源焊成论证，音素焊成语音。"},{"senses":"08","en":"A NAMED STEP: education turns the act into a level that can be assessed.","cn":"被命名的一步：教育把这个动作变成一个可被评定的层级。"}]},"affixes":{"intro":{"en":"Synthesis is a Greek compound taken whole, and its two parts also build several other English words.","cn":"synthesis 是整体借入的希腊复合词，它的两部分还构成若干其他英语词。"},"latinIntro":{"en":"Latin passed the Greek noun on unchanged; the productive endings in English build the verb, the adjective and the device.","cn":"拉丁语原样传出这个希腊名词；英语里能产的词尾则造出动词、形容词与器具名。"},"items":[{"word":"syn-","structure":"syn- (Greek prefix, 'together')","meaning":"together","meaningCN":"一起","example":"The prefix gathers the parts into one place.","exampleCN":"这个前缀把各部分聚到一处。"},{"word":"tithenai","structure":"tithenai (Greek verb, 'to place, put')","meaning":"to place","meaningCN":"放置","example":"The root is the hand setting something down.","exampleCN":"这个词根是把东西放下的那只手。"},{"word":"synthesis","structure":"syn- + tithenai + -sis (noun of action)","meaning":"a putting together","meaningCN":"放到一起；组合","example":"Synthesis came after the notes were grouped.","exampleCN":"笔记归类之后，综合才出现。"},{"word":"synthesize","structure":"synthesis + -ize (to make or cause)","meaning":"to combine into a whole","meaningCN":"合成；综合","example":"Chemists synthesize the compound in four steps.","exampleCN":"化学家用四步合成这种化合物。"},{"word":"synthetic","structure":"synthesis + -tic (adjective ending)","meaning":"combined; artificial","meaningCN":"合成的；人造的","example":"The fabric is synthetic.","exampleCN":"这种织物是合成的。"},{"word":"synthesizer","structure":"synthesize + -er (one that acts)","meaning":"a device or person that combines","meaningCN":"合成器；综合者","example":"The studio owns three synthesizers.","exampleCN":"这间录音室有三台合成器。"},{"word":"synthetically","structure":"synthetic + -ally (adverb)","meaning":"by combining","meaningCN":"以合成方式","example":"The vitamin was produced synthetically.","exampleCN":"这种维生素是以合成方式制出的。"},{"word":"synthesizable","structure":"synthesize + -able ('capable of being')","meaning":"able to be made by combining","meaningCN":"可合成的","example":"The molecule is synthesizable in two steps.","exampleCN":"这个分子可用两步合成。"},{"word":"thesis","structure":"tithenai + -sis (without the 'together' prefix)","meaning":"a statement set down","meaningCN":"论点；论文","example":"The same placing verb stands alone here.","exampleCN":"同一个「放置」动词在这里单独出现。"}],"latinEntries":[{"word":"synthesis","structure":"synthesis, synthesis (f., third declension, from Greek)","meaning":"a composition, a putting together","meaningCN":"组合；放到一起"},{"word":"syntheticus","structure":"syntheticus, synthetice (adj., late Latin, from Greek)","meaning":"of composition","meaningCN":"组合的；合成的"}],"derivatives":[{"word":"synthesize","pos":"v.","zh":"合成；综合（名词加表「使成为」的动词后缀）"},{"word":"synthetic","pos":"adj.","zh":"合成的；人造的（希腊形容词后缀，指「由组合而成」）"},{"word":"synthesizer","pos":"n.","zh":"合成器；综合者（动词加表施动者或器具的后缀）"},{"word":"synthetically","pos":"adv.","zh":"以合成方式（形容词加副词后缀）"}]}},{"word":"synthesize","ipa_uk":"/ˈsɪnθəsaɪz/","ipa_us":"/ˈsɪnθəsaɪz/","definition_zh":"合成；综合；整合（信息、观点）；人工合成（语音）","definition_en":"to build something by combining separate parts, or to combine ideas and information into a whole","core_image":"冰浴中的两只烧瓶，两种无色液体慢慢汇合，白色晶体随后挂在瓶壁上","scene":"药学实验室里，研究员把两种无色的液体在冰浴中慢慢混合，析出的白色晶体挂在瓶壁上。Chemists synthesize the compound in four steps, each guarded by a strict temperature.","sceneCN":"这里 synthesize 指「用较简单的物质构建化合物」（第 2 个义项：化学合成）；句意为化学家用四步合成这种化合物，每一步都要严守温度。","pos":[{"tag":"v.","zh":"合成；综合；整合（信息与观点）；人工合成（语音）"}],"collocations":[{"phrase":"synthesize a compound","zh":"合成一种化合物"},{"phrase":"synthesize information","zh":"整合信息"},{"phrase":"synthesize findings","zh":"综合研究结果"},{"phrase":"synthesize speech","zh":"合成语音"},{"phrase":"synthesize a position","zh":"整合出一个立场"},{"phrase":"synthesize proteins","zh":"合成蛋白质"}],"forms":[{"label":"三单（he/she/it）","form":"synthesizes"},{"label":"过去式","form":"synthesized"},{"label":"过去分词","form":"synthesized"},{"label":"现在分词","form":"synthesizing"},{"label":"名词","form":"synthesis"},{"label":"形容词","form":"synthetic"},{"label":"名词（器具或人）","form":"synthesizer"}],"derivatives":[{"word":"synthesis","pos":"n.","zh":"综合；合成（本词的动词所对应的名词，指过程或结果）"},{"word":"synthesizer","pos":"n.","zh":"合成器；综合者（动词加表施动者或器具的后缀）"},{"word":"synthetic","pos":"adj.","zh":"合成的；人造的（希腊形容词后缀，指「由组合而成」）"},{"word":"resynthesize","pos":"v.","zh":"重新合成（前缀「再」加本词，指在分解之后重建）"}],"senses":[{"no":"01","title":"To combine into a whole","titleCN":"把部分合为整体","definition":"to bring separate elements together so that they form one coherent thing","definitionCN":"把彼此分离的要素合到一起，形成一件连贯之物","example":"She synthesized the interviews into a single narrative.","exampleCN":"她把这些访谈整合成了一份叙述。","why":"The verb is formed from a noun meaning 'a putting together', so its basic act is placing parts side by side.","whyCN":"这个动词由一个意为「放到一起」的名词构成，因此它的基本动作就是把部分并排摆好。"},{"no":"02","title":"To build a compound chemically","titleCN":"化学合成","definition":"to make a substance from simpler ones in a controlled reaction","definitionCN":"在受控反应中由较简单物质制成某物","example":"Chemists synthesize the compound in four steps.","exampleCN":"化学家用四步合成这种化合物。","why":"The literal image returns here: plain substances are placed together and made to join.","whyCN":"字面画面在此回归：普通的物质被放到一起，并被促使结合。"},{"no":"03","title":"To produce a substance in a living body","titleCN":"生物合成","definition":"to build a molecule inside a cell from simpler materials","definitionCN":"在细胞内由较简单材料构建分子","example":"The liver synthesizes the enzyme on demand.","exampleCN":"肝脏按需合成这种酶。","why":"A cell does the same building without glassware, taking small units and linking them in order.","whyCN":"细胞在没有玻璃器皿的情况下做同样的构建：取来小单元，按顺序连接。"},{"no":"04","title":"To combine ideas into an argument","titleCN":"把观点综合成论述","definition":"to weld several positions into one defensible claim","definitionCN":"把若干立场焊成一个可辩护的主张","example":"The essay synthesizes two rival theories without flattening either.","exampleCN":"这篇文章综合两种对立理论，却没有把任何一方抹平。","why":"Once the material is thought rather than matter, the same linking becomes argument-building.","whyCN":"当材料是思想而非物质时，同样的连接就变成论证的搭建。"},{"no":"05","title":"To produce speech artificially","titleCN":"合成语音","definition":"to generate audible speech from text or symbols by machine","definitionCN":"由机器从文字或符号生成可听的语音","example":"The device synthesizes a voice from typed text.","exampleCN":"这台设备由键入的文字合成语音。","why":"Sound is assembled from small units in sequence, which is the same placing-together at a finer grain.","whyCN":"声音由小单元按序拼装，这是同一件「放到一起」在更细的颗粒上。"},{"no":"06","title":"To summarize many sources","titleCN":"综述整合","definition":"to read widely and compress what several studies say into one account","definitionCN":"广泛阅读，把若干研究所述压缩成一份说明","example":"The review synthesizes forty years of fieldwork.","exampleCN":"这篇综述整合了四十年的田野工作。","why":"Many reports become one account, so the act is both combining and reducing.","whyCN":"许多报告变成一份说明，因此这动作既是合并也是压缩。"},{"no":"07","title":"To blend sounds","titleCN":"混制、融合声音","definition":"to combine recorded sound elements into a new single texture","definitionCN":"把录制的声音元素合成一种新的整体质感","example":"The engineer synthesized city noise and a choir into one bed.","exampleCN":"工程师把城市噪音与合唱合成同一条底。","why":"Separate recordings are layered until they are heard as one surface rather than as parts.","whyCN":"分离的录音被层层叠加，直到被听成一整片表面，而不是若干部件。"},{"no":"08","title":"To integrate across fields","titleCN":"跨学科整合","definition":"to draw methods or results from different disciplines into one account","definitionCN":"把不同学科的方法或结果纳入同一说明","example":"The paper synthesizes genetics with archaeology.","exampleCN":"这篇论文把遗传学与考古学整合起来。","why":"Disciplines are the largest units that can be placed side by side, and the word stretches to cover them.","whyCN":"学科是可以并排摆放的最大单元，这个词一直伸展到能覆盖它们。"}],"etymology":{"intro":{"en":"Synthesize is a modern English verb built on the Greek noun for 'a putting together', with a suffix that makes verbs of making.","cn":"synthesize 是近代英语动词，建立在希腊语中意为「放到一起」的名词上，并带一个造「使成为」动词的词尾。"},"items":[{"era":"GREEK SYNTHESIS","en":"The noun meant 'a putting together, a composition'; its two parts mean 'together' and 'place'.","cn":"这个名词意为「放到一起、组合」；它的两部分分别意为「一起」与「放置」。"},{"era":"GREEK -IZEIN","en":"Greek verbs in this ending meant 'to make, to act upon'; Latin and French passed the pattern to English, where it became highly productive.","cn":"带这个词尾的希腊动词意为「使成为、施加作用于」；拉丁语与法语把这个模式传给英语，在英语里变得极其能产。"},{"era":"NINETEENTH CENTURY","en":"English formed the verb from the noun in the early nineteenth century, at first in learned and scientific writing.","cn":"英语在 19 世纪初由这个名词造出动词，最初用于学术与科学写作。"},{"era":"CHEMISTRY","en":"As organic chemistry grew, the verb became the standard way to say that a compound had been built in the laboratory.","cn":"随着有机化学的发展，这个动词成了表示「在实验室里造出化合物」的标准说法。"},{"era":"TWENTIETH-CENTURY EXTENSIONS","en":"Sound engineering, biology and information work each adopted the verb for combining their own materials.","cn":"声音工程、生物学与信息工作各自采用这个动词，指组合它们自己的材料。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of the Greek placing verb is a reconstructed form, and the exact date of the English verb's first use is not certain.","cn":"来源不确定：那个希腊「放置」动词的更早来源属重构形式，这个英语动词首次使用的确切年代也不能确定。"}]},"similar":{"note":{"en":"The first group holds forms and relatives of the same noun that are regularly confused; the second holds other verbs for putting things together.","cn":"第一组是同一个名词的形式与亲属词，常被混淆；第二组是其他表示「把东西合起来」的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"synthesis","ipa":"/ˈsɪnθəsɪs/","tag":"the noun","definition":"The process or the product; the verb is what carries the object and the tense.","definitionCN":"指过程或产物；动词则承担宾语与时态。"},{"word":"synthetic","ipa":"/sɪnˈθetɪk/","tag":"the adjective","definition":"It describes the result as combined or artificial, and cannot take an object.","definitionCN":"形容结果是组合的或人造的，不能带宾语。"},{"word":"synthesizer","ipa":"/ˈsɪnθəsaɪzə/","tag":"the doer","definition":"The person or machine that performs the act, marked by the ending for an agent.","definitionCN":"指执行该行为的人或机器，由表施动者的词尾标记。"},{"word":"synthesise","ipa":"/ˈsɪnθəsaɪz/","tag":"spelling variant","definition":"The British spelling with -ise; the pronunciation is identical and the meaning does not change.","definitionCN":"英式拼法把结尾写成另一种形式；读音相同，意义不变。"}]},{"heading":"NEAR MEANING","entries":[{"word":"combine","ipa":"/kəmˈbaɪn/","tag":"join without judgment","definition":"It says only that things are joined, making no claim that the result is coherent.","definitionCN":"只说明被接在一起，不主张结果连贯。"},{"word":"integrate","ipa":"/ˈɪntɪɡreɪt/","tag":"make them work together","definition":"It stresses that the parts function as one system, often of institutions or data.","definitionCN":"强调各部分作为一个系统运作，常用于机构或数据。"},{"word":"consolidate","ipa":"/kənˈsɒlɪdeɪt/","tag":"make firm","definition":"It stresses strengthening what already exists rather than creating something new.","definitionCN":"强调加固已有之物，而非造出新东西。"},{"word":"summarize","ipa":"/ˈsʌməraɪz/","tag":"shorten, not build","definition":"It compresses material, while synthesize builds a new whole from it.","definitionCN":"指压缩材料，而 synthesize 是由材料造出一个新的整体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The parts mean 'together' and 'place', and the ending means 'make': to make things placed together.","cn":"两部分意为「一起」与「放置」，词尾意为「使成为」：使东西被放到一起。"},{"en":"The family runs synthesis, synthesize, synthetic, synthesizer, synthetically.","cn":"同族词包括 synthesis、synthesize、synthetic、synthesizer、synthetically。"},{"en":"Fixed phrases mark the objects: synthesize a compound, synthesize findings, synthesize speech.","cn":"固定搭配标出宾语：合成化合物、综合研究结果、合成语音。"},{"en":"The verb is younger than the noun, which came into English through Latin.","cn":"动词比名词年轻，名词是经拉丁语进入英语的。"},{"en":"British writing often uses the spelling with -ise, with no change in sound.","cn":"英式写作常在结尾换用另一种拼法，读音不变。"}],"abstract":[{"en":"Picture two rivers meeting and continuing as one wider water.","cn":"想象两条河汇合，继续作为一片更宽的水。"},{"en":"Picture a loom that takes separate threads and produces one cloth.","cn":"想象一台织机，把分开的线织成一整块布。"},{"en":"Picture a choir where many voices become a single chord.","cn":"想象一个合唱团，许多声音合成一个和弦。"}]},"examples":[{"en":"The team synthesized the data from six trials into one table.","cn":"团队把六项试验的数据整合进一张表。"},{"en":"Plants synthesize sugars from light and water.","cn":"植物由光与水合成糖。"},{"en":"The software synthesizes a voice that reads the text aloud.","cn":"这款软件合成一个把文本读出来的声音。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"syn（一起）+ thes（放置）+ ize（使成为）＝ 使分开的东西放到一起 → 合成、综合。","word":"synthesize"},"root":"由希腊名词 synthesis「放到一起」加动词词尾构成，synthesis 来自 syn-「一起」+ tithenai「放置」；该动词更早来源属重构形式。同族有 synthesis、synthetic、synthesizer。","sensesIntro":{"en":"Eight senses follow one act of building by placing parts together. The parts can be chemicals, molecules in a cell, rival ideas, recorded sound, voices, published studies, or methods from two disciplines, and the act always ends with something that did not exist before.","cn":"八个义项沿同一个「把部分放到一起而造出东西」的动作展开。这些部分可以是化学品、细胞里的分子、对立观点、录下的声音、人声、已发表的研究，或两个学科的方法；这个动作总以一件此前不存在的东西收尾。"},"semanticMap":{"core":{"en":"CORE IMAGE: separate threads drawn together on a loom until one cloth appears.","cn":"核心意象：分开的线被拉到织机上，直到出现一整块布。"},"chain":["PLACE TOGETHER","A WHOLE OUT OF PIECES","MADE IN A FLASK","MADE INSIDE A CELL","MADE FROM MANY SOURCES","MADE INTO ONE VIEW"],"branches":[{"senses":"01 · 04","en":"BUILDING AND ARGUING: the general act, and the same act performed on rival positions.","cn":"构建与论辩：一般性的动作，以及同一动作施于对立立场。"},{"senses":"02","en":"IN THE FLASK: separate substances made to react under control.","cn":"在烧瓶里：分离的物质在受控条件下被迫反应。"},{"senses":"03","en":"IN THE CELL: the same building done by an organism without a chemist.","cn":"在细胞里：同一件构建之事由生物体完成，无需化学家。"},{"senses":"05 · 07","en":"MADE INTO SOUND: phonemes into a voice, recorded noise into one texture.","cn":"造出声音：音素合成人声，录下的噪音合成一种质感。"},{"senses":"06 · 08","en":"MANY SOURCES, ONE ACCOUNT: studies compressed, and disciplines brought into one paper.","cn":"多来源、一份说明：研究被压缩，学科被带进同一篇论文。"}]},"affixes":{"intro":{"en":"Synthesize is a noun-derived verb carrying a suffix that means 'to make', so it reads as 'make a putting-together'.","cn":"synthesize 是由名词派生的动词，带一个意为「使成为」的词尾，因此可读作「使一次放到一起发生」。"},"latinIntro":{"en":"Greek supplied both the noun and the verb ending; Latin passed them on, and English made the combination its own.","cn":"希腊语提供了名词与动词词尾；拉丁语把它们传出，英语把这套组合变成了自己的词。"},"items":[{"word":"syn-","structure":"syn- (Greek prefix, 'together')","meaning":"together","meaningCN":"一起","example":"The prefix gathers the parts.","exampleCN":"这个前缀把各部分聚拢。"},{"word":"tithenai","structure":"tithenai (Greek verb, 'to place')","meaning":"to place","meaningCN":"放置","example":"The root is the act of setting down.","exampleCN":"这个词根是放下的动作。"},{"word":"-sis","structure":"-sis (Greek noun-of-action ending)","meaning":"the act of","meaningCN":"……的行为","example":"The ending makes the placing into a process.","exampleCN":"这个词尾把「放置」变成一个过程。"},{"word":"synthesis","structure":"syn- + tithenai + -sis","meaning":"a putting together","meaningCN":"放到一起","example":"Synthesis is the noun behind the verb.","exampleCN":"synthesis 是这个动词背后的名词。"},{"word":"-ize","structure":"-izein (Greek verb ending, 'to make, act')","meaning":"to make, to act","meaningCN":"使成为；施行","example":"The ending turns the noun into what someone does.","exampleCN":"这个词尾把名词变成某人做的事。"},{"word":"synthesize","structure":"synthesis + -ize","meaning":"to make by combining","meaningCN":"通过组合造出","example":"Chemists synthesize the compound.","exampleCN":"化学家合成这种化合物。"},{"word":"synthesizer","structure":"synthesize + -er (agent)","meaning":"one that synthesizes","meaningCN":"合成者；合成器","example":"The synthesizer turns text into sound.","exampleCN":"合成器把文字变成声音。"},{"word":"synthetic","structure":"synthesis + -tic (adjective)","meaning":"combined; artificial","meaningCN":"合成的；人造的","example":"The fibre is synthetic.","exampleCN":"这种纤维是合成的。"},{"word":"resynthesize","structure":"re- + synthesize","meaning":"to build again after breaking down","meaningCN":"分解后重新合成","example":"The cell resynthesizes the molecule after use.","exampleCN":"用完之后，细胞重新合成这个分子。"}],"latinEntries":[{"word":"synthesis","structure":"synthesis, synthesis (f., third declension, from Greek)","meaning":"a composition","meaningCN":"组合；合成"},{"word":"syntheticus","structure":"syntheticus, synthetice (adj., late Latin, from Greek)","meaning":"of composition","meaningCN":"组合的"}],"derivatives":[{"word":"synthesis","pos":"n.","zh":"综合；合成（本词的动词所对应的名词，指过程或结果）"},{"word":"synthesizer","pos":"n.","zh":"合成器；综合者（动词加表施动者或器具的后缀）"},{"word":"synthetic","pos":"adj.","zh":"合成的；人造的（希腊形容词后缀，指「由组合而成」）"},{"word":"resynthesize","pos":"v.","zh":"重新合成（前缀「再」加本词，指在分解之后重建）"}]}}]);
